/* Gidsen — gemaakt uit de kennisbank (20 Website-content/Gidsen) door .scripts/gidsen_js.py op 2026-10-08. Niet met de hand bewerken. */
var GIDSEN={"bottelaar":{"adelphi":{"id":"adelphi","soort":"bottelaar","t":"Adelphi: een oude naam, een nieuwe distilleerderij","k":"Adelphi draagt de naam van een verdwenen distilleerderij in Glasgow. Sinds 1993 is het een onafhankelijke bottelaar, en sinds 2014 heeft het met Ardnamurchan een eigen distilleerderij.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Adelphi is een Schotse onafhankelijke bottelaar.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De naam is ouder dan het bedrijf. In de 19de eeuw stond in de Gorbals, een wijk van Glasgow, de Adelphi-distilleerderij van de broers Charles en David Gray.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Die stopte begin 20ste eeuw met distilleren.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In 1993 blies Jamie Walker, een nazaat van een latere eigenaar, de naam nieuw leven in als bottelaar.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Dat betekent: het huidige Adelphi zet de naam voort, niet de oude distilleerderij.</p>","html":"<h2>Eigenaren</h2><p>In 2004 kochten Keith Falconer en Donald Houston het bedrijf.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het Britse bedrijfsregister laat zien dat Walker op 1 juni 2004 vertrok en dat Falconer en Houston toen bestuurder werden.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Keith Falconer stopte in 2022.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Sinds 2023 staat James Falconer als grootaandeelhouder in het register, naast Donald Irwin-Houston.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><h2>Ardnamurchan</h2><p>In juli 2014 opende Princess Anne de Ardnamurchan-distilleerderij in de West-Highlands.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Die hoort bij Adelphi Distillery Ltd.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> De distilleerderij staat op het landgoed van Houston.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens de producent is Ardnamurchan 'established in 2014'.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Flessen van Ardnamurchan zelf dragen namen als AD / Single Malt en AD / Cask Strength Release.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> In de praktijk zijn dat dus geen onafhankelijke bottelingen, maar whisky van Adelphi's eigen distilleerderij.</p><h2>Wat Adelphi bottelt</h2><p>Adelphi richt zich op <span class=\"wl\" data-n=\"Single cask\">single casks</span>, zonder <span class=\"wl\" data-n=\"Chill filtration\">koudfiltratie</span> en zonder kleurstof.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens een tweede bron zijn ze vaak op <span class=\"wl\" data-n=\"Cask strength\">vatsterkte</span> gebotteld.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Onder de naam Fascadale verschijnen kleine batches uit eilanddistilleerderijen die niet bij naam genoemd worden.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><p>Adelphi bottelt niet alleen Schotse whisky. Er is bijvoorbeeld een fles van het Duitse <span class=\"wl\" data-n=\"St. Kilian\">St. Kilian</span> uit 2017.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Een fles met 'Glasgow' in de naam komt van The Glasgow Distillery Co., niet van de oude Adelphi-distilleerderij.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup></p><h2>Nog niet uitgezocht</h2><ul><li>Het precieze oprichtingsjaar van de oude distilleerderij: bronnen noemen 1825 en 1826.</li><li>Hoe de huidige series officieel heten; de eigen website van Adelphi verwijst nu door naar Ardnamurchan.</li><li>Of vatsterkte een vaste regel is of per vat verschilt.</li></ul>","bronnen":[{"n":"Scotchwhisky.com - Whiskypedia Adelphi Distillery","t":"Whiskypedia — Adelphi Distillery","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/whiskypedia/2660/adelphi-distillery/","j":""},{"n":"Wikipedia - Adelphi distillery","t":"Adelphi distillery","o":"Wikipedia","q":"E","u":"https://en.wikipedia.org/wiki/Adelphi_distillery","j":""},{"n":"Companies House - Adelphi Distillery Limited SC141800","t":"ADELPHI DISTILLERY LIMITED (SC141800) — officers, PSC","o":"Companies House (UK)","q":"A","u":"https://find-and-update.company-information.service.gov.uk/company/SC141800/persons-with-significant-control","j":"2026-10-08"},{"n":"The Spirits Business 2014 - Princess Anne opens new Scotch distillery","t":"Princess Anne opens new Scotch distillery","o":"The Spirits Business","q":"C","u":"https://www.thespiritsbusiness.com/2014/07/princess-anne-opens-new-scotch-distillery","j":"2014-07-28"},{"n":"Ardnamurchan Distillery - Homepage","t":"Ardnamurchan Distillery — homepage","o":"Ardnamurchan Distillery (Adelphi Distillery Ltd)","q":"D","u":"https://ardnamurchandistillery.com/","j":""},{"n":"The Whiskey Wash 2026 - A History of Adelphi Distillers","t":"A History of Adelphi Distillers: From Glasgow Roots to a Highland Revival","o":"The Whiskey Wash (Richard Hawley)","q":"E","u":"https://thewhiskeywash.com/whiskey-articles/a-history-of-adelphi-distillers-from-glasgow-roots-to-a-highland-revival/","j":"2026-02-04"},{"n":"The Whisky Exchange - St Kilian 2017 6 Year Old Cask 5161 Adelphi","t":"St Kilian 2017 Unpeated / 6 Year Old / Cask 5161 / Adelphi","o":"The Whisky Exchange","q":"E","u":"https://www.thewhiskyexchange.com/p/88032/st-kilian-2017-unpeated-6-year-old-cask-5161-adelphi","j":""},{"n":"Master of Malt - Glasgow 10 Years Old 2016 Cask 845 Adelphi","t":"Glasgow 10 Year Old 2016 Cask 845 (Adelphi)","o":"Master of Malt","q":"E","u":"https://www.masterofmalt.com/whiskies/the-glasgow-distillery-co/glasgow-10-year-old-2016-cask-845-adelphi-whisky/","j":""}],"kennis":["Adelphi"]},"berry-bros-rudd":{"id":"berry-bros-rudd","soort":"bottelaar","t":"Berry Bros & Rudd: een Londense wijnhandel met een whiskyverleden","k":"Berry Bros & Rudd is een Londense wijn- en drankhandel uit 1698. Het bedrijf bedacht ooit Cutty Sark en bottelt nu whisky onder eigen naam.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Berry Bros &amp; Rudd is een wijn- en drankhandel in Londen. Het bedrijf bestaat sinds 1698 en zit nog altijd op No. 3 St James's Street.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het is een familiebedrijf.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Volgens het bedrijf zelf begon het als kruidenierszaak van een weduwe Bourne.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> In whisky speelde Berry Bros drie rollen. Het bedacht de blend Cutty Sark, het was een tijd eigenaar van het merk The Glenrothes, en het bottelt whisky onder eigen naam.</p>","html":"<h2>Cutty Sark en The Glenrothes</h2><p>In 1923 maakten Francis Berry, Walter Berry en Hugh Rudd de blend Cutty Sark.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De naam komt van een beroemd Brits zeilschip.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Cutty Sark werd vooral in de Verenigde Staten populair.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In 2010 ruilde Berry Bros Cutty Sark met <span class=\"wl\" data-n=\"Edrington\">Edrington</span>. Edrington kreeg Cutty Sark, Berry Bros kreeg het merk The Glenrothes.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> De distilleerderij zelf bleef van Edrington.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> In 2017 kocht Edrington het merk weer terug.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Meer over de distilleerderij lees je bij <span class=\"wl\" data-n=\"Glenrothes\">Glenrothes</span>.</p><h2>Bottelen onder eigen naam</h2><p>Berry Bros is ook een onafhankelijke bottelaar: het koopt vaten van distilleerderijen en bottelt die onder eigen naam. Volgens het bedrijf verkoopt het al meer dan een eeuw sterke drank onder eigen label.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Het noemt zichzelf een van de vroegste onafhankelijke bottelaars.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Dat is een claim van Berry Bros zelf.</p><p>In de winkel en in onze catalogus zie je vooral deze reeksen:</p><ul><li><b>Losse vaten en jaargangen.</b> De naam begint met de distilleerderij en het jaar van distillatie, bijvoorbeeld \"Ledaig 2009 Berry Bros &amp; Rudd\". Vaak gaat het om een <span class=\"wl\" data-n=\"Single cask\">single cask</span>.</li><li><b>Classic Range.</b> Single malts per streek of land, zoals Speyside, Islay en Ierland. Sinds 2024 hebben de Speyside-flessen een leeftijd.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></li><li><b>The Perspective Series.</b> Blended Scotch van 21, 25, 35 en 40 jaar. Op elk etiket staat een foto van een Schots landschap van fotograaf Lindsay Robertson.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup></li><li><b>Exceptional Casks.</b> Een reeks met zeer oude vaten, zoals een North British single grain van 50 jaar.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup></li></ul><p>De flessen komen van veel verschillende distilleerderijen. Waar de whisky vandaan komt, lees je dus bij de distilleerderij op het etiket, niet bij Berry Bros.</p><h2>Nog niet uitgezocht</h2><ul><li>Sinds wanneer Berry Bros losse vaten onder eigen naam bottelt. Dat weten we nu alleen van het bedrijf zelf.</li><li>Wat 'Friend Bottling' en 'For Craft Spirits' op sommige etiketten betekenen.</li></ul>","bronnen":[{"n":"The Spirits Business 2020 - Berry Bros & Rudd a brand history","t":"Berry Bros & Rudd: a brand history","o":"The Spirits Business","q":"C","u":"https://www.thespiritsbusiness.com/2020/01/berry-bros-rudd-a-brand-history/","j":"2020-01-28"},{"n":"Berry Bros & Rudd - Our history","t":"Our history","o":"Berry Bros & Rudd","q":"D","u":"https://bbr.com/about/history","j":""},{"n":"Scotchwhisky.com 2018 - Cutty Sark sold to Glen Moray owner","t":"Cutty Sark sold to Glen Moray owner","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/magazine/latest-news/21864/cutty-sark-sold-to-glen-moray-owner/","j":"2018-11-28"},{"n":"Scotchwhisky.com 2017 - Glenrothes sold back to Edrington","t":"Glenrothes sold back to Edrington","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/magazine/latest-news/13681/glenrothes-sold-back-to-edrington/","j":"2017-05-02"},{"n":"Berry Bros & Rudd - London Shop Spirits Room","t":"London Shop: Spirits Room","o":"Berry Bros & Rudd","q":"D","u":"https://www.bbr.com/about/london-shop-fine-spirits","j":""},{"n":"Whisky Magazine 2024 - Berry Bros & Rudd refreshes its Classic Single Malts range","t":"Berry Bros & Rudd refreshes its Classic Single Malts range","o":"Whisky Magazine","q":"C","u":"https://whiskymag.com/articles/berry-bros-rudd-refreshes-its-classic-single-malts-range/","j":"2024-04-23"},{"n":"Scotchwhisky.com 2019 - Berry Bros launches new Perspective Series","t":"Berry Bros launches new Perspective Series","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/magazine/latest-news/24652/berry-bros-launches-new-perspective-series/","j":"2019-03-13"},{"n":"Harpers 2014 - Berry Bros releases Exceptional Cask Collection","t":"Berry Bros releases Exceptional Cask Collection going back 50 years","o":"Harpers Wine & Spirit","q":"C","u":"https://cdn796.pressflex.net/news/fullstory.php/aid/16289/Berry_Bros_releases_Exceptional_Cask_Collection_going_back_50_years.html","j":"2014-10-27"}],"kennis":["Berry Bros & Rudd","Edrington","Glenrothes","Single cask"]},"blackadder":{"id":"blackadder","soort":"bottelaar","t":"Blackadder: whisky met het bezinksel er nog in","k":"Blackadder is een Britse familiebottelaar uit 1995. De bekendste reeks, Raw Cask, bottelt single casks met vatbezinksel in de fles.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Blackadder is een onafhankelijke bottelaar en familiebedrijf dat vooral losse vaten op vatsterkte bottelt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het bedrijf staat sinds 7 maart 1995 ingeschreven in het Britse handelsregister.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Oprichters waren Robin Tucek en John Lamond.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Lamond vertrok in 2001; Tucek bleef eigenaar.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het is een familiebedrijf: dochter Hannah kwam in 2005 in de zaak.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens de producent werkt ook zoon Michael er sinds 2014.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> De naam verwijst naar bisschop John Blackadder.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p>","html":"<h2>Wat is Raw Cask?</h2><p>Raw Cask is de bekendste reeks, gestart in 2000.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Het is een merknaam van Blackadder, geen wettelijke term. Blackadder bottelt hier één vat tegelijk, een <span class=\"wl\" data-n=\"Single cask\">single cask</span>, meestal op <span class=\"wl\" data-n=\"Cask strength\">cask strength</span>: de sterkte waarmee de whisky uit het vat komt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het opvallende is wat er nog in de fles zit. De producent spreekt van whisky 'met vatbezinksel'.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Een vakbron schrijft dat er bewust vatdepot meekomt, met minimale filtratie.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Een andere bron zegt dat er zelfs niet mechanisch gefilterd wordt, zodat er houtdeeltjes in de fles kunnen zitten.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Hoeveel er precies gefilterd wordt, verschilt dus per bron. Zie je vlokjes in een Raw Cask-fles? Dan is dat in de praktijk de bedoeling, geen fout.</p><p>Volgens de producent wordt er nooit <span class=\"wl\" data-n=\"Chill filtration\">koudgefiltreerd</span> en geen kleurstof toegevoegd.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Een vakbron bevestigt: geen kleurstof en weinig filtratie.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>De andere reeksen</h2><p>Naast Raw Cask heeft Blackadder veel eigen labels.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></p><ul><li><b>Statement</b>: volgens de producent een trede boven Raw Cask.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b>Peat Reek</b> en <b>Peat Reek Embers</b>: zwaar geturfde malts, meestal van <span class=\"wl\" data-n=\"Islay\">Islay</span>; Embers zijn geselecteerde vaten, soms met een extra finish.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b>Smoking Islay</b>: een Islay-malt waarvan de distilleerderij niet genoemd wordt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b>Black Snake</b>: één groot vat dat telkens deels wordt gebotteld en weer bijgevuld; elke tapping heet een 'Venom'.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li><li><b>Red Snake</b>: volgens de producent komt elke fles uit één first fill ex-bourbonvat, soms met een finish.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b>Sherry Snake</b>: uit first fill sherryvaten.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b>Chimera</b>: vatted malts, dus malt van meerdere distilleerderijen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li></ul><p>Blackadder bottelt ook whisky van buiten Schotland, zoals <span class=\"wl\" data-n=\"St. Kilian\">St. Kilian</span> uit Duitsland, en daarnaast rum.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></p><h2>Ingelred: wel in de buurt, geen Blackadder-reeks</h2><p>Op sommige flessen staat 'Ingelred' naast de naam Blackadder. Volgens een Amerikaanse importeur is Ingelred een apart merk van een andere bottelaar, dat via Blackadder wordt geleverd.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Blackadder zelf noemt Ingelred niet bij zijn merken.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Wie Ingelred precies maakt, weten we nog niet.</p><h2>Nog niet uitgezocht</h2><ul><li>Wie de eigenaar en bottelaar van Ingelred is.</li><li>Waar Blackadder nu werkt: het register noemt Hastings, een vakbron Coulsdon.</li><li>Wat codes als 'RN154' bij Red Snake betekenen.</li></ul>","bronnen":[{"n":"Scotchwhisky.com - Whiskypedia Blackadder International","t":"Blackadder International (Whiskypedia)","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/whiskypedia/2216/blackadder-international/","j":"onbekend"},{"n":"Companies House - Blackadder International Limited 03030363","t":"Blackadder International Limited (03030363) — Companies House","o":"Companies House (UK Government)","q":"A","u":"https://find-and-update.company-information.service.gov.uk/company/03030363","j":""},{"n":"Wikipedia - Blackadder whisky bottler","t":"Blackadder (whisky bottler) — Wikipedia","o":"Wikipedia","q":"C","u":"https://en.wikipedia.org/wiki/Blackadder_(whisky_bottler)","j":""},{"n":"Blackadder International - Website introductie team en merken","t":"Blackadder International — website (introductie, The Team, Our Brands)","o":"Blackadder International Ltd","q":"D","u":"https://blackadder.com/","j":""},{"n":"Glass Revolution - Ingelred Ben Nevis cask 384","t":"Ingelred Ben Nevis Cask","o":"Glass Revolution Imports","q":"E","u":"https://www.glassrev.com/all-spirits/ingelred-ben-nevis-384","j":""}],"kennis":["Blackadder International"]},"boutique-y":{"id":"boutique-y","soort":"bottelaar","t":"That Boutique-y Whisky Company: getekende etiketten, genummerde batches","k":"That Boutique-y Whisky Company is een onafhankelijke bottelaar die in 2012 door de Britse webwinkel Master of Malt werd gestart. Het label koopt whisky van distilleerderijen en bottelt die onder eigen naam.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>That Boutique-y Whisky Company is een onafhankelijke bottelaar. Zo'n bedrijf heeft geen eigen distilleerderij, maar koopt vaten whisky in en bottelt die onder eigen naam. Het label werd in 2012 gelanceerd door de online drankwinkel Master of Malt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens Master of Malt gebeurde dat op het whiskyfestival Maltstock in Nijmegen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Je herkent de flessen aan de getekende, vaak grappige etiketten.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In deze gids lees je hoe het label ontstond, hoe de flessen heten en bij wie het bedrijf nu hoort.</p>","html":"<h2>Hoe het begon</h2><p>In september 2012 bracht Master of Malt de eerste vier whisky's uit, van <span class=\"wl\" data-n=\"Ardbeg\">Ardbeg</span>, <span class=\"wl\" data-n=\"Macallan\">The Macallan</span>, Caperdonich en <span class=\"wl\" data-n=\"Port Ellen\">Port Ellen</span>.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het ging om kleine oplagen ('small batches') in flessen van 500 ml, zonder leeftijd op het etiket.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Kort daarna volgde een tweede reeks, onder meer van BenRiach, <span class=\"wl\" data-n=\"Aberlour\">Aberlour</span> en <span class=\"wl\" data-n=\"Aultmore\">Aultmore</span>.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></p><p>Waarom een apart label? Volgens Master of Malt had de winkel geen manier om single malts uit te brengen met de naam van de distilleerderij erop.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> De naam Master of Malt staat niet op het etiket, zodat ook andere winkels de flessen kunnen verkopen, aldus de oprichter.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Als oprichter noemt Master of Malt Ben Ellefsen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><h2>Hoe de flessen heten</h2><p>Bij de start kreeg elke whisky de naam van de distilleerderij plus een batchnummer: de eerste vier heetten allemaal 'Batch 1'.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> De etiketten waren met de hand getekend en per fles genummerd.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Op elke tekening staat een verwijzing naar een verhaal of legende rond de distilleerderij, volgens de oprichter.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Master of Malt noemt Emily Chappell als tekenaar.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><p>Een leeftijd stond er niet op. Volgens de oprichter liepen de leeftijden binnen één batch te ver uiteen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Zo'n whisky zonder leeftijdsvermelding heet in het vak een <span class=\"wl\" data-n=\"NAS\">NAS</span>-whisky.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Het ontbreken van een leeftijd zegt niets over de kwaliteit.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></p><p>Of dit nog steeds de vaste opbouw van de namen is, en welke series er nu zijn, hebben we nog niet uitgezocht.</p><h2>Waar komt de whisky vandaan?</h2><p>Een onafhankelijke bottelaar bottelt whisky van andere distilleerderijen. Op deze site volgt de herkomst van een fles daarom de distilleerderij op het etiket, niet de bottelaar.</p><h2>Bij wie het hoort</h2><p>That Boutique-y Whisky Company hoort bij Atom Group, samen met Master of Malt.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Bierbrouwer AB InBev kocht Atom Group rond 2018 en verkocht het in augustus 2024 terug aan oprichter Justin Petszaft.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Wat er sinds 2024 veranderde, weten we nog niet.</p><h2>Nog niet uitgezocht</h2><ul><li>Welke series en flesmaten het label nu voert.</li><li>Een onafhankelijke bron voor de lancering op Maltstock.</li><li>Wie de etiketten nu tekent.</li><li>Veranderingen na de verkoop in 2024.</li></ul>","bronnen":[{"n":"The Spirits Business 2012 - Scotch distilleries feature in Master of Malt range","t":"Scotch distilleries feature in Master of Malt range","o":"The Spirits Business","q":"C","u":"https://www.thespiritsbusiness.com/?p=6216","j":"2012-09-14"},{"n":"Master of Malt 2022 - A short history of That Boutique-y Whisky Company","t":"A short history of That Boutique-y Whisky Company","o":"Master of Malt","q":"D","u":"https://www.masterofmalt.com/blog/post/a-short-history-of-that-boutique-y-whisky-company.aspx","j":"2022-09-27"},{"n":"Master of Malt 2012 - That Boutique-y Whisky Company a new independent bottling label","t":"That Boutique-y Whisky Company — a new independent bottling label","o":"Master of Malt","q":"D","u":"https://www.masterofmalt.com/blog/post/that-boutique-y-whisky-company-a-new-independent-bottling-label/","j":"2012-09-12"},{"n":"Whisky Israel 2012 - Whisky Newsflash 16 november","t":"Whisky Newsflash for Nov 16th 2012","o":"Whisky Israel (blog)","q":"E","u":"https://www.whiskyisrael.co.il/?p=7483","j":"2012-11-16"},{"n":"Edinburgh Whisky Academy 2023 - No Age Statement","t":"Whisky words: No Age Statement (NAS)","o":"Edinburgh Whisky Academy","q":"C","u":"https://www.edinburghwhiskyacademy.com/blogs/definition/whisky-words-no-age-statement-nas","j":"2023-08-16"},{"n":"Global Drinks Intel 2024 - AB InBev sells Atom Group to founder","t":"Anheuser-Busch InBev sells Atom Group back to founder","o":"Global Drinks Intel","q":"C","u":"https://drinks-intel.com/news/anheuser-busch-inbev-sells-atom-group-to-company-founder/","j":"2024-08-07"}],"kennis":["That Boutique-y Whisky Company","NAS"]},"coopers-choice":{"id":"coopers-choice","soort":"bottelaar","t":"Cooper's Choice: de single casks van The Vintage Malt Whisky Company","k":"Cooper's Choice is de single cask-reeks van The Vintage Malt Whisky Company uit Milngavie bij Glasgow, in 1992 opgericht door Brian Crook.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>The Cooper's Choice is een reeks <span class=\"wl\" data-n=\"Single cask\">single cask</span>-bottelingen: elke fles komt uit één vat.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De reeks is van The Vintage Malt Whisky Company, een onafhankelijke bottelaar uit Milngavie, vlak bij Glasgow.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Brian Crook richtte het bedrijf in 1992 op.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Daarvoor was hij jarenlang exportdirecteur bij een grote Schotse whiskyproducent.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Het is een familiebedrijf: zijn zoon Andrew Crook werkt mee.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p>","html":"<h2>Hoe het bedrijf groeide</h2><p>In 1997 kwamen de merken van Highlands &amp; Islands Scotch Whisky Co bij de groep.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In 2005 nam het bedrijf C.S. James &amp; Sons over, de maker van Islay Storm.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Naast Cooper's Choice brengt het bedrijf merken als Finlaggan en The Ileach uit, single malts van <span class=\"wl\" data-n=\"Islay\">Islay</span>.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In 2016 kreeg het de titel 'Lowland Independent Bottler of the Year' in een wedstrijd van Whisky Magazine.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><h2>Wat staat er op de fles?</h2><p>Cooper's Choice bottelt whisky van veel verschillende distilleerderijen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens een whiskykennisbank gaat het om kleine oplagen met verschillende vatfinishes, niet <span class=\"wl\" data-n=\"Chill filtration\">koudgefiltreerd</span> en zonder kleurstof.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Een finish betekent dat de whisky aan het eind nog een tijd in een ander vat ligt, bijvoorbeeld een portvat. Volgens een Australische winkel komen de meeste vaten van Amerikaans eiken dat eerder bourbon bevatte, met finishes in onder meer port-, sherry-, madeira- en wijnvaten.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></p><p>Binnen de reeks zijn er twee namen die je op het etiket kunt tegenkomen:</p><ul><li><b>Golden Cut</b>: een premiumlijn op 50%, met single casks en kleine batches van malt en grain.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li><b>Golden Grains</b>: oude single grains.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li></ul><p>Waar komt de naam vandaan? Volgens een winkel eert de naam de kuiper (in het Engels: cooper), de vakman die vaten maakt.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Dat klinkt als een uitleg van de producent; een eigen bron van het bedrijf hebben we daarvoor nog niet.</p><h2>Nog niet uitgezocht</h2><ul><li>Sinds wanneer de reeks Cooper's Choice bestaat.</li><li>Welke distilleerderij achter flessen zonder distilleerderijnaam zit, zoals 'Secret Orkney'.</li><li>De gegevens in het Britse handelsregister.</li></ul>","bronnen":[{"n":"Scotchwhisky.com - Whiskypedia The Vintage Malt Whisky Co","t":"The Vintage Malt Whisky Co (Whiskypedia)","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/whiskypedia/2282/the-vintage-malt-whisky-co/","j":"onbekend"},{"n":"Whisky.com - Vintage Malt Whisky Company","t":"Vintage Malt Whisky Company Ltd. — Whisky.com independent bottlers","o":"Whisky.com","q":"C","u":"https://www.whisky.com/independent-bottlers/vintage-malt-whisky-company-ltd.html","j":""},{"n":"Vintage Malt Whisky Company - About","t":"About — The Vintage Malt Whisky Company","o":"The Vintage Malt Whisky Company Limited","q":"D","u":"https://www.vintagemaltwhisky.com/about/","j":""},{"n":"Select Scotch Whisky - The Cooper's Choice","t":"The Cooper's Choice whisky by The Vintage Malt Whisky Company — Select Scotch Whisky","o":"Select Scotch Whisky (Australië)","q":"E","u":"https://www.selectscotchwhisky.com.au/pages/the-coopers-choice-whisky-by-the-vintage-malt-whisky-company","j":""}],"kennis":["The Vintage Malt Whisky Company"]},"douglas-laing":{"id":"douglas-laing","soort":"bottelaar","t":"Douglas Laing: familiebottelaar uit Glasgow","k":"Douglas Laing bottelt sinds 1948 whisky vanuit Glasgow. Op het etiket herken je het bedrijf aan series als Old Particular en Provenance, of aan blended malts als Big Peat.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Douglas Laing is een onafhankelijke bottelaar en blender uit Glasgow, opgericht in 1948.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De oprichter kocht na zijn tijd bij de RAF het blendmerk King of Scots.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Het bedrijf is nog steeds van de familie Laing.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Volgens het Britse bedrijfsregister heeft Frederick Hamilton Laing meer dan de helft van de aandelen.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Zijn dochter Cara Laing leidt het bedrijf als derde generatie.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Sinds 2019 heeft Douglas Laing ook een eigen distilleerderij: Strathearn in Perthshire.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup></p>","html":"<h2>Twee broers, twee bedrijven</h2><p>De broers Fred en Stewart Laing leidden het familiebedrijf zo'n veertig jaar samen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> In 2013 gingen ze uit elkaar en verdeelden ze de merken.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Stewart begon een nieuw bedrijf, Hunter Laing &amp; Co.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Hij nam onder meer Old Malt Cask en de Old &amp; Rare-reeks mee.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Fred hield onder meer Provenance, Premier Barrel en Big Peat.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Dat betekent voor jou: een fles Old Malt Cask van na 2013 komt van Hunter Laing, niet van Douglas Laing.</p><h2>Series op het etiket</h2><ul><li><b>Old Particular</b>: <span class=\"wl\" data-n=\"Single cask\">single casks</span>, gelanceerd in september 2013, zonder kleurstof en zonder <span class=\"wl\" data-n=\"Chill filtration\">koudfiltratie</span>.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Bij de start werden 18-jarigen op 48,4% gebotteld en oudere vaten op 51,5%; enkele bijzondere vaten op <span class=\"wl\" data-n=\"Cask strength\">vatsterkte</span>.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup></li><li><b>Xtra Old Particular (XOP)</b>: oudere en zeldzame vaten, op vatsterkte.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b>Provenance</b>: single casks of kleine batches op 46%, niet koudgefilterd en zonder kleurstof.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b>Premier Barrel</b>: jongere single casks in een decanterachtige fles.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b>Remarkable Regional Malts</b>: <span class=\"wl\" data-n=\"Blended Malt Scotch Whisky\">blended malts</span> die elk een Schotse streek vertegenwoordigen, zoals Big Peat (Islay, sinds 2009), Scallywag, Timorous Beastie, Rock Island, The Epicurean en The Gauldrons.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-9\">9</a></sup></li></ul><p>Vaak staat 'Douglas Laing' niet in de productnaam, maar alleen 'Old Particular' of 'Provenance'.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Aan die serienaam herken je de bottelaar toch.</p><h2>Strathearn</h2><p>Douglas Laing kocht Strathearn in oktober 2019; de distilleerderij produceerde sinds 2013.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> In 2024 kwam de eerste Strathearn Single Malt van Douglas Laing uit, op 50%, niet koudgefilterd en zonder kleurstof.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></p><h2>Nog niet uitgezocht</h2><ul><li>Op welke sterkte Old Particular nu wordt gebotteld; onze bron is van 2013.</li><li>Of de geplande distilleerderij in Glasgow er al is.</li></ul>","bronnen":[{"n":"Scotchwhisky.com - Whiskypedia Douglas Laing & Company","t":"Whiskypedia — Douglas Laing & Company","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/whiskypedia/2228/douglas-laing-company/","j":""},{"n":"DRAM Scotland 2013 - Fred Laing takes control at Douglas Laing","t":"Fred Laing takes control at Douglas Laing & Co","o":"DRAM Scotland (DRAM News Team)","q":"C","u":"https://dramscotland.co.uk/2013/05/01/fred-laing-takes-control-at-douglas-laing-co","j":"2013-05-01"},{"n":"The Spirits Business 2019 - Douglas Laing & Co a brand history","t":"Douglas Laing & Co: a brand history","o":"The Spirits Business (Tom Bruce-Gardyne)","q":"C","u":"https://www.thespiritsbusiness.com/2019/05/douglas-laing-co-a-brand-history/","j":"2019-05-21"},{"n":"Whisky.com - Douglas Laing (onafhankelijke bottelaar)","t":"Douglas Laing — independent bottler","o":"Whisky.com (Whisky.com Media GmbH & Co. KG)","q":"C","u":"https://whisky.com/independent-bottlers/douglas-laing.html","j":""},{"n":"Companies House - Douglas Laing & Company Limited SC027619","t":"DOUGLAS LAING & COMPANY LIMITED (SC027619) — overview, PSC","o":"Companies House (UK)","q":"A","u":"https://find-and-update.company-information.service.gov.uk/company/SC027619","j":"2026-10-08"},{"n":"Dramface 2024 - Douglas Laing launches inaugural Strathearn single malt","t":"Douglas Laing distilling debut with launch of Strathearn","o":"Dramface","q":"C","u":"https://www.dramface.com/news/2024/strathearn-douglas-laing-launch-inaugural","j":"2024-04-15"},{"n":"Drinks International 2019 - Douglas Laing acquires Strathearn Distillery","t":"Douglas Laing acquires Strathearn Distillery","o":"Drinks International","q":"C","u":"https://drinksint.com/news/fullstory.php/aid/8565/.html","j":"2019-10-24"},{"n":"DRAM Scotland 2013 - Old Particular Single Casks released by Douglas Laing","t":"Old Particular Single Casks released by Douglas Laing","o":"DRAM Scotland (DRAM News Team)","q":"C","u":"https://dramscotland.co.uk/2013/09/25/old-particular-single-casks-released-by-douglas-laing/","j":"2013-09-25"},{"n":"Douglas Laing - Homepage en assortiment","t":"Douglas Laing — homepage","o":"Douglas Laing & Co","q":"D","u":"https://www.douglaslaing.com/","j":""}],"kennis":["Douglas Laing"]},"duncan-taylor":{"id":"duncan-taylor","soort":"bottelaar","t":"Duncan Taylor: van vatmakelaar in Glasgow naar bottelaar in Huntly","k":"Duncan Taylor begon in 1938 in Glasgow als handelaar in vaten en bottelt nu vanuit Huntly. Je herkent het aan series als Battlehill, Octave en Dimensions.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Duncan Taylor begon in 1938 in Glasgow als makelaar en handelaar in whiskyvaten.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Wie het bedrijf oprichtte, vermelden de bronnen niet. Volgens een Duitse vakbron kwam dat op gang door samenwerking met de Amerikaanse verzamelaar Abe Rosenberg, die zo'n 4.500 vaten bezat.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Na zijn dood in 1994 werden die vaten verkocht en verzorgde Duncan Taylor de marketing en de botteling.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Tegenwoordig zit het bedrijf in Huntly, in Aberdeenshire.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p>","html":"<h2>Huntly</h2><p>Euan Shand, die eerder bij Glendronach werkte, nam het bedrijf rond de jaarwisseling 2001–2002 over en bracht het naar zijn geboorteplaats Huntly.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Het bedrijfsregister laat zien dat hij op 31 januari 2002 bestuurder werd.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In 2014 verhuisde Duncan Taylor binnen Huntly naar een groter pand aan King Street, voor blenden, opslag en bottelen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Wie er nu eigenaar is</h2><p>In 2021 waren Euan Shand en Shawn Smith de eigenaren.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Volgens het register heeft Shawn Smith sinds november 2020 via de holding 75% of meer van de aandelen.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Shand stopte in april 2024 als bestuurder en staat sinds mei 2024 niet meer als aandeelhouder van betekenis in het register.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></p><h2>Series op het etiket</h2><ul><li><b>Battlehill</b>: single malts en single grains, tot 55 jaar oud.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Een voorbeeld uit de handel is gebotteld op 46%.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></li><li><b>Dimensions</b>: whisky van 10 tot 40 jaar, met op het etiket de datum van distillatie, botteling en het vat.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li><b>Octave</b>: whisky die (na)gerijpt is in een octave, een vat van ongeveer 50 liter; op <span class=\"wl\" data-n=\"Cask strength\">vatsterkte</span>, niet <span class=\"wl\" data-n=\"Chill filtration\">koudgefilterd</span> en zonder kleurstof.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li><b>Tantalus</b>: malts en grains van minstens 40 jaar.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li><b>Rarest</b>: whisky van distilleerderijen die al lang gesloten zijn.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><b>Rare Auld Grain</b>: <span class=\"wl\" data-n=\"Single cask\">single cask</span> <span class=\"wl\" data-n=\"Grain whisky\">grain whisky</span>.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li></ul><p>Daarnaast maakt Duncan Taylor blends, zoals Black Bull.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Dat merk werd in 1864 voor het eerst geregistreerd en werd in 2009 door Shand nieuw leven ingeblazen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Nog niet uitgezocht</h2><ul><li>Wie Duncan Taylor in 1938 oprichtte.</li><li>Of de eigen distilleerderij in Huntly, gepland sinds 2007, er gekomen is.</li><li>Een vakbron over de kenmerken van Battlehill (sterkte, filtratie).</li></ul>","bronnen":[{"n":"Scotchwhisky.com - Whiskypedia Duncan Taylor Scotch Whisky","t":"Whiskypedia — Duncan Taylor Scotch Whisky","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/whiskypedia/2230/duncan-taylor-scotch-whisky/","j":""},{"n":"Whisky.com - Duncan Taylor (onafhankelijke bottelaar)","t":"Duncan Taylor — independent bottler","o":"Whisky.com (Whisky.com Media GmbH & Co. KG)","q":"C","u":"https://www.whisky.com/independent-bottlers/duncan-taylor.html","j":""},{"n":"Companies House - Duncan Taylor Scotch Whisky Limited SC036622","t":"DUNCAN TAYLOR SCOTCH WHISKY LIMITED (SC036622) — overview, officers, PSC","o":"Companies House (UK)","q":"A","u":"https://find-and-update.company-information.service.gov.uk/company/SC036622","j":"2026-10-08"},{"n":"Whisky Magazine 2021 - Ian Logan joins Duncan Taylor Scotch Whisky","t":"Ian Logan joins Duncan Taylor Scotch Whisky","o":"Whisky Magazine","q":"C","u":"https://www.whiskymag.com/articles/ian-logan-joins-duncan-taylor-scotch-whisky/","j":"2021-06-10"},{"n":"Companies House - Duncan Taylor & Company Holdings Limited SC226358","t":"DUNCAN TAYLOR & COMPANY HOLDINGS LIMITED (SC226358) — overview, PSC","o":"Companies House (UK)","q":"A","u":"https://find-and-update.company-information.service.gov.uk/company/SC226358/persons-with-significant-control","j":"2026-10-08"},{"n":"Master of Malt - Glenrothes 12 Year Old Battlehill Duncan Taylor","t":"Glenrothes 12 Year Old — Battlehill (Duncan Taylor)","o":"Master of Malt","q":"E","u":"https://www.masterofmalt.com/whiskies/glenrothes/glenrothes-12-year-old-battlehill-duncan-taylor-whisky/?sku=119601","j":""}],"kennis":["Duncan Taylor"]},"hart-brothers":{"id":"hart-brothers","soort":"bottelaar","t":"Hart Brothers: een familienaam uit de Schotse whiskyhandel","k":"Hart Brothers gaat terug op 1964, toen de broers Iain en Donald Hart een groothandel en blendbedrijf begonnen. Wie het bedrijf nu bezit, is nog onduidelijk.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Hart Brothers is een Schotse onafhankelijke bottelaar, gevestigd in East Kilbride bij Glasgow.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Het verhaal begint in 1964. Toen begonnen de broers Iain en Donald Hart een groothandel in wijn en gedistilleerd, die ook Scotch blendde.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Volgens het bedrijf zelf waren de Harts al eind 19e eeuw herbergiers in Paisley.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Een whiskykennisbank vertelt dat de broers begonnen als makelaar in whiskyvaten. Later kwamen er een eigen blend, een bottelarij en een pakhuis bij.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p>","html":"<h2>Van blender naar bottelaar van losse vaten</h2><p>In 1975 kwam de derde broer, Alistair Hart, in het bedrijf.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Samen met Donald ging hij geselecteerde losse vaten bottelen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Zo werd Hart Brothers een onafhankelijke bottelaar.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Volgens de producent gaat het om <span class=\"wl\" data-n=\"Single cask\">single casks</span>, zonder kleurstof en zonder <span class=\"wl\" data-n=\"Chill filtration\">koudfiltratie</span>, en wordt alleen water toegevoegd.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De producent schrijft ook dat het op vatsterkte bottelt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Dat is een opgave van de producent; kijk per fles naar de sterkte op het etiket.</p><p>Volgens de producent zijn er naast losse single malts ook reeksen als Legends, genummerde flessen in een houten kist, en de Dynasty Decanter. Daarnaast noemt het bedrijf categorieën als Islay Single Malt, Single Grain en <span class=\"wl\" data-n=\"Blended Malt Scotch Whisky\">Blended Malt</span>.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Wie is nu de eigenaar?</h2><p>Dat is minder duidelijk dan je zou verwachten. Volgens het handelsregister heette een Schotse vennootschap van 1998 tot 2007 Hart Brothers Limited. In 2007 kreeg die een nieuwe naam: nu heet ze Meadowside Blending Company Limited.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Een whiskykennisbank schrijft dat Hart Brothers in 2007 werd verkocht. Donald Hart en zijn zoon Andrew begonnen later Meadowside Blending, een eigen bottelaar.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Een veilinghuis noemt Alistair Hart echter nog als directeur van Hart Brothers.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Wie het merk nu voert, hebben we nog niet kunnen vaststellen.</p><p>Ook over het oprichtingsjaar zijn de bronnen het niet eens. Het bedrijf zelf noemt 1964.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het veilinghuis noemt 1988 als oprichtingsjaar van Hart Brothers en 1964 als begin van het eerdere familiebedrijf.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><h2>Nog niet uitgezocht</h2><ul><li>Wie Hart Brothers sinds 2007 bezit.</li><li>Of 1988 het begin is van een nieuwe onderneming.</li><li>Wat 'Finest Collection' precies is: alleen winkels en veilinghuizen noemen die naam.</li></ul>","bronnen":[{"n":"Hart Brothers - Our story","t":"Our Story — Hart Brothers","o":"Hart Brothers Limited","q":"D","u":"https://hartbrothers.co.uk/our-story/","j":""},{"n":"Whisky Auctioneer - Hart Brothers","t":"Hart Brothers — Whisky Auctioneer company profile","o":"Whisky Auctioneer","q":"E","u":"https://whiskyauctioneer.com/learn/explore-whisky/companies/hart-brothers","j":""},{"n":"Whisky.com - Meadowside Blending","t":"Meadowside Blending (bottelaarsprofiel)","o":"Whisky.com","q":"C","u":"https://www.whisky.com/independent-bottlers/medowside-blending.html","j":""},{"n":"Companies House - Meadowside Blending Company Limited SC093121","t":"Meadowside Blending Company Limited (SC093121) — Companies House","o":"Companies House (UK Government)","q":"A","u":"https://find-and-update.company-information.service.gov.uk/company/SC093121","j":""}],"kennis":["Hart Brothers"]},"infrequent-flyers":{"id":"infrequent-flyers","soort":"bottelaar","t":"Infrequent Flyers: de single casks van Alistair Walker","k":"Infrequent Flyers is het label van de Alistair Walker Whisky Company, een Schotse onafhankelijke bottelaar uit 2018. Het label bottelt losse vaten van veel verschillende distilleerderijen.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Infrequent Flyers is de naam die je op het etiket ziet. Het bedrijf erachter heet de Alistair Walker Whisky Company.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Het is een onafhankelijke bottelaar: een bedrijf zonder eigen distilleerderij dat vaten van anderen koopt en onder eigen naam bottelt.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Volgens het bedrijf en twee andere bronnen ging het van start in 2018.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Infrequent Flyers was de eerste reeks die Walker uitbracht. Een Belgische recensent besprak eind 2019 al de eerste batch van negen flessen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p>","html":"<h2>Wie is Alistair Walker?</h2><p>Alistair Walker werkte eerder bij de distilleerderij BenRiach.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Hij is een zoon van Billy Walker, die de distilleerderij GlenAllachie leidt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Walker zei bij de start dat hij veel houdt van wood finishes.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Een finish is een korte extra rijping in een ander vat, bijvoorbeeld een wijnvat, na de hoofdrijping.</p><h2>Wat het label kenmerkt</h2><p>Infrequent Flyers bottelt <span class=\"wl\" data-n=\"Single cask\">single casks</span>: alle flessen van één botteling komen uit één vat.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> De whisky komt van veel verschillende distilleerderijen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Volgens het bedrijf verwijst de naam naar vaten die je zelden tegenkomt, vaak van minder bekende distilleerderijen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Dat is de eigen uitleg van de bottelaar. Volgens Whiskybase en de eigen opgave bottelt het label meestal op natuurlijke sterkte, zonder kleurstof en zonder koudfiltratie.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Per fles staat dat op de productpagina, als de bottelaar het vermeldt.</p><p>In onze catalogus staat eerst de distilleerderij, dan leeftijd en jaar van distillatie, en dan 'Infrequent Flyers'. Een voorbeeld is \"Auchroisk 13 Years Old 2012 Infrequent Flyers\". Staat er \"Undisclosed Islay\", dan noemt de bottelaar de distilleerderij niet. Dat komt vaker voor bij onafhankelijke bottelaars. In de praktijk betekent het dat je alleen het eiland weet.</p><h2>Nog niet uitgezocht</h2><ul><li>Waar het bedrijf precies is gevestigd. Eén bron noemt Grangemouth, maar dat is nog niet bevestigd.</li><li>Of er naast Infrequent Flyers nog andere labels zijn.</li><li>Wat de nummers betekenen die winkels bij de flessen noemen.</li><li>Een bevestiging van het startjaar in vakpers of het Britse handelsregister.</li></ul>","bronnen":[{"n":"WhiskyNotes 2019 - Glen Keith 1993 Orkney 2003 Cameronbridge 1995 Infrequent Flyers","t":"Glen Keith 1993 // Orkney 2003 // Cameronbridge 1995 (Infrequent Flyers)","o":"WhiskyNotes (Ruben Luyten)","q":"C","u":"https://www.whiskynotes.be/?p=32767","j":"2019-10-09"},{"n":"The Whisky Barrel 2020 - New Alistair Walker Whisky Company","t":"NEW! Alistair Walker Whisky Company","o":"The Whisky Barrel (webwinkel)","q":"E","u":"https://www.thewhiskybarrel.com/blogs/news/new-alistair-walker-whisky-company","j":"2020-04-20"},{"n":"Independent Spirits Festival - Alistair Walker","t":"Alistair Walker (exposantenprofiel)","o":"Independent Spirits Festival","q":"D","u":"https://independentspirits.co.uk/exhibitor-list/alistair-walker","j":""},{"n":"Whiskybase - Alistair Walker Whisky Company","t":"Alistair Walker Whisky Company (bottelaarspagina)","o":"Whiskybase","q":"E","u":"https://www.whiskybase.com/whiskies/bottler/90498/about","j":""}],"kennis":["Alistair Walker Whisky Company","Single cask"]},"living-souls":{"id":"living-souls","soort":"bottelaar","t":"Living Souls: een jonge bottelaar uit Glasgow","k":"Living Souls is een Schotse onafhankelijke bottelaar uit Glasgow, in november 2024 gelanceerd door drie mensen uit de whiskybranche. Ze brengen whisky uit in batches van een paar flessen tegelijk.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Living Souls is een onafhankelijke bottelaar. Dat is een bedrijf dat zelf geen distilleerderij heeft, maar whisky van anderen inkoopt en onder eigen naam bottelt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Living Souls zit in Glasgow en is opgericht in 2024.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Het merk kwam in november 2024 op de markt met een eerste reeks van vier whisky's.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Achter het bedrijf staan drie mensen die al lang in de whiskywereld werken: John Torrance, Jamie Williamson en Calum Leslie.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Het is dus een heel jonge naam. Over de eerste jaren is nog weinig geschreven.</p>","html":"<h2>Wie erachter zitten</h2><p>Calum Leslie bedacht eerder het merk PeatReekers en werkte bij Loch Lomond Group.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Jamie Williamson richtte de drankdistributeur Kilninian op.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> John Torrance werkte onder meer bij Tullibardine.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het bedrijf achter het merk heet volgens gegevens uit het Britse handelsregister Whisky Souls Limited, met de drie oprichters als bestuurders.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Die gegevens hebben we nog niet in het register zelf gecontroleerd.</p><h2>Werken in batches</h2><p>Living Souls brengt whisky uit in genummerde batches. Batch #1 bestond uit een 15 jaar oude blend uit een solera-systeem, een 18 jaar oude Ledaig, een 19 jaar oude blended malt van Islay en een 40 jaar oude blend uit één vat.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Een solera is een systeem waarin steeds nieuwe whisky bij oudere whisky wordt bijgevuld. In het voorjaar van 2025 volgde een tweede reeks, met onder meer een Balblair van 10 jaar en een Dumbarton van 25 jaar.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Volgens het profiel op Whisky.com bottelt Living Souls zonder kleurstof en zonder koudfiltratie.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Per fles staat dat op de productpagina, als de bottelaar het vermeldt.</p><p>Op het etiket en in onze catalogus staat de naam van de distilleerderij, dan de leeftijd en dan 'Living Souls'. Een voorbeeld is \"Bowmore 22 Years Old Living Souls\". Bij een <span class=\"wl\" data-n=\"Single cask\">single cask</span> komen alle flessen uit één vat.</p><h2>Living Souls en Little Brown Dog</h2><p>Je ziet in de catalogus ook flessen met de naam <span class=\"wl\" data-n=\"Little Brown Dog\">Little Brown Dog</span>. Dat is een andere bottelaar, uit Aberdeenshire, in 2018 opgericht door Andrew Smith en Chris Reid.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> De twee bedrijven maakten samen één whisky: een blend van 46 jaar.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> De grain-whisky daarin kwam van Living Souls en de malt-whisky van Little Brown Dog.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Andere flessen van Little Brown Dog, zoals Drookit Dug, horen niet bij Living Souls.</p><h2>Nog niet uitgezocht</h2><ul><li>Welke batches er na het voorjaar van 2025 zijn verschenen.</li><li>De gegevens uit het Britse handelsregister zelf.</li><li>Wie van de oprichters eerder bij de bottelaar Douglas Laing werkte. De bronnen spreken elkaar daarover tegen.</li></ul>","bronnen":[{"n":"Whisky.com - Living Souls","t":"Living Souls (bottelaarsprofiel)","o":"Whisky.com","q":"C","u":"https://www.whisky.com/independent-bottlers/living-souls.html","j":""},{"n":"Meininger 2024 - Alba Import stellt Living Souls vor","t":"alba import stellt den neuen independent bottler living souls aus glasgow vor","o":"Meininger (Mixology/Meininger Verlag)","q":"C","u":"https://www.meininger.de/spirituosen/handel/alba-import-stellt-den-neuen-independent-bottler-living-souls-aus-glasgow-vor","j":"2024-12-18"},{"n":"Whisky Magazine 2024 - New independent bottler Living Souls launches with first collection","t":"New independent bottler Living Souls launches with first collection","o":"Whisky Magazine","q":"C","u":"https://whiskymag.com/articles/new-independent-bottler-living-souls-launches-with-first-collection/","j":"2024-11-05"},{"n":"Bottle of Italy - Whisky Souls Limited brand Living Souls","t":"Whisky Souls Limited – brand Living Souls (producentpagina)","o":"Bottle of Italy (webwinkel)","q":"E","u":"https://bottleofitaly.com/en/pages/produttore-whisky-souls-limited-brand-living-souls","j":""},{"n":"Dram Scotland 2025 - Living Souls launches latest collection of whiskies","t":"Living Souls launches latest collection of whiskies","o":"Dram Scotland","q":"C","u":"https://dramscotland.co.uk/2025/04/29/living-souls-launches-latest-collection-of-whiskies","j":"2025-04-29"},{"n":"The Whiskey Wash 2026 - Little Brown Dog launches Aberdeenshire single malt","t":"Little Brown Dog Launches Aberdeenshire Single Malt Whisky","o":"The Whiskey Wash","q":"C","u":"https://thewhiskeywash.com/whiskey-news/little-brown-dog-launches-aberdeenshire-single-malt-whisky/","j":"2026-04-28"},{"n":"Top Whiskies - Little Brown Dog x Living Souls 46 Year Old","t":"Little Brown Dog x Living Souls 46 Year Old","o":"Top Whiskies (webwinkel)","q":"E","u":"https://topwhiskies.com/products/little-brown-dog-x-living-souls-46-year-old","j":""}],"kennis":["Living Souls","Little Brown Dog","Single cask"]},"signatory-vintage":{"id":"signatory-vintage","soort":"bottelaar","t":"Signatory Vintage: de bottelaar die een distilleerderij kocht","k":"Signatory Vintage begon in 1988 in Edinburgh en zit sinds 2002 op de Edradour-distilleerderij in Pitlochry. Op het etiket vind je vaak een serienaam als Cask Strength Collection of Symington's Choice.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Signatory Vintage is een Schotse onafhankelijke bottelaar.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het bedrijf werd in augustus 1988 ingeschreven in het Schotse bedrijfsregister.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De oprichter is Andrew Symington.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens een Duitse vakbron begon hij samen met zijn broer, die hij later uitkocht.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> De naam komt volgens dezelfde bron van een plan dat nooit is uitgevoerd: elk etiket zou door een bekend persoon worden gesigneerd.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p>","html":"<h2>Van Edinburgh naar Pitlochry</h2><p>Signatory begon in de omgeving van Edinburgh. Over de precieze plek zijn de bronnen het niet eens: de ene noemt Newhaven, de andere Leith.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In 2002 kocht het bedrijf de Edradour-distilleerderij bij Pitlochry van Pernod Ricard.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Daarvoor richtte Symington een apart bedrijf op, The Edradour Distillery Company.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Sindsdien staan de bottelarij, de opslag en het kantoor van Signatory naast de distilleerderij.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In de praktijk is Signatory dus bottelaar én eigenaar van een distilleerderij. Edradour maakt ook een geturfde malt onder de naam Ballechin.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></p><h2>Series op het etiket</h2><p>Signatory werkt met series. Die vertellen je iets over hoe de whisky gebotteld is.</p><ul><li><b>Cask Strength Collection</b>: whisky op <span class=\"wl\" data-n=\"Cask strength\">vatsterkte</span>, dus niet met water verdund.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li><li><b>Un-Chillfiltered Collection</b>: niet <span class=\"wl\" data-n=\"Chill filtration\">koudgefilterd</span>, op een hogere sterkte dan de basisreeks.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li><li><b>100 Proof Edition</b>: een reeks die begin 2024 verscheen, op 57,1% alcohol.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></li><li><b>The Monuments of Scotland</b>: een reeks die Signatory bottelt op 50,8%, in flessen van 70 cl.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup></li><li><b>Symington's Choice</b>: vaten die Andrew Symington zelf uitkiest uit de voorraad van Signatory.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup><sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> De voorbeelden zijn <span class=\"wl\" data-n=\"Single cask\">single casks</span> van 25 jaar en ouder, niet verdund.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup><sup class=\"fn\"><a href=\"#bn-9\">9</a></sup></li></ul><p>Het handige: soms staat 'Signatory' niet op de fles of in de naam, maar wel 'Symington's Choice'. Dan weet je toch van wie hij is.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup></p><p>Daarnaast noemt de Duitse bron een basisreeks op 43%, een Decanter Collection, een Small Batch Edition en een tweede label, Dun Eideann.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><h2>Nog niet uitgezocht</h2><ul><li>Wie het bedrijf nu precies bezit: het register gaf ons die gegevens nog niet.</li><li>Of The Monuments of Scotland altijd op 50,8% wordt gebotteld, en waarom.</li><li>Wat '100 proof' precies betekent in deze reeks.</li><li>Wanneer Symington's Choice begon (rond 2023, maar zonder vakbron).</li></ul>","bronnen":[{"n":"Scotchwhisky.com - Whiskypedia Signatory Vintage Scotch Whisky Company","t":"Whiskypedia — Signatory Vintage Scotch Whisky Company","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/whiskypedia/2272/signatory-vintage-scotch-whisky-company/","j":""},{"n":"Companies House - Signatory Vintage Scotch Whisky Company Limited SC112957","t":"SIGNATORY VINTAGE SCOTCH WHISKY COMPANY LIMITED (SC112957) — company overview","o":"Companies House (UK)","q":"A","u":"https://find-and-update.company-information.service.gov.uk/company/SC112957","j":"2026-10-08"},{"n":"Whisky.com - Signatory Vintage (onafhankelijke bottelaar)","t":"Signatory Vintage — independent bottler","o":"Whisky.com (Whisky.com Media GmbH & Co. KG)","q":"C","u":"https://whisky.com/independent-bottlers/signatory-vintage.html","j":""},{"n":"Harpers - Pernod sells Edradour and BWG","t":"Pernod sells Edradour and BWG","o":"Harpers Wine & Spirit","q":"C","u":"https://harpers.co.uk/news/fullstory.php/aid/721","j":"ONBEKEND (site toont 23-07-2008; inhoud past bij 2002)"},{"n":"Scotchwhisky.com - Whiskypedia Edradour Distillery Company","t":"Whiskypedia — Edradour Distillery Company","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/whiskypedia/2644/edradour-distillery-company/","j":""},{"n":"Dramface 2024 - Signatory Ben Nevis 8yo 100 Proof","t":"Ben Nevis 8yo 100º Proof (Signatory Vintage)","o":"Dramface (Fletcher Finlay)","q":"C","u":"https://www.dramface.com/all-reviews/2024/signatory-ben-nevis-8yo-100-proof","j":"2024-02-29"},{"n":"Master of Malt - Blair Athol 10 Years Old 2015 The Monuments of Scotland Signatory","t":"Blair Athol 10 Year Old 2015 — The Monuments of Scotland (Signatory)","o":"Master of Malt","q":"E","u":"https://www.masterofmalt.com/whiskies/blair-athol/blair-athol-10-year-old-2015-the-monuments-of-scotland-signatory-whisky/","j":""},{"n":"Whiskynotes 2023 - Macallan Laphroaig Bowmore 25 Years Symington's Choice","t":"Macallan / Laphroaig / Bowmore 25 Years (Symington's Choice)","o":"Whiskynotes.be (Ruben)","q":"E","u":"https://www.whiskynotes.be/2023/macallan/macallan-laphroaig-bowmore-25-years-symingtons-choice/","j":"2023-03-30"},{"n":"The Whisky Exchange - Imperial 1995 30 Year Old Cask 50274 Signatory Symington's Choice","t":"Imperial 1995 / 30 Year Old / Cask","o":"The Whisky Exchange","q":"E","u":"https://www.thewhiskyexchange.com/p/86692/imperial-1995-30-year-old-cask-50274-signatory-symingtons-choice","j":""}],"kennis":["Signatory Vintage"]},"single-malts-of-scotland":{"id":"single-malts-of-scotland","soort":"bottelaar","t":"The Single Malts of Scotland: de single casks van Elixir Distillers","k":"The Single Malts of Scotland is een reeks single casks van Elixir Distillers in Londen, het bedrijf van de broers Sukhinder en Rajbir Singh. De reeks bestaat sinds 2005.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>The Single Malts of Scotland is een reeks Schotse single malts van Elixir Distillers, een onafhankelijke bottelaar in Londen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Achter Elixir zitten de broers Sukhinder en Rajbir Singh.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Zij begonnen in 1999 ook de webwinkel The Whisky Exchange.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Hun bedrijf heette eerst Speciality Drinks; sinds 2017 heet het Elixir Distillers.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Sommige bronnen noemen 2017 daarom het oprichtingsjaar van Elixir.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></p>","html":"<h2>De reeks</h2><p>Volgens Elixir bottelt het bedrijf sinds 2005 zijn beste <span class=\"wl\" data-n=\"Single cask\">single casks</span> onder deze naam.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Een vakbron noemt hetzelfde jaar.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Een Amerikaanse importeur noemt 2002; dat jaartal vinden we verder nergens terug.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Volgens de producent heeft elke fles een eigen vatnummer en wordt er niet <span class=\"wl\" data-n=\"Chill filtration\">koudgefiltreerd</span> en geen kleurstof toegevoegd.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De whisky komt uit de eigen voorraad van Elixir.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><p>Binnen de reeks zie je verschillende namen op het etiket. De importeur onderscheidt drie collecties:<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></p><ul><li><b>Single Cask</b>: de kern van de reeks, één vat per botteling.</li><li><b>Reserve Casks</b>: kleine batches.</li><li><b>Director's Special</b>: zeldzame vaten die Sukhinder Singh persoonlijk kiest.</li></ul><p>Ook een winkel beschrijft een Director's Special als vaten uit de eigen selectie van de broers Singh.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Je komt ook de namen 'Small Batch' en 'A Marriage of Casks' tegen. Wat die precies betekenen, hebben we nog niet in een bron gevonden.</p><h2>Wat Elixir nog meer doet</h2><p>Elixir maakt ook andere reeksen, zoals Elements of Islay (sinds 2006) en Port Askaig (sinds 2009).<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Port Askaig is genoemd naar een haven op <span class=\"wl\" data-n=\"Islay\">Islay</span>, niet naar een distilleerderij.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> The Whisky Trail is een aparte, persoonlijke reeks van Sukhinder Singh.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Dat betekent dat The Whisky Trail niet onder The Single Malts of Scotland valt.</p><p>In 2022 kocht Elixir de distilleerderij Tormore in Speyside van Pernod Ricard.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Pernod Ricard had een jaar eerder The Whisky Exchange overgenomen.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Dat betekent in de praktijk dat de winkel en de bottelaar sindsdien andere eigenaren hebben.</p><h2>Nog niet uitgezocht</h2><ul><li>Wat 'Small Batch' en 'A Marriage of Casks' binnen de reeks betekenen.</li><li>Of de reeks in 2002 of 2005 begon (de meeste bronnen zeggen 2005).</li><li>Hoe de eigendom van Elixir precies geregeld is.</li></ul>","bronnen":[{"n":"Scotchwhisky.com - Whiskypedia Elixir Distillers","t":"Elixir Distillers (Whiskypedia)","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/whiskypedia/2274/elixir-distillers/","j":"onbekend"},{"n":"Elixir Distillers - The Single Malts of Scotland","t":"The Single Malts of Scotland — Elixir Distillers","o":"Elixir Distillers","q":"D","u":"https://www.elixirdistillers.com/brands/the-single-malts-of-scotland/","j":""},{"n":"Pernod Ricard 2022 - Sale of Tormore to Elixir Distillers","t":"Pernod Ricard to sell Tormore Scotch whisky brand and distillery to Elixir Distillers","o":"Pernod Ricard","q":"D","u":"https://www.pernod-ricard.com/en/media/pernod-ricard-sell-tormore-scotch-whisky-brand-and-distillery-elixir-distillers","j":"2022-06-20"},{"n":"BeverageDaily 2022 - Pernod Ricard to sell Tormore to Elixir Distillers","t":"Pernod Ricard to sell Tormore to Elixir Distillers","o":"BeverageDaily (William Reed)","q":"C","u":"https://www.beveragedaily.com/Article/2022/06/21/Pernod-Ricard-to-sell-Tormore-to-Elixir-Distillers/","j":"2022-06-21"},{"n":"Skurnik - Single Malts of Scotland","t":"Single Malts of Scotland — Skurnik Wines & Spirits (producentprofiel)","o":"Skurnik Wines & Spirits","q":"D","u":"https://www.skurnik.com/producer/single-malts-of-scotland/","j":""},{"n":"The Whisky Exchange - Bruichladdich 30 Director's Special","t":"Bruichladdich 30 Year Old Single Malts of Scotland Director's Special — The Whisky Exchange","o":"The Whisky Exchange","q":"E","u":"https://www.thewhiskyexchange.com/p/80771/bruichladdich-30-year-old-single-malts-of-scotland-directors-special","j":""},{"n":"Whisky.com - Elixir Distillers bottelaar","t":"Elixir Distillers — Whisky.com independent bottlers","o":"Whisky.com","q":"C","u":"https://www.whisky.com/independent-bottlers/elixir-distillers.html","j":""}],"kennis":["Elixir Distillers"]},"spirit-of-scotland":{"id":"spirit-of-scotland","soort":"bottelaar","t":"Spirit of Scotland: een label van Gordon & MacPhail","k":"Op Spirit of Scotland-flessen staat geen bottelaar. Meerdere bronnen wijzen naar Gordon & MacPhail uit Elgin; die bevestiging zelf hebben we nog niet.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Spirit of Scotland is een reeks Schotse single malts. Op het etiket staat de naam van de distilleerderij, maar geen bottelaar.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Wie zit erachter? Een whiskykennisbank beschrijft Spirit of Scotland als tweede label van Gordon &amp; MacPhail.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Vier whiskywinkels noemen Gordon &amp; MacPhail ook als bottelaar van recente Spirit of Scotland-flessen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Een bevestiging van Gordon &amp; MacPhail zelf of van de vakpers hebben we nog niet gevonden. Daarom houden we het op 'zeer waarschijnlijk', nog niet 'bevestigd'.</p>","html":"<h2>Wie is Gordon &amp; MacPhail?</h2><p>Gordon &amp; MacPhail begon in 1895 als delicatessenwinkel in Elgin, in <span class=\"wl\" data-n=\"Speyside\">Speyside</span>.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> De oprichters waren James Gordon en John Alexander MacPhail.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> De familie Urquhart leidt het bedrijf; John Urquhart werd in 1915 senior partner.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het bedrijf bezit zelf twee distilleerderijen: Benromach, gekocht in 1993, en The Cairn, geopend in 2022.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Daarnaast bottelt het al decennia whisky van andere distilleerderijen, onder meer in de reeks Connoisseurs Choice.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><p>Vanaf 2024 koopt Gordon &amp; MacPhail geen nieuwe spirit meer in bij distilleerderijen die het niet zelf bezit.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Dat betekent in de praktijk dat nieuwe bottelingen van andere distilleerderijen uit bestaande voorraad komen.</p><h2>Hoe herken je een Spirit of Scotland-fles?</h2><p>Op de bekende flessen zie je de naam van de distilleerderij, het jaar van distillatie en de leeftijd.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Het gaat om <span class=\"wl\" data-n=\"Single cask\">single casks</span>: whisky uit één vat, met vatnummer en een beperkt aantal flessen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> De alcoholsterkte is hoog, bijvoorbeeld 55% en 58,4%.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Of het steeds om <span class=\"wl\" data-n=\"Cask strength\">cask strength</span> gaat (de sterkte waarmee de whisky uit het vat komt), zeggen de bronnen niet letterlijk. Bij een Glen Grant uit 2010 meldt de winkel: niet <span class=\"wl\" data-n=\"Chill filtration\">koudgefiltreerd</span> en geen kleurstof.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Of dat voor alle flessen in de reeks geldt, weten we niet.</p><h2>Nog niet uitgezocht</h2><ul><li>Een bevestiging door Gordon &amp; MacPhail zelf of door de vakpers.</li><li>Sinds wanneer de reeks bestaat en voor welke landen hij bedoeld is.</li><li>Waarom Gordon &amp; MacPhail zijn naam niet op deze flessen zet.</li><li>Of andere whisky's met 'Spirit of Scotland' in de naam (bijvoorbeeld oudere blends) iets met deze reeks te maken hebben.</li></ul>","bronnen":[{"n":"Whisky.com - Gordon & MacPhail bottelaar","t":"Gordon & MacPhail — Whisky.com independent bottlers","o":"Whisky.com","q":"C","u":"https://www.whisky.com/independent-bottlers/gordon-amp-macphail.html","j":""},{"n":"The Whisky Exchange - Glen Grant 2010 14 Spirit of Scotland","t":"Glen Grant 2010 14 Year Old Cask","o":"The Whisky Exchange","q":"E","u":"https://www.thewhiskyexchange.com/p/87241/glen-grant-2010-14-year-old-cask-903223-spirit-of-scotland","j":""},{"n":"The Whisky Barrel - Glen Grant 11 2013 Spirit of Scotland","t":"Glen Grant 11 Year Old 2013 Spirit of Scotland — The Whisky Barrel","o":"The Whisky Barrel","q":"E","u":"https://www.thewhiskybarrel.com/products/glen-grant-11-year-old-2013-spirit-of-scotland","j":""},{"n":"Master of Malt - Strathmill 14 2011 Spirit of Scotland","t":"Strathmill 14 Year Old 2011 Spirit of Scotland (Gordon & MacPhail) — Master of Malt","o":"Master of Malt","q":"E","u":"https://www.masterofmalt.com/whiskies/strathmill/strathmill-14-year-old-2011-spirit-of-scotland-gordon-and-macphail-whisky/?sku=144881","j":""},{"n":"Strath Liquor - Glen Grant Spirit of Scotland","t":"Glen Grant Spirit of Scotland 2010 — Strath Liquor","o":"Strath Liquor","q":"E","u":"https://www.strathliquor.com/?p=18324","j":""}],"kennis":["Gordon & MacPhail"]},"the-maltman":{"id":"the-maltman","soort":"bottelaar","t":"The Maltman: single casks van de familie Hart uit Glasgow","k":"The Maltman is het bekendste label van Meadowside Blending, een familiebedrijf van Donald en Andrew Hart in Glasgow. Het label bottelt losse vaten single malt.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>The Maltman is een label van Meadowside Blending, een familiebedrijf in Glasgow.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Vader Donald Hart en zoon Andrew Hart leiden het bedrijf.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Meadowside is een onafhankelijke bottelaar: het heeft geen eigen distilleerderij en bottelt whisky van anderen onder eigen naam.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Wanneer het bedrijf precies begon, is niet helemaal duidelijk. Twee bronnen noemen 2011, een andere bron noemt 2007.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Wel staat vast dat de familie Hart al veel langer whisky bottelt.</p>","html":"<h2>Van Hart Brothers naar Meadowside</h2><p>Donald Hart werkt sinds 1964 in de whiskyhandel.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Met zijn broer Iain begon hij het bedrijf Hart Brothers.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Dat handelde eerst in vaten en werd later ook bottelaar van losse vaten.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In 2007 verkocht de familie Hart Brothers.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Daarna begonnen Donald en Andrew Meadowside Blending.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><h2>Wat The Maltman bottelt</h2><p>The Maltman is het belangrijkste label van Meadowside.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Het bottelt vooral <span class=\"wl\" data-n=\"Single cask\">single casks</span> van single malt, vaak van oudere whisky.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Bij een single cask komen alle flessen uit één vat. Volgens Whisky.com bottelt The Maltman meestal zonder kleurstof en zonder koudfiltratie.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Per fles staat dat op de productpagina, als de bottelaar het vermeldt.</p><p>Naast The Maltman heeft Meadowside nog andere namen. The Grainman bottelt single grain-whisky, The Royal Thistle is de eigen blend.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Ook The Granary en Vital Spark worden als merken van Meadowside genoemd.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><p>In onze catalogus staat eerst de distilleerderij, dan leeftijd en jaar van distillatie, en dan 'The Maltman'. Een voorbeeld is \"Bruichladdich 32 Years Old 1991 The Maltman\". Bij \"Vital Spark 18 Years Old The Maltman\" is Vital Spark geen distilleerderij, maar een naam die Meadowside zelf gebruikt.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><h2>Nog niet uitgezocht</h2><ul><li>Het juiste oprichtingsjaar van Meadowside Blending: 2007 of 2011.</li><li>Wat er in de flessen van Vital Spark zit en van welke distilleerderij die whisky komt.</li></ul>","bronnen":[{"n":"Whisky.com - Meadowside Blending","t":"Meadowside Blending (bottelaarsprofiel)","o":"Whisky.com","q":"C","u":"https://www.whisky.com/independent-bottlers/medowside-blending.html","j":""},{"n":"Whisky Auctioneer - Meadowside Blending","t":"Meadowside Blending Company (bedrijfsprofiel)","o":"Whisky Auctioneer","q":"C","u":"https://whiskyauctioneer.com/learn/explore-whisky/companies/meadowside-blending","j":""},{"n":"Miss Whisky 2013 - The Maltman single casks","t":"The Maltman single casks","o":"Miss Whisky (blog)","q":"E","u":"https://misswhisky.com/2013/09/26/the-maltman-single-casks/","j":"2013-09-26"},{"n":"Whiskybase - Meadowside Blending","t":"Meadowside Blending (bottelaarspagina)","o":"Whiskybase","q":"E","u":"https://www.whiskybase.com/whiskies/bottler/77593/about","j":""}],"kennis":["Meadowside Blending","Single cask"]}},"land":{"australie":{"id":"australie","soort":"land","t":"Australië: wat we (nog) weten over whisky van down under","k":"Over Australische whisky weet onze kennisbank nog weinig. Wat we hebben, gaat over één Tasmaanse single malt: Knopwood 1999.","lt":"2","st":"INCOMPLETE","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Over whisky uit Australië weet onze kennisbank nog weinig. Welke regels Australië stelt aan whisky, hebben we nog niet uitgezocht. Ook de geschiedenis en de distilleerderijen staan nog open. Wat we wel hebben uitgezocht, gaat over één botteling uit Tasmanië. Die whisky werd gebotteld in opdracht van een Duitse distributeur en kreeg een finish in Jerez.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Daarom is deze gids kort. Liever een korte gids die klopt dan een lange die raadt.</p>","html":"<h2>Knopwood 1999: een Tasmaanse single malt</h2><p>Volgens het Duitse vakblad Spirituosen-Journal is deze whisky in 1999 gedistilleerd door de Tasmania Distillery, ook bekend als Sullivans Cove Distillery.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De Duitse distributeur Haromex uit Brüggen liet de whisky exclusief bottelen onder de naam Knopwood, als twee Tasmaanse single malts.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Dat betekent: Knopwood is een merknaam van een bottelaar, geen distilleerderij.</p><p>Beide versies kregen een finish: een laatste rijpingsperiode in een ander vat. De ene in een ex-olorosovat, de andere in een ex-Pedro-Ximénezvat, bij Bodega Rey Fernando de Castilla in Jerez.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Oloroso en Pedro Ximénez zijn soorten sherry; het vakblad spreekt van een sherryfinish.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De whiskydatabase Whisky.com noemt voor de olorosoversie het jaartal 1999 en de herkomst Tasmanië.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><p>Volgens de productomschrijving reisde de whisky per schip van Tasmanië naar Jerez voor die finish.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Dat is een verhaal van de maker; we hebben het niet onafhankelijk kunnen controleren.</p><p>Let op: wat we over de distilleerderij en de bottelaar weten, rust op één vakblad. Een bevestiging van de distilleerderij of de bottelaar zelf hebben we nog niet.</p><h2>Nog niet uitgezocht</h2><ul><li>Welke regels Australië stelt aan whisky (de Australische voedselwetgeving).</li><li>De geschiedenis van whisky in Australië en op Tasmanië.</li><li>Welke distilleerderijen er zijn; ook de Tasmania Distillery heeft nog geen eigen notitie.</li><li>Hoe oud de Knopwood 1999 is bij botteling, en waar de naam Knopwood vandaan komt.</li></ul>","bronnen":[{"n":"Spirituosen-Journal 2022 - Knopwood 1999 Tasmanian Single Malts","t":"Sherry finished: Haromex präsentiert Knopwood 1999 Tasmanian Single Malts","o":"Spirituosen-Journal","q":"C","u":"https://www.spirituosen-journal.de/sherry-finished-haromex-praesentiert-knopwood-1999-tasmanian-single-malts-113678/","j":"2022-12-11"},{"n":"Whisky.com - Knopwood 1999","t":"Knopwood - 1999 Tasmanian Single Malt Whisky - Single Oloroso Antique Cask","o":"Whisky.com (whisky-database)","q":"C","u":"https://www.whisky.com/whisky-database/details/knopwood.html","j":""},{"n":"Fonts In Use - Knopwood Tasmanian Single Malt Whisky","t":"Knopwood Tasmanian Single Malt Whisky","o":"Fonts In Use","q":"E","u":"https://fontsinuse.com/uses/71362/knopwood-tasmanian-single-malt-whisky","j":""}],"kennis":["Australië","Knopwood 1999"]},"belgie":{"id":"belgie","soort":"land","t":"België: Europese regels en een whiskymaker uit Brugge","k":"In België geldt de Europese definitie van whisky. Onze kennisbank kent één Belgische whiskymaker goed genoeg om te beschrijven: de Brugse Whisky Company.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>België is lid van de Europese Unie. Daarom geldt er de Europese definitie van whisky.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Eigen Belgische regels voor whisky heeft onze kennisbank nog niet gevonden. Ook over de geschiedenis van whisky in België weten we nog weinig. Wat we wel hebben, komt vooral uit vakbladen en databanken. Deze gids is daarom kort: wat de Europese regels vragen, en wat we weten over één Belgische whiskymaker.</p>","html":"<h2>Wat de Europese regels vragen</h2><p>In de hele EU geldt voor <span class=\"wl\" data-n=\"Whisky\">Whisky</span>:<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><ul><li>het beslag bevat gemoute granen, eventueel met hele korrels van ongemoute granen;</li><li>de omzetting naar suiker gebeurt door de enzymen van de mout (moutdiastase), eventueel met andere natuurlijke enzymen;</li><li>de vergisting gebeurt door gist;</li><li>elke distillatie blijft onder 94,8% vol., zodat het distillaat geur en smaak van de grondstoffen houdt;</li><li>de whisky rijpt minimaal drie jaar in houten vaten van maximaal 700 liter;</li><li>hij wordt gebotteld op minimaal 40% vol.</li></ul><p>Alcohol toevoegen mag niet, en de whisky mag niet gezoet of gearomatiseerd worden. Alleen water en gewone karamel (<span class=\"wl\" data-n=\"E150a\">E150a</span>) voor de kleur mogen erbij.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In de praktijk betekent dit: elke whisky uit België bevat gemout graan.</p><h2>Wie er stookt</h2><p>De <span class=\"wl\" data-n=\"Brugse Whisky Company\">Brugse Whisky Company</span> is opgericht door Thibaut de Meyer en zijn vader Peter, volgens het vakblog Whiskymonkeys.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Het bedrijf heeft een eigen distilleerderij met koperen ketels waarop 'B.W.C.' staat.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Het maakt onder meer de lijnen Rogia, Ryggia en Peathia.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><p>Bekend is ook de Lanchals. Die whisky rijpte op bourbon-, oloroso- en pinot-noirvaten.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> De naam verwijst volgens Whiskymonkeys naar Pieter Lanchals, een Brugse ambtenaar die op 22 maart 1488 werd onthoofd.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Of de Lanchals in Brugge zelf is gestookt, hebben we nog niet kunnen vaststellen.</p><p>Er gaat een verhaal rond dat Schotse handelaars in de vijftiende eeuw al whisky stookten in Brugge.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Een historische bron daarvoor hebben we niet gevonden. Lees het dus als verhaal, niet als geschiedenis.</p><p>Op Whiskybase staat Klubb23 als Belgische onafhankelijke bottelaar, ontstaan rond 2020.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Dat is nog niet door een tweede bron bevestigd.</p><h2>En de smaak?</h2><p>De Europese regels koppelen geen smaak aan België. Een smaakstijl voor 'Belgische whisky' beschrijven we daarom niet. Zoek je op smaak, gebruik dan het smaakfilter.</p><h2>Nog niet uitgezocht</h2><ul><li>Of België eigen regels voor whisky heeft naast de Europese.</li><li>De geschiedenis van whisky in België.</li><li>Andere Belgische distilleerderijen.</li><li>Het oprichtingsjaar van de Brugse Whisky Company en waar de Lanchals is gestookt.</li></ul>","bronnen":[{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"Whiskymonkeys - Distilleerderij Donderdag Brugse Whisky Company","t":"Distilleerderij Donderdag: Brugse Whisky Company","o":"Whiskymonkeys","q":"C","u":"https://whiskymonkeys.com/rubrieken/distilleerderij-donderdag-brugse-whisky-company","j":""},{"n":"Whiskymonkeys - Lanchals whisky onthoofden","t":"Belgische distilleerderij spoort mensen aan nieuwe whisky vooral te onthoofden","o":"Whiskymonkeys","q":"C","u":"https://whiskymonkeys.com/nieuws/belgische-distilleerderij-spoort-mensen-aan-nieuwe-whisky-vooral-te-onthoofden","j":""},{"n":"Whiskybase - Klubb23","t":"Klubb23 (bottelaarspagina)","o":"Whiskybase","q":"E","u":"https://www.whiskybase.com/whiskies/bottler/92220","j":""}],"kennis":["België","Whisky","E150a","Brugse Whisky Company","Klubb23"]},"canada":{"id":"canada","soort":"land","t":"Canada: vier wettelijke soorten whisky, en wat 'rye' daar betekent","k":"Canada kent vier wettelijke whiskynormen. Smaakstoffen mogen, 'rye' zegt niets over rogge en 'Highland' komt niet uit Schotland.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Canada heeft vier wettelijke normen voor whisky: Whisky, Malt Whisky, Canadian Whisky en Highland Whisky.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Ze staan in de Canadian Food Compositional Standards.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Tot december 2024 stonden de regels in de Food and Drug Regulations; een wetswijziging verplaatste ze.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Op een paar punten wijken de Canadese regels flink af van de Europese. Smaakstoffen mogen bijvoorbeeld. 'Rye' zegt niets over het aandeel rogge. En 'Highland Whisky' is in Canada geen Schotse whisky. Deze gids zet de regels op een rij.</p>","html":"<h2>Canadian Whisky</h2><p>Voor <span class=\"wl\" data-n=\"Canadian Whisky\">Canadian Whisky</span> geldt:<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><ul><li>het is een distillaat, of een mengsel van distillaten, uit graanbeslag;</li><li>versuikerd door moutdiastase (enzymen uit mout) of andere enzymen, en vergist door gist, eventueel samen met andere micro-organismen;</li><li>beslag, distillatie en rijping gebeuren in Canada;</li><li>het rijpt minimaal drie jaar in 'small wood';</li><li>het heeft minimaal 40% alcohol;</li><li>smaakstoffen (flavouring) zijn toegestaan.</li></ul><p>'Small wood' betekent houten vaten of tonnen van maximaal 700 liter.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Voor de leeftijd op het etiket telt alleen de tijd in small wood. Na minimaal drie jaar in small wood mag nog hooguit zes maanden in andere containers meetellen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><h2>'Rye' is geen roggepercentage</h2><p>Canadian Whisky, Canadian Rye Whisky en Rye Whisky zijn in Canada één en dezelfde wettelijke categorie.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De norm noemt geen percentage rogge.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Dat betekent: 'rye' op een Canadees etiket zegt niets over hoeveel rogge erin zit.</p><h2>Whisky en Malt Whisky</h2><p>De algemene norm 'Whisky or Whiskey' beschrijft een distillaat uit graanbeslag. Smaakstoffen mogen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Een rijpingsduur, vat of minimumsterkte noemt deze norm niet.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De norm 'Malt Whisky' vraagt een beslag van gemout graan, niet specifiek gerst. Ook hier mogen smaakstoffen, en ook hier staat geen rijpingsduur of minimumsterkte.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Meer over <span class=\"wl\" data-n=\"Malt whisky\">Malt whisky</span> per land vind je in de kennisbank.</p><h2>Highland Whisky: niet uit Schotland</h2><p><span class=\"wl\" data-n=\"Highland Whisky (Canada)\">Highland Whisky</span> wordt in Canada geblend. Minimaal 25% is malt whisky, gerekend op zuivere alcohol, gedistilleerd in Canada of Schotland. De rest is whisky.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Alleen als minstens 51% Schotse malt whisky is, mag het etiket vermelden dat het in Schotland gedistilleerde malt whisky bevat.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De categorie bestond al vóór 2006; tot december 2024 stond ze in de Food and Drug Regulations.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In de praktijk betekent dit: 'Highland' verwijst hier niet naar de Schotse <span class=\"wl\" data-n=\"Highland\">Highland</span>-regio.</p><h2>Kleurstof</h2><p>Karamel staat op de Canadese lijst van toegestane kleurstoffen voor whisky. Als maximum geldt 'Good Manufacturing Practice'.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> De lijst noemt alleen 'caramel', zonder onderverdeling in soorten.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> In de EU mag alleen gewone karamel (<span class=\"wl\" data-n=\"E150a\">E150a</span>).<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Of in Canada dus ook andere soorten karamel zijn toegestaan, hebben we niet officieel bevestigd gezien.</p><h2>En de smaak?</h2><p>Een smaakstijl voor 'Canadese whisky' beschrijven we niet. Onze kennisbank onderbouwt die (nog) niet. Zoek je op smaak, gebruik dan het smaakfilter.</p><h2>Nog niet uitgezocht</h2><ul><li>De geschiedenis van whisky in Canada.</li><li>Welke distilleerderijen in Canada stoken; de kennisbank heeft er nog geen notities over.</li><li>Hoe ver de toegestane smaakstoffen gaan.</li><li>Of in Canada alle soorten karamel zijn toegestaan, of alleen gewone karamel.</li><li>Waarom Canada de categorie Highland Whisky kent, en of de drie jaar rijping daar ook voor geldt.</li></ul>","bronnen":[{"n":"Canadian Food Compositional Standards","t":"Canadian Food Compositional Standards (Volume 2)","o":"Canadian Food Inspection Agency (CFIA)","q":"A","u":"https://inspection.canada.ca/en/about-cfia/acts-and-regulations/list-acts-and-regulations/documents-incorporated-reference/canadian-food-compositional-standards-0","j":"2024-12-18"},{"n":"SOR-2024-244","t":"SOR/2024-244 — Regulations Amending Certain Regulations Concerning Food Additives and Compositional Standards","o":"Canada Gazette, Part II","q":"A","u":"https://gazette.gc.ca/rp-pr/p2/2024/2024-12-18/html/sor-dors244-eng.html","j":"2024-12-18"},{"n":"Food and Drug Regulations Canada","t":"Food and Drug Regulations (C.R.C., c. 870)","o":"Government of Canada — Justice Laws","q":"A","u":"https://laws-lois.justice.gc.ca/eng/regulations/C.R.C.,_c._870/page-19.html","j":""},{"n":"Health Canada 2025 - List of Permitted Food Colours","t":"3. List of Permitted Food Colours (Lists of Permitted Food Additives)","o":"Health Canada","q":"A","u":"https://www.canada.ca/en/health-canada/services/food-nutrition/food-safety/food-additives/lists-permitted/3-colouring-agents.html","j":"2025-10-20 (laatst gewijzigd)"},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"}],"kennis":["Canada","Canadian Whisky","Highland Whisky (Canada)","Whisky","Malt whisky","Whiskywetgeving per land","Wat mag whisky heten - regels per land"]},"denemarken":{"id":"denemarken","soort":"land","t":"Denemarken: een oude poging en een nieuwe start","k":"Denemarken maakte al in 1952 een eigen whisky, maar de huidige distilleerderijen ontstonden pas vanaf 2005. Als EU-land volgt het de Europese regels.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Denemarken lijkt een nieuw whiskyland, maar het verhaal begint eerder. In 1922 werden er al proeven gedaan, en in 1952 kwam er een eerste commerciële Deense whisky.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Die bleef niet bestaan.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De distilleerderijen die je nu in de winkel tegenkomt, ontstonden vanaf 2005.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Denemarken is lid van de EU, dus daar gelden de Europese regels voor whisky.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In deze gids lees je hoe het begon, wie er stookt en wat sommige Deense makers anders doen.</p>","html":"<h2>Een vroege poging</h2><p>Volgens Whiskipedia deed de staatsdistilleerderij in Roskilde in 1922 de eerste whiskyproeven.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Whisky uit Schotland halen bleek toen goedkoper.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In 1952 verscheen C.L.O.C., de eerste commerciële Deense whisky; de productie stopte in 1974.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Voor deze vroege geschiedenis hebben we maar één bron. De moderne tijd begon volgens dezelfde bron op 27 december 2005, toen Jesper Paulsen op Bornholm zijn eerste moutdistillaat in een vat deed.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Wat mag whisky heten?</h2><p>Deense whisky valt onder de EU-definitie van whisky.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Wat die precies eist, lees je in <span class=\"wl\" data-n=\"Whisky\">Whisky</span>. Een aparte beschermde aanduiding voor Deense whisky hebben we niet gevonden. Of er karamel als kleurstof in zit, hoeft volgens ons onderzoek in Denemarken niet op het etiket; zie <span class=\"wl\" data-n=\"E150a\">E150a</span>.</p><h2>Wie er stookt</h2><ul><li><b>Stauning</b> aan de westkust van Jutland werd in 2005 opgericht door negen vrienden.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De distilleerderij werkt met lokale gerst, rogge en turf.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Naast single malt maakt Stauning ook whisky van gemoute rogge.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> In 2015 investeerde Distill Ventures, een door <span class=\"wl\" data-n=\"Diageo\">Diageo</span> gesteund fonds, ruim tien miljoen pond; de oprichters bleven meerderheidsaandeelhouder.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Sinds eind 2018 is er een grotere distilleerderij.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Wanneer Stauning precies begon met distilleren, is niet duidelijk: de bronnen noemen 2006 en 2009.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><b>Braunstein</b> zit in de haven van Køge en is een brouwerij én distilleerderij van twee broers.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Ze stoken op een hybride installatie die een pot still en een kolom combineert.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Voor hun geturfde whisky laten ze Deense gerst mouten en met turf drogen in Port Ellen op Islay.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Braunstein bottelt ook whisky van anderen, in de Embassy Collection.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></li><li><b>Fary Lochan</b> in Farre stookte zijn eerste spirit op 31 december 2009.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De stills komen van het Schotse bedrijf Forsyths.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li></ul><p>Whiskipedia noemde in 2020 nog meer namen, zoals Nyborg Destilleri, Trolden en Mosgaard.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Hoeveel distilleerderijen er nu zijn, weten we nog niet.</p><h2>Brandnetels in plaats van turf</h2><p>Turf geeft whisky een rokerige smaak als je de gerst erboven droogt. Fary Lochan doet iets anders: het mout zelf gerst op een vloer en rookt een deel met brandnetels in plaats van turf.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Dat is een keuze van één distilleerderij, geen Deense traditie.</p><h2>Nog niet uitgezocht</h2><ul><li>De vroege geschiedenis (1922 en 1952) met een tweede bron.</li><li>Wanneer Stauning begon met distilleren (2006 of 2009) en hoe groot het belang van Diageo nu is.</li><li>De achternaam van de broers achter Braunstein: de bronnen spreken elkaar tegen.</li><li>Het huidige aantal Deense distilleerderijen.</li></ul>","bronnen":[{"n":"Whiskipedia 2020 - Danish whisky","t":"Danish whisky","o":"Whiskipedia","q":"C","u":"https://whiskipedia.com/fundamentals/danish-whisky/","j":"2020-11-22"},{"n":"Whisky Magazine 2016 - The Vikings are coming again","t":"The Vikings Are Coming (Again) — Danish whisky on the rampage","o":"Whisky Magazine","q":"C","u":"https://whiskymag.com/articles/the-vikings-are-coming-again/","j":"2016-03-18"},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"The Drinks Business 2015 - Diageo pours 10m into Danish whisky","t":"Diageo pours £10m into Danish whisky","o":"The Drinks Business","q":"C","u":"https://www.thedrinksbusiness.com/2015/12/diageo-pours-10m-into-danish-whisky/","j":"2015-12-07"},{"n":"Scotchwhisky.com - Whiskypedia Braunstein","t":"Braunstein Profile — Whiskypedia","o":"ScotchWhisky.com","q":"C","u":"https://scotchwhisky.com/whiskypedia/3105/braunstein/","j":""}],"kennis":["Denemarken","Whisky","E150a","Diageo"]},"engeland":{"id":"engeland","soort":"land","t":"Engeland: sinds oktober 2026 een beschermde naam","k":"Sinds 1 oktober 2026 is English Whisky een beschermde Britse geografische aanduiding. De regels eisen onder meer Brits graan, distillatie en rijping in Engeland en minimaal drie jaar rijping.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Engelse whisky heeft sinds kort een eigen beschermde naam. Op 1 oktober 2026 werd English Whisky ingeschreven als Britse geografische aanduiding.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De aanvraag dateert van februari 2022.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De naam beschermt zowel 'English Whisky' als 'English Whiskey'.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Aanvrager was de English Whisky Guild.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In deze gids lees je wat de nieuwe regels eisen en waarover discussie was.</p>","html":"<h2>Wat mag English whisky heten?</h2><p>De regels staan in een officiële productspecificatie.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><ul><li>De whisky wordt gemaakt van granen die in het Verenigd Koninkrijk zijn geteeld.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li>Voor maischen en distilleren wordt water gebruikt uit een bron bij de distilleerderij.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li>Er wordt gedistilleerd tot onder 94,8% alcohol.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> In pot stills moet de damp voldoende in contact komen met koper.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li>De whisky rijpt minimaal drie jaar in houten vaten van maximaal 700 liter, en alleen in Engeland.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Gebruikte vaten, bijvoorbeeld van sherry, port, madeira of bourbon, zijn toegestaan.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li>Bij botteling is hij minimaal 40%.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li>Toevoegen mag alleen water en gewone karamel (<span class=\"wl\" data-n=\"E150a\">E150a</span>).<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De kleur mag dan niet donkerder worden dan wat vaten van nature kunnen geven.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Kleuren moet in Engeland gebeuren.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li>Een leeftijd op het etiket verwijst naar het jongste bestanddeel.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li></ul><h2>Soorten</h2><p>Er zijn twee hoofdsoorten.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><ul><li><b>Malt English Whisky</b>: van gemoute gerst, gedistilleerd in pot stills, en minimaal twee keer gedistilleerd.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li><b>Grain English Whisky</b>: van granen, gedistilleerd in pot stills of kolommen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li></ul><p>'Single' betekent: uit één Engelse distilleerderij. 'Blended' betekent: uit meer dan één.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><h2>Discussie over de regels</h2><p>Over de regels was discussie. Er kwamen zeven bezwaren binnen; vier daarvan werden ontvankelijk verklaard en de meeste bleven onopgelost.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Na de consultatie verviel de eis van volledig koperen ketels; nu volstaat voldoende koper in de dampweg.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Liam Hirt van Circumstance Distillery maakte bezwaar.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> De Scotch Whisky Association noemde de ruimte rond vaten en vergisting 'very damaging' voor het aanzien van single malt in het Verenigd Koninkrijk.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Tegen het besluit kon tot 8 oktober 2026, 17.00 uur, beroep worden ingesteld.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></p><h2>Engeland binnen het Verenigd Koninkrijk</h2><p>Na de Brexit geldt in Groot-Brittannië voor gedistilleerde dranken nog een overgenomen versie van een oudere Europese verordening.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Welsh whisky ging Engeland voor: <span class=\"wl\" data-n=\"Single Malt Welsh Whisky\">Single Malt Welsh Whisky</span> werd in 2023 als eerste Britse spirit beschermd onder het nieuwe Britse stelsel.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></p><h2>Wie er stookt</h2><p>De kennisbank heeft nog geen notities over Engelse distilleerderijen. In onze catalogus staan onder meer whisky's van White Peak, The English Whisky Company en Spirit of Yorkshire onder Engeland. Over die makers zelf hebben we nog niets uitgezocht.</p><h2>Veel voorkomende misverstanden</h2><ul><li><i>\"English whisky mag van buitenlands graan worden gemaakt.\"</i> Nee. Het graan moet in het Verenigd Koninkrijk zijn geteeld.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li><i>\"Een Engelse bottelaar maakt English whisky.\"</i> Niet vanzelf. Wie Schotse whisky in Engeland bottelt, maakt geen English whisky: distillatie en rijping moeten in Engeland gebeuren.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li><i>\"English whisky moet in volledig koperen ketels worden gemaakt.\"</i> Nee. Die eis is na de consultatie geschrapt.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li></ul><h2>Nog niet uitgezocht</h2><ul><li>Of er vóór 8 oktober 2026 beroep is ingesteld tegen de registratie.</li><li>De geschiedenis van whisky in Engeland staat nog niet in de kennisbank.</li><li>Notities over Engelse distilleerderijen, zoals de makers die in de catalogus staan.</li><li>Hoe de Britse algemene regels voor whisky buiten de beschermde namen precies luiden.</li></ul>","bronnen":[{"n":"GOV.UK - English Whisky register entry","t":"English Whisky/English Whiskey","o":"GOV.UK (protected food and drink names)","q":"A","u":"https://www.gov.uk/protected-food-drink-names/english-whisky-slash-english-whiskey","j":"2026-09-11"},{"n":"GOV.UK 2026 - English Whisky product specification","t":"Product specification for English Whisky","o":"DEFRA / GOV.UK (aanvrager English Whisky Guild Ltd)","q":"A","u":"https://assets.publishing.service.gov.uk/media/6aa7d23b6d3764db169045ab/English_Whisky_Product_Specification.pdf","j":"2026-09-11"},{"n":"Spirits Business 2026 - English whisky secures GI","t":"English whisky secures GI","o":"The Spirits Business","q":"C","u":"https://www.thespiritsbusiness.com/2026/09/english-whisky-secures-gi/","j":"2026-09-14"},{"n":"GOV.UK 2026 - English Whisky decision notice","t":"English Whisky: decision notice","o":"DEFRA / GOV.UK","q":"A","u":"https://assets.publishing.service.gov.uk/media/6aa7d0a375ab9593331f7a4d/English_Whisky_Decision_Notice.pdf","j":"2026-09-11"},{"n":"Business Companion - Spirit drinks labelling","t":"Labelling and composition of spirit drinks","o":"Business Companion (Chartered Trading Standards Institute, VK)","q":"A","u":"https://www.businesscompanion.info/en/quick-guides/food-and-drink/labelling-and-composition-of-spirit-drinks-s","j":"2025-10"},{"n":"Just Drinks 2026 - English whisky GI","t":"English whisky receives GI status","o":"Just Drinks","q":"C","u":"https://www.just-drinks.com/news/english-whisky-gi-status/","j":"2026-09-15"}],"kennis":["Engeland","English Whisky","Whisky","E150a","Single Malt Welsh Whisky","Whiskywetgeving per land","Whisky vs whiskey"]},"frankrijk":{"id":"frankrijk","soort":"land","t":"Frankrijk: Bretagne, de Elzas en een landelijke naam in de maak","k":"Franse whisky valt onder de Europese regels. Bretagne en de Elzas hebben elk een eigen beschermde naam; een beschermde naam voor heel Frankrijk is aangevraagd maar nog niet erkend.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Voor alle Franse whisky geldt de Europese definitie: gedistilleerd uit een beslag van gemoute granen, minimaal drie jaar gerijpt in houten vaten en gebotteld op minimaal 40%.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Twee streken hebben daarbovenop een eigen beschermde naam: Bretagne en de Elzas.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Een beschermde naam voor whisky uit heel Frankrijk is aangevraagd, maar nog niet erkend.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> In deze gids lees je wat die namen inhouden en wat we weten over een Franse maker.</p>","html":"<h2>Whisky breton</h2><p>Whisky breton (of Whisky de Bretagne) is sinds eind 2014 een Franse geografische aanduiding; de regels zijn in 2021 gewijzigd.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Het gebied omvat de vier Bretonse departementen en het deel van Loire-Atlantique ten noorden van de Loire.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Malen, maischen, vergisten, distilleren en rijpen gebeurt allemaal in dat gebied.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></p><ul><li>Toegestaan zijn gemout graan en een reeks andere granen, waaronder boekweit, spelt en haver.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Genetisch gemodificeerde rassen zijn verboden.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></li><li>Er mag zowel in ketels per partij als in kolommen worden gedistilleerd.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></li><li>De whisky rijpt minimaal drie jaar in eiken vaten van maximaal 700 liter.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></li><li>Alleen gewone karamel voor de kleur is toegestaan.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></li><li>'Single malt' mag alleen bij whisky van uitsluitend gemoute gerst uit één distilleerderij, enkelvoudig gedistilleerd in ketels per partij tot maximaal 88%.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Dat betekent: strenger dan de Europese regel, die voor single malt geen distillatiewijze voorschrijft.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup><sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li></ul><h2>Whisky alsacien</h2><p>Ook Whisky alsacien (of Whisky d'Alsace) is sinds eind 2014 een geografische aanduiding.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Het gebied omvat alle gemeenten in de Bas-Rhin en de Haut-Rhin.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></p><ul><li>Grondstoffen: alleen gemoute gerst, water en gist.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></li><li>Gedistilleerd wordt alleen in ketels per partij, tot 60 à 80% alcohol.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li>De whisky rijpt minimaal drie jaar in eiken vaten van maximaal 700 liter.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Daarna mag hij verder rijpen in vaten van ander hout.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li>Bij verkoop is hij 40 tot 65% sterk.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></li><li>Volgens een INAO-document uit 2017 mag er geen kleurstof in.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Dat zou strenger zijn dan de Europese regel, die karamel toestaat.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li></ul><h2>Whisky de France: nog niet erkend</h2><p>In mei 2023 is een beschermde naam voor whisky uit heel Frankrijk aangevraagd, toen nog 'Whisky Français'.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Het Franse instituut voor herkomstbenamingen (INAO) vond de band met het gebied te zwak en vroeg vooral de herkomst van het graan te versterken.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Inmiddels heet het plan 'Whisky de France'.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Het lastenboek is volgens Franse vakbladen afgerond en op 25 september 2026 gepresenteerd.<sup class=\"fn\"><a href=\"#bn-10\">10</a></sup><sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Volgens die berichten volgt in november 2026 de behandeling bij het INAO en daarna een Europese procedure, met erkenning rond 2027.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Het ontwerp zou Franse granen eisen, met maximaal 15% buitenlands graan.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Dat is nog geen regel: tot de erkenning is 'Whisky de France' geen beschermde term.</p><h2>Wie er stookt</h2><p>De kennisbank heeft één Franse maker uitgewerkt: <span class=\"wl\" data-n=\"Château du Breuil\">Château du Breuil</span> in Le Breuil-en-Auge, in het Pays d'Auge in Normandië. Het is vooral een calvadoshuis; de kernproducten zijn Calvados Pays d'Auge en Pommeau.<sup class=\"fn\"><a href=\"#bn-11\">11</a></sup> Daarnaast maakt het single malt whisky.<sup class=\"fn\"><a href=\"#bn-12\">12</a></sup> Volgens het profiel bij de Franse whiskyfederatie is die gemaakt van 100% Golden Promise-gerst.<sup class=\"fn\"><a href=\"#bn-12\">12</a></sup> De whisky wordt volgens de importeur op het château zelf twee keer gedistilleerd in pot stills.<sup class=\"fn\"><a href=\"#bn-13\">13</a></sup> Sinds wanneer er whisky wordt gestookt, weten we nog niet.</p><h2>Veel voorkomende misverstanden</h2><ul><li><i>\"'French whisky' is een beschermde term.\"</i> Nog niet. Alleen Bretagne en de Elzas hebben een beschermde naam.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><i>\"Franse whisky is altijd van Frans graan.\"</i> Nee. Voor de aanvraag uit 2023 gold juist geen eis aan de herkomst van het graan.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><i>\"Elzasser en Bretonse whisky volgen dezelfde regels.\"</i> Nee. De Elzas staat alleen gemoute gerst en distillatie per partij toe; Bretagne ook andere granen en kolommen.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup><sup class=\"fn\"><a href=\"#bn-6\">6</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></li></ul><h2>Nog niet uitgezocht</h2><ul><li>De geschiedenis van whisky in Frankrijk staat nog niet in de kennisbank.</li><li>Het definitieve lastenboek van 'Whisky de France' en de uitkomst bij het INAO.</li><li>Wat er in 2021 precies is veranderd aan de regels voor Whisky breton.</li><li>Of de regels voor Whisky alsacien na 2015 zijn gewijzigd, en of het kleurstofverbod in het lastenboek zelf staat.</li><li>Bij Château du Breuil: het startjaar van de whiskyproductie en het aantal ketels.</li><li>Notities over andere Franse distilleerderijen, ook in Bretagne en de Elzas.</li></ul>","bronnen":[{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"Legifrance - IG Whisky de Bretagne","t":"Arrêté du 30 décembre 2014 relatif à l'indication géographique « Whisky de Bretagne » ou « Whisky breton »","o":"Légifrance (Frankrijk)","q":"A","u":"https://www.legifrance.gouv.fr/loda/id/JORFTEXT000030093693","j":"2014-12-30"},{"n":"INAO - Whisky d'Alsace productpagina","t":"Whisky d'Alsace ou Whisky alsacien — fiche produit","o":"INAO","q":"A","u":"https://www.inao.gouv.fr/produit/whisky-dalsace-ou-whisky-alsacien-13121","j":""},{"n":"INAO 2023 - Note Whisky Francais","t":"Note — demande de reconnaissance IG « Whisky Français »","o":"INAO — Commission nationale boissons spiritueuses","q":"A","u":"https://extranet.inao.gouv.fr/fichier/COMNAT-EDV-20230607-Note-Whisky-Fran%C3%A7ais.pdf","j":"2023-06-07"},{"n":"BO-agri 2021 - Cahier des charges IG Whisky de Bretagne","t":"Cahier des charges de l'indication géographique « Whisky de Bretagne » ou « Whisky Breton »","o":"Ministère de l'Agriculture (BO AGRI)","q":"A","u":"https://info.agriculture.gouv.fr/boagri/document_administratif-791276ff-2dfc-404a-92c3-a19d8e89bf59/telechargement","j":"2021-06-03"},{"n":"BO-agri 2015 - Cahier des charges IG Whisky d'Alsace","t":"Cahier des charges de l'indication géographique « Whisky d'Alsace » ou « Whisky alsacien »","o":"Ministère de l'Agriculture (BO-agri)","q":"A","u":"https://info.agriculture.gouv.fr/boagri/document_administratif-24f8f547-8609-4e4e-be81-306cbba67730/telechargement","j":"2015-01-22"},{"n":"INAO 2017 - Whisky d'Alsace antwoord Europese Commissie","t":"« WHISKY ALSACIEN »/« WHISKY D'ALSACE » (PGI-FR-01982) — réponse aux questions de la Commission","o":"INAO","q":"A","u":"https://extranet.inao.gouv.fr/fichier/COMNAT-EDV-04092017-Whisky-Alsace-Reponse-questions-COM2017-20170804vuTF.pdf","j":"2017-08-04"},{"n":"INAO 2023 - Note demandes IG 21-11-2023","t":"Note — demandes IG (Commission nationale boissons spiritueuses, 21-11-2023)","o":"INAO — Commission nationale boissons spiritueuses","q":"A","u":"https://extranet.inao.gouv.fr/fichier/COMNAT-EDV-20231121-Note-demandes-IG.pdf","j":"2023-11-21"},{"n":"Monde de l'epicerie fine 2026 - IGP Whisky de France","t":"L'IGP Whisky de France dans la dernière ligne droite","o":"Le monde de l'épicerie fine","q":"C","u":"https://monde-epicerie-fine.fr/igp-whisky-de-france-cahier-des-charges/","j":"2026-09-28 (volgens hulpmodel)"},{"n":"ForGeorges 2026 - IG Whisky de France etappe","t":"IG Whisky de France : une étape de plus franchie","o":"ForGeorges","q":"C","u":"https://www.forgeorges.fr/ig-whisky-de-france-une-etape-de-plus-franchie/","j":"2026-09-17 (volgens hulpmodel)"},{"n":"IDAC - Chateau du Breuil","t":"La Spiriterie Française, Château du Breuil, Normandie","o":"Drink Calvados (IDAC, interprofession calvados)","q":"C","u":"https://drinkcalvados.com/en/producers/chateau-du-breuil/","j":"ONBEKEND"},{"n":"Federation du Whisky de France - Chateau du Breuil","t":"Château du Breuil — Fédération du Whisky de France","o":"Fédération du Whisky de France","q":"C","u":"https://whiskydefrance.fr/en/etablissement/chateau-du-breuil/","j":"ONBEKEND"},{"n":"Amathus - Le Breuil Normandie Tourbee Single Malt","t":"Le Breuil Normandie Tourbée Single Malt (productblad)","o":"Amathus Drinks (importeur VK)","q":"D","u":"https://www.amathusdrinks.com/productpagepdf/product/printaction/product_id/5113/","j":""}],"kennis":["Frankrijk","Whisky","Whisky breton","Whisky alsacien","Whisky Français","Château du Breuil","Whiskywetgeving per land"]},"ierland":{"id":"ierland","soort":"land","t":"Ierland: één beschermde naam voor het hele eiland","k":"Irish whiskey is een beschermde geografische aanduiding voor het hele eiland Ierland, Noord-Ierland inbegrepen. De regels kennen vier soorten, waaronder de Ierse specialiteit pot still.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Irish whiskey is een beschermde geografische aanduiding. De naam mag alleen op whiskey die op het eiland Ierland is gedistilleerd en gerijpt, Noord-Ierland inbegrepen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De regels staan in een productdossier uit 2014; dat is de versie die in het Europese register is opgenomen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De officiële naam heeft ook een Ierse vorm: Uisce Beatha Eireannach.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens een etymologisch woordenboek komt het woord whisky van het Gaelische <i>uisge beatha</i>, 'water des levens'.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In deze gids lees je wat Irish whiskey wettelijk is, welke vier soorten er bestaan en wat er over de stokerijen bekend is.</p>","html":"<h2>Wat mag Irish whiskey heten?</h2><p>Irish whiskey wordt gedistilleerd uit een beslag van gemoute granen, eventueel aangevuld met hele korrels van andere granen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Er wordt gedistilleerd tot onder 94,8% alcohol.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Daarna rijpt de whiskey minimaal drie jaar op het eiland, in houten vaten (zoals eiken) van maximaal 700 liter.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Toevoegen mag alleen water en gewone karamel voor de kleur.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Bij botteling is de whiskey minimaal 40%.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><p>Je mag 'Irish whiskey' en 'Irish whisky' schrijven; met een e is gebruikelijk.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Opvallend: het graan hoeft niet uit Ierland te komen, wijzen Ierse graantelers op.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Over smaak zeggen de regels niets. Zoek je een bepaalde stijl, gebruik dan het smaakfilter.</p><h2>Vier soorten</h2><ul><li><b><span class=\"wl\" data-n=\"Pot Still Irish Whiskey\">Pot still</span></b>: een beslag van minimaal 30% gemoute en minimaal 30% ongemoute gerst, met maximaal 5% andere granen zoals haver en rogge.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Gedistilleerd in <span class=\"wl\" data-n=\"Pot Still\">pot stills</span>, de klassieke koperen ketels die per partij werken.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><b><span class=\"wl\" data-n=\"Malt Irish Whiskey\">Malt</span></b>: 100% gemoute gerst, gedistilleerd in pot stills.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De mout mag geturfd zijn.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><b><span class=\"wl\" data-n=\"Grain Irish Whiskey\">Grain</span></b>: maximaal 30% gemoute gerst plus hele ongemoute granen, meestal maïs, tarwe of gerst.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Gedistilleerd in kolomketels, die continu werken.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><b><span class=\"wl\" data-n=\"Blended Irish Whiskey\">Blended</span></b>: een mengsel van twee of meer van de drie soorten hierboven.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li></ul><h2>Regels in beweging</h2><p>In 2026 liep een openbare consultatie over wijzigingen van het productdossier; die sloot op 4 september 2026.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Voorgesteld werd onder meer om in pot still tot 30% andere granen toe te staan (alleen haver, tarwe en rogge) en in grain whiskey tot 40% gemoute gerst.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Een uitkomst is nog niet bekend. Tot die tijd gelden de regels uit 2014.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Een stukje geschiedenis</h2><p>Een bekende distilleerketel heeft Ierse wortels. <span class=\"wl\" data-n=\"Aeneas Coffey\">Aeneas Coffey</span> was accijnsambtenaar in Dublin en kreeg in 1830 een Iers patent op een ketel die continu werkt.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> In de jaren 1840 werd de <span class=\"wl\" data-n=\"Coffey Still\">Coffey still</span> breed gebruikt in Schotse distilleerderijen.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></p><p>Bushmills zet 1608 op het etiket. In dat jaar gaf koning Jacobus I een vergunning om te distilleren in de regio rond Bushmills.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup><sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Het huidige bedrijf werd in 1784 opgericht.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Een doorlopende lijn van 1608 naar de huidige distilleerderij is niet aangetoond. Meer hierover lees je in <span class=\"wl\" data-n=\"Is Bushmills de oudste distilleerderij ter wereld\">Is Bushmills de oudste distilleerderij ter wereld</span>.</p><h2>Wie er stookt</h2><p>De kennisbank heeft nog geen eigen notities over Ierse distilleerderijen. Wel weten we via de eigenaren een paar dingen. <span class=\"wl\" data-n=\"Suntory Global Spirits\">Suntory Global Spirits</span> noemt Kilbeggan en Cooley als zijn Ierse distilleerderijen; Kilbeggan bestaat volgens de eigenaar sinds 1757.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> <span class=\"wl\" data-n=\"William Grant &amp;amp; Sons\">William Grant &amp; Sons</span> noemt Tullamore in Ierland, met het jaartal 2014.<sup class=\"fn\"><a href=\"#bn-10\">10</a></sup></p><h2>Veel voorkomende misverstanden</h2><ul><li><i>\"Irish whiskey komt alleen uit de Ierse republiek.\"</i> Nee. De aanduiding geldt voor het hele eiland, ook voor Noord-Ierland.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><i>\"Met een e is verplicht.\"</i> Nee. Beide spellingen zijn toegestaan.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><i>\"Irish whiskey is altijd ongeturfd.\"</i> Nee. Bij malt Irish whiskey mag geturfde mout.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><i>\"Bushmills is de oudste distilleerderij ter wereld.\"</i> De vergunning uit 1608 gold voor de regio; het bedrijf bestaat sinds 1784.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup></li></ul><h2>Nog niet uitgezocht</h2><ul><li>De uitkomst van de consultatie van 2026: worden de regels voor pot still en grain whiskey aangepast?</li><li>Een bredere geschiedenis van Irish whiskey staat nog niet in de kennisbank.</li><li>Notities over de Ierse distilleerderijen zelf (Bushmills, Kilbeggan, Cooley, Tullamore en andere) ontbreken nog.</li><li>Of de vergunning van 1608 in een doorlopende lijn aan de huidige distilleerderij Bushmills vastzit.</li><li>De rol van de Irish Whiskey Act uit 1980.</li></ul>","bronnen":[{"n":"Irish Whiskey Technical File 2014","t":"Irish Whiskey / Uisce Beatha Eireannach / Irish Whisky — Technical File","o":"Department of Agriculture, Food and the Marine (Ierland)","q":"A","u":"https://assets.gov.ie/static/documents/irish-whiskey-technical-file-pdf-428kb.pdf","j":"2014-10"},{"n":"eAmbrosia - Irish Whiskey technical file","t":"Irish Whiskey — technical file in het EU-register (eAmbrosia)","o":"Europese Commissie — eAmbrosia (register geografische aanduidingen)","q":"A","u":"https://ec.europa.eu/geographical-indications-register/eambrosia-public-api/api/v1/attachments/55944","j":"2014-10"},{"n":"Etymonline - whiskey","t":"whiskey (n.) — Online Etymology Dictionary","o":"Etymonline (Douglas Harper)","q":"C","u":"https://www.etymonline.com/word/whiskey","j":""},{"n":"Farmers Journal 2026 - Have your say on Irish whiskey rules","t":"Have your say on Irish whiskey rules","o":"Irish Farmers Journal","q":"C","u":"https://www.farmersjournal.ie/tillage/news/have-your-say-on-irish-whiskey-rules-927928","j":"2026-08-18"},{"n":"Spirits Business 2026 - Irish whiskey changes can broaden category","t":"Irish whiskey changes can broaden category","o":"The Spirits Business","q":"C","u":"https://www.thespiritsbusiness.com/2026/08/irish-whiskey-changes-can-broaden-category/","j":"2026-08-14"},{"n":"Dictionary of Irish Biography - Aeneas Coffey","t":"Coffey, Æneas — Dictionary of Irish Biography","o":"Royal Irish Academy","q":"B","u":"https://www.dib.ie/biography/coffey-aeneas-a1790","j":"2009-10"},{"n":"Bushmills - Legacy","t":"Legacy — Bushmills Irish Whiskey","o":"Bushmills (Proximo / Becle)","q":"D","u":"https://bushmills.com/pages/legacy","j":""},{"n":"Wikipedia - Old Bushmills Distillery","t":"Old Bushmills Distillery — Wikipedia","o":"Wikipedia","q":"C","u":"https://en.wikipedia.org/wiki/Old_Bushmills_Distillery","j":""},{"n":"Suntory Global Spirits - Our Locations","t":"Our Locations — Suntory Global Spirits","o":"Suntory Global Spirits","q":"D","u":"https://www.suntoryglobalspirits.com/about-us/our-locations","j":""},{"n":"William Grant - We","t":"We — William Grant & Sons","o":"William Grant & Sons","q":"D","u":"https://www.williamgrant.com/gb/we/","j":""}],"kennis":["Ierland","Irish Whiskey","Pot Still Irish Whiskey","Malt Irish Whiskey","Grain Irish Whiskey","Blended Irish Whiskey","Whisky vs whiskey","Pot Still","Aeneas Coffey","Coffey Still","Is Bushmills de oudste distilleerderij ter wereld","Suntory Global Spirits","William Grant & Sons","Whiskywetgeving per land"]},"india":{"id":"india","soort":"land","t":"India: wat daar whisky heet, is in Europa niet altijd whisky","k":"In India mag whisky deels of grotendeels uit neutrale alcohol bestaan en geldt geen minimale rijping. Indiase flessen die in Europa als whisky worden verkocht, moeten wel aan de Europese regels voldoen.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>In India is whisky wettelijk omschreven, maar heel anders dan in Europa. Een Indiase whisky mag gemaakt zijn van gemoute granen, maar ook met neutrale alcohol, of met een mengsel van beide.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Een minimale rijpingstijd kent de Indiase regeling niet.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In de EU moet whisky uit graan worden gedistilleerd en drie jaar rijpen, en mag er geen alcohol bij.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Dat betekent: veel van wat in India 'whisky' heet, mag in Europa niet zo heten. In deze gids lees je hoe dat zit, en waarom een Indiase fles in een Europese winkel toch gewoon whisky kan zijn.</p>","html":"<h2>Wat mag whisky heten in India?</h2><p>De regels staan in de Alcoholic Beverages Regulations van de Indiase voedselautoriteit FSSAI, uit 2018.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Daarin is whisky een drank die gedistilleerd is uit het vergiste extract van gemoute granen, óf gemaakt met neutrale alcohol van graan of andere agrarische oorsprong, óf een mengsel daarvan.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Neutrale alcohol is vrijwel zuivere alcohol met weinig eigen smaak.</p><p>De regeling kent een paar soorten:<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><ul><li><b>Single malt</b>: alleen gemoute gerst, alleen gedistilleerd in pot stills, in één distilleerderij.</li><li><b>Single grain</b>: gemoute of ongemoute granen, in één distilleerderij.</li><li><b>Blended malt of grain whisky</b>: minimaal 2% malt- of grain whisky, aangevuld met neutrale of gerectificeerde alcohol.</li></ul><p>Verder geldt:</p><ul><li>Whisky heeft een alcoholgehalte van 36 tot 50%.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In de EU is het minimum 40%.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li><li>Wie 'matured' op het etiket zet, moet de whisky minimaal een jaar laten rijpen, in eiken of ander geschikt hout of met houtsnippers.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li>Een leeftijd op het etiket verwijst naar de jongste alcohol in de fles.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li></ul><p>Indiase single malt lijkt in de basis op <span class=\"wl\" data-n=\"Single Malt Scotch Whisky\">Schotse single malt</span>: gerst, pot stills, één distilleerderij.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Waarom de Indiase fles in Europa wel whisky is</h2><p>Alles wat in de EU als whisky wordt verkocht, moet aan de Europese definitie voldoen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> In de praktijk betekent dat: een Indiase whisky in een Europese winkel moet minimaal drie jaar gerijpt zijn, op minimaal 40% gebotteld en zonder toegevoegde alcohol.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Een Indiase blend met 2% whisky en 98% neutrale alcohol kan in de EU dus niet als whisky worden verkocht.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><h2>Melasse</h2><p>De Indiase regels noemen melasse, een bijproduct van suiker, uitdrukkelijk als mogelijke grondstof voor neutrale alcohol.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Of melassealcohol ook onder de whiskydefinitie valt, staat er niet letterlijk; waarschijnlijk wel, omdat die 'neutrale alcohol van agrarische oorsprong' toestaat.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In 2003 was melassewhisky volgens een marktrapport goed voor meer dan 90% van de whiskyverkoop in India.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Een vakblad schreef in hetzelfde jaar dat de overgrote meerderheid van de Indiase whisky op melasse was gebaseerd.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Een actueel cijfer hebben we niet.</p><h2>Single malt in opmars</h2><p>Naast de massamarkt groeit de Indiase single malt. Volgens een schatting van een Indiase brancheorganisatie werden in 2025 ongeveer 500.000 dozen Indiase single malt verkocht.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></p><h2>Veel voorkomende misverstanden</h2><ul><li><i>\"Indiase whisky is altijd van melasse.\"</i> Te stellig. De wet staat ook whisky uit graan toe, en single malt moet van gemoute gerst zijn.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><i>\"Indiase whisky moet drie jaar rijpen, net als in Europa.\"</i> Nee. De Indiase regeling kent geen minimale rijping.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><i>\"Een Indiase whisky in de Europese winkel is anders gemaakt dan andere whisky.\"</i> Hij moet aan dezelfde EU-regels voldoen als elke andere whisky in de winkel.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li></ul><h2>Nog niet uitgezocht</h2><ul><li>De geschiedenis van whisky in India staat nog niet in de kennisbank.</li><li>Welke Indiase distilleerderijen er zijn: daar zijn nog geen notities over.</li><li>Hoeveel van de Indiase whisky nu op melasse is gebaseerd. Het laatste harde cijfer is uit 2003.</li><li>Of er aparte regels gelden voor Indiase whisky die voor de export wordt gemaakt.</li></ul>","bronnen":[{"n":"FSSAI - Alcoholic Beverages Regulations 2018","t":"Food Safety and Standards (Alcoholic Beverages) Regulations, 2018 — Compendium","o":"Food Safety and Standards Authority of India (FSSAI)","q":"A","u":"https://fssai.gov.in/upload/uploadfiles/files/Comp_Alcoholic_Beverages_01_12_2025.pdf","j":"2018"},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"Beverage Daily 2004 - India stretches whisky market lead","t":"India stretches whisky market lead","o":"BeverageDaily","q":"C","u":"https://www.beveragedaily.com/Article/2004/01/13/India-stretches-whisky-market-lead/","j":"2004-01-13"},{"n":"Whisky Magazine 2003 - A taste of India","t":"A taste of India","o":"Whisky Magazine","q":"C","u":"https://whiskymag.com/articles/a-taste-of-india/","j":"'2003-03-24'"},{"n":"Outlook Business 2026 - Indian single malts half a million cases","t":"Indian Single Malts Leap to Half a Million Cases in 2025, Desi Firms Dominate with 92% Share: CIABC","o":"Outlook Business (PTI), cijfers CIABC","q":"C","u":"https://www.outlookbusiness.com/news/indian-single-malts-leap-to-half-a-million-cases-in-2025-desi-firms-dominate-with-92-share-ciabc","j":"2026-07-26"}],"kennis":["India","Indian Whisky","Whisky","Whiskywetgeving per land","Single Malt Scotch Whisky"]},"israel":{"id":"israel","soort":"land","t":"Israël: een jong whiskyland in een warm klimaat","k":"Israël maakt pas sinds de jaren 2010 whisky. Milk & Honey in Tel Aviv was de eerste distilleerderij; op de Golanhoogten volgden er meer.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Israël is een nieuwkomer in de whiskywereld. De eerste whiskydistilleerderij, Milk &amp; Honey in Tel Aviv, werd vanaf 2012 gepland en distilleert sinds 2015 op de huidige plek.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In 2017 kwamen de eerste Israëlische single malts op de markt.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In deze gids lees je wie er stookt, wat het warme klimaat zou doen en wat er (nog) niet geregeld is.</p>","html":"<h2>Hoe het begon</h2><p>Milk &amp; Honey bracht in mei 2017 een single malt uit die het vakblad The Spirits Business voorzichtig \"de eerste\" van het land noemt, met aanhalingstekens.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Het ging om 391 genummerde flessen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De spirit was gemaakt door head distiller Tomer Goren, samen met whiskyconsultant Jim Swan.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Over het precieze oprichtingsjaar van Milk &amp; Honey zijn de bronnen het niet eens: sommige noemen 2012, andere 2013.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></p><h2>Wie er stookt</h2><ul><li><b>Milk &amp; Honey</b> (Tel Aviv). De distilleerderij werkt volgens de producent met koperen pot stills.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Dat zijn ketels waarin per keer (batchgewijs) wordt gedistilleerd. De whisky's verschijnen onder meer in de series Classic, Elements en Apex, volgens de producent.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></li><li><b>Pelter</b> (Golanhoogten). Opgericht in 2013, stookt op een Franse alambiek en maakt ook brandy en arak.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De eerste driejarige single malt kwam in 2017.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><b>Golan Heights Distillery</b> (Katzrin). David Zibell begon in 2014 in zijn achtertuin.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Zijn Golani Two Grain is gemaakt van tarwe en gemoute gerst en rijpt in vaten van een wijnhuis uit de streek.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li><li><b>Edre'i</b> (Katzrin) mout zelf in Israël geteelde gerst.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Eind 2018 was deze distilleerderij volgens Tablet nog in aanbouw.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li></ul><p>Rond 2018 waren er volgens ScotchWhisky.com ongeveer een half dozijn andere distilleerderijen open of in voorbereiding.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Hoe het daar nu mee staat, hebben we nog niet uitgezocht.</p><h2>Snel rijpen in de hitte?</h2><p>In Israël is drie jaar rijping gangbaar.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Volgens Milk &amp; Honey is de whisky door hitte en vocht na drie jaar al \"volledig gerijpt\" en rijpt hij twee tot tweeënhalf keer sneller dan Scotch.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Dat is een claim van de producent; een meting hebben we niet gevonden. Volgens ScotchWhisky.com verdampt er in de warmte ook meer whisky uit het vat (de angel's share).<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Milk &amp; Honey liet ook vaten rijpen bij de Dode Zee, ruim 400 meter onder zeeniveau.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Wat dat met de whisky doet, is niet gemeten.</p><p>Een praktisch punt: Israël heeft geen grote commerciële mouterijen, en de meeste gemoute gerst komt van buiten.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><h2>Wat mag whisky heten?</h2><p>Eind 2018 had Israël geen wettelijke definitie van whisky.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De distilleerderijen volgden in het algemeen de Schotse normen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Milk &amp; Honey pleitte toen voor regels over ingrediënten en een minimale rijpingsduur.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Of die regels er inmiddels zijn, weten we nog niet. Voor de EU-regels, zie <span class=\"wl\" data-n=\"Whisky\">Whisky</span>.</p><h2>Nog niet uitgezocht</h2><ul><li>Of Israël sinds 2018 een wettelijke definitie van whisky heeft.</li><li>Hoe het nu staat met Edre'i, Jerusalem Distilling Company, Legends en Golan Heights Distillery.</li><li>Het juiste oprichtingsjaar van Milk &amp; Honey (2012 of 2013).</li><li>Of snelle rijping in Israël ooit gemeten is.</li></ul>","bronnen":[{"n":"Scotchwhisky.com 2018 - Israel the land of milk honey and whisky","t":"Israel: the land of milk, honey and whisky","o":"ScotchWhisky.com","q":"C","u":"https://scotchwhisky.com/magazine/features/22095/israel-the-land-of-milk-honey-and-whisky/","j":"2018-12-12"},{"n":"The Spirits Business 2017 - Distillery unveils Israels first single malt whisky","t":"Distillery unveils Israel's 'first' single malt whisky","o":"The Spirits Business","q":"C","u":"https://www.thespiritsbusiness.com/?p=632118","j":"2017-05-26"},{"n":"Tablet Magazine 2018 - Whiskey takes off in Israel","t":"Whiskey Takes Off in Israel","o":"Tablet Magazine","q":"C","u":"https://www.tabletmag.com/jewish-life-and-religion/276414/whiskey-takes-off-in-israel","j":"2018-12-17"},{"n":"Times of Israel 2018 - Sweet drams of whisky flow in the land of milk and honey","t":"Sweet drams of whisky flow in the land of milk and honey","o":"The Times of Israel","q":"C","u":"https://www.timesofisrael.com/sweet-drams-of-whisky-flow-in-the-land-of-milk-and-honey/","j":"2018-03-01"},{"n":"Milk & Honey Distillery - About","t":"About — Milk & Honey Distillery","o":"The Milk & Honey Distillery","q":"D","u":"https://mh-distillery.com/about/","j":""}],"kennis":["Israël","Whisky"]},"japan":{"id":"japan","soort":"land","t":"Japan: een strenge norm, maar een ruime wet","k":"'Japanese whisky' is in Japan nog geen wettelijke term. Sinds 2021 is er een vrijwillige norm van de producenten; de belastingwet zelf is veel ruimer.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Wie in Japan 'Japanese whisky' op een fles zet, volgt daarmee geen wet maar een afspraak. In 2021 stelden de Japanse producenten via hun brancheorganisatie JSLMA een norm op voor die term.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De norm is vrijwillig en niet wettelijk afdwingbaar.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De Japanse belastingwet, die bepaalt wat 'whisky' is, stelt veel minder eisen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Op Whiskysite noemen we een fles daarom zoals de producent hem noemt. In deze gids lees je wat de wet en de norm zeggen, hoe het verder gaat en wat we weten over de stokerij Sakurao.</p>","html":"<h2>Wat zegt de wet?</h2><p>De Japanse belastingwet (Liquor Tax Act) omschrijft whisky als een distillaat van een vergist beslag van mout en water, eventueel met andere granen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Er wordt gedistilleerd tot onder 95% alcohol.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Aan dat distillaat mag andere alcohol, smaakstof, kleurstof of water worden toegevoegd.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> De voorwaarde: minstens 10% van de alcohol in de fles moet uit het whiskydistillaat komen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Over rijping of vaten zegt de wet niets.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><p>In de praktijk betekent dit: een fles die in Japan als whisky wordt verkocht, kan voor het grootste deel uit andere alcohol bestaan. In de EU mag zo'n product geen whisky heten; daar moet whisky onder meer drie jaar rijpen en mag er geen alcohol bij.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></p><h2>Wat zegt de norm voor 'Japanese whisky'?</h2><p>De JSLMA-norm is veel strenger dan de wet.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><ul><li>Grondstoffen: gemoute granen (altijd verplicht), andere granen en water uit Japan.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li>Versuikeren, vergisten en distilleren gebeurt in een distilleerderij in Japan.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li>De whisky rijpt minimaal drie jaar in Japan, in houten vaten van maximaal 700 liter.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li>Hij wordt in Japan gebotteld, op minimaal 40%.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li>Gewone karamel voor de kleur mag.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li></ul><p>Een fles die niet aan de norm voldoet, mag geen Japanse plaatsnamen, vlag of andere verwijzingen naar Japan gebruiken, tenzij duidelijk op het etiket staat dat hij niet aan de norm voldoet.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De norm geldt sinds 1 april 2021; bestaande etiketten mochten tot en met 31 maart 2024 blijven.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Wordt het een wet?</h2><p>Nog niet. Op de officiële Japanse lijst van beschermde herkomstbenamingen staat geen whisky.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Wel beschermt Japan Bourbon Whisky en Tennessee Whisky, via een afspraak met de Verenigde Staten.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> De JSLMA wil 'Japanese whisky' laten beschermen.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> De voorzitter kondigde eind 2025 aan dat begin 2026 aan te vragen.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Of dat is gebeurd, weten we nog niet. Volgens een Japanse whiskysite werkt de belastingdienst met de branche aan een wettelijke definitie, maar is die nog enkele jaren weg.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><h2>Wie er stookt</h2><p>Over één Japanse stokerij heeft de kennisbank een notitie: <span class=\"wl\" data-n=\"Sakurao\">Sakurao</span> in Hatsukaichi, in de prefectuur Hiroshima. Het bedrijf bestaat volgens de producent sinds 1918; de whiskydistilleerderij kwam er in 2017.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Een Japanse whiskysite meldde dat de productie medio december 2017 begon.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> De whisky's kwamen in 2021 op de markt onder de merken Sakurao en Togouchi.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup><sup class=\"fn\"><a href=\"#bn-10\">10</a></sup> De whisky rijpt volgens de producent in een magazijn bij de distilleerderij aan de kust en in een tunnel van een opgeheven spoorlijn in Togouchi.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup></p><p>Een voorbeeld van waarom de norm ertoe doet: voordat Sakurao zelf stookte, was Togouchi ingevoerde whisky die in Hiroshima werd geblend en gerijpt.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Wat er nu in de Togouchi-flessen zit, hebben we nog niet uitgezocht.</p><h2>Veel voorkomende misverstanden</h2><ul><li><i>\"Whisky uit Japan is altijd volledig in Japan gemaakt.\"</i> Dat garandeert de wet niet. Alleen de vrijwillige norm stelt die eis.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li><li><i>\"Japanese whisky is wettelijk beschermd.\"</i> Nog niet. Er is alleen de branchenorm.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></li><li><i>\"Japanse whisky moet drie jaar rijpen.\"</i> Volgens de norm wel, volgens de wet niet.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li><li><i>\"Japanse whisky schrijf je met een e.\"</i> Meestal niet: Japanse whisky wordt doorgaans zonder e gespeld.<sup class=\"fn\"><a href=\"#bn-11\">11</a></sup></li></ul><h2>Nog niet uitgezocht</h2><ul><li>De geschiedenis van whisky in Japan staat nog niet in de kennisbank.</li><li>Welke producenten de norm volgen, en welke flessen eraan voldoen.</li><li>Of de aanvraag voor een beschermde naam 'Japanese whisky' begin 2026 echt is ingediend.</li><li>Bij Sakurao: hoeveel ketels er zijn en wat er nu in Togouchi zit.</li><li>Notities over andere Japanse distilleerderijen.</li></ul>","bronnen":[{"n":"JSLMA - Standards for Labeling Japanese Whisky 2021","t":"Standards for Labeling \"Japanese Whisky","o":"Japan Spirits & Liqueurs Makers Association (JSLMA)","q":"A","u":"https://www.yoshu.or.jp/files/libs/552/202303291555304944.pdf","j":"2021-02-12"},{"n":"Nomunication 2026 - Japanese whisky law","t":"Japanese Whisky law — The National Tax Agency is working on it","o":"Nomunication","q":"C","u":"https://www.nomunication.jp/2026/03/19/japanese-whisky-law-the-national-tax-agency-is-working-on-it/","j":"2026-03-19"},{"n":"e-Gov - Liquor Tax Act art 3","t":"酒税法 (Liquor Tax Act) — artikel 3, nr. 15 ウイスキー","o":"e-Gov (Digital Agency, Japan)","q":"A","u":"https://laws.e-gov.go.jp/api/1/articles;lawNum=昭和二十八年法律第六号;article=3","j":"1953 (wet nr. 6, geconsolideerd)"},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"NTA - Lijst geografische aanduidingen alcoholische dranken","t":"酒類の地理的表示一覧 (lijst geografische aanduidingen voor alcoholische dranken)","o":"National Tax Agency (国税庁), Japan","q":"A","u":"https://www.nta.go.jp/taxes/sake/hyoji/chiri/ichiran.htm","j":"onbekend (laatste aanwijzing in lijst: 2025-10-01)"},{"n":"Drinks International 2025 - JSMLA to register GI for Japanese whisky","t":"JSMLA to register GI for Japanese whisky","o":"Drinks International","q":"C","u":"https://drinksint.com/news/fullstory.php/aid/11667/.html","j":"2025-03-28"},{"n":"Nissyoku 2025 - Japanese whisky GI-aanvraag 2026","t":"日本洋酒酒造組合・塚原理事長、ジャパニーズウイスキー 26年にGI申請へ","o":"日本食糧新聞 (Nissyoku)","q":"C","u":"https://news.nissyoku.co.jp/flash/1247602","j":"2025-12-16"},{"n":"Sakurao Brewery and Distillery - Website","t":"SAKURAO Brewery and Distillery (Engelse site)","o":"SAKURAO Brewery and Distillery Co., Ltd.","q":"D","u":"https://www.sakuraobd.co.jp/en/","j":""},{"n":"Nomunication 2017 - Chugoku Jozo opens Sakurao Distillery","t":"Chugoku Jozo opens Sakurao Distillery, Hiroshima's first single malt whisky & craft gin","o":"Nomunication","q":"C","u":"https://www.nomunication.jp/2017/12/11/chugoku-jozo-opens-sakurao-distillery-hiroshimas-first-single-malt-whisky-craft-gin/","j":"2017-12-11"},{"n":"Whiskymonkeys 2025 - Distillery Thursday Sakurao","t":"Distillery Thursday: How Sakurao rose from the ashes of war","o":"Whiskymonkeys (Hessel Koeten)","q":"C","u":"https://whiskymonkeys.com/en/sections/distillery-thursday-how-sakurao-rose-from-the-ashes-of-war","j":"2025-11-06"},{"n":"SWA - Scotch Whisky FAQs","t":"Scotch Whisky FAQs","o":"Scotch Whisky Association","q":"A","u":"https://www.scotch-whisky.org.uk/discover-scotch/faqs/","j":""}],"kennis":["Japan","Japanese Whisky","Sakurao","Whisky","Whiskywetgeving per land","Whisky vs whiskey"]},"nederland":{"id":"nederland","soort":"land","t":"Nederland: een jonge whiskytraditie onder Europese regels","k":"De bekendste vroege Nederlandse whisky's kwamen in 2005 en 2006 op de markt. Er gelden dezelfde Europese regels als overal in de EU, en het aantal makers groeit snel.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Nederland is geen oud whiskyland. De bekendste vroege Nederlandse whisky's kwamen in 2005 en 2006 op de markt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Inmiddels zijn tientallen stokerijen en brouwerijen met whisky bezig, verspreid over alle provincies.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Een eigen whiskywet heeft Nederland niet: hier gelden de Europese regels.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In deze gids lees je wat dat betekent, wie de pioniers waren en wat we weten over een paar makers. Een korter overzicht met dezelfde basis vind je in ons artikel <span class=\"wl\" data-n=\"Nederlandse whisky\">Nederlandse whisky</span>.</p>","html":"<h2>Wat mag Nederlandse whisky heten?</h2><p>Voor whisky uit Nederland geldt de Europese definitie.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><ul><li>Gedistilleerd uit een beslag van gemoute granen, eventueel met hele korrels van andere granen, tot onder 94,8% alcohol.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li><li>Minimaal drie jaar gerijpt in houten vaten van maximaal 700 liter.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li><li>Minimaal 40% alcohol bij botteling.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li><li>Geen toegevoegde alcohol, geen zoet- of smaakstoffen. Alleen gewone karamel voor de kleur mag.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li></ul><p>'Single malt' mag alleen op de fles als de whisky uitsluitend van gemoute gerst is gemaakt, in één distilleerderij.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Een beschermde herkomstbenaming 'Nederlandse whisky' hebben we niet gevonden. Over smaak zegt de wet niets; gebruik voor een bepaalde stijl het smaakfilter.</p><h2>De pioniers</h2><p>Twee namen vallen steeds als het om 'de eerste' gaat. <span class=\"wl\" data-n=\"Zuidam\">Zuidam</span> in Baarle-Nassau legde volgens de producent in 1996 de eerste experimentele vaten whisky weg.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> De whisky kwam in 2006 op de markt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> <span class=\"wl\" data-n=\"Us Heit\">Us Heit</span> in Bolsward begon in 2002 met whisky en bracht in 2005 Frysk Hynder uit.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><p>Wie de eerste was, hangt dus af van de vraag. Bedoel je eerst gedistilleerd, dan is dat volgens de producent Zuidam. Bedoel je eerst verkocht, dan is dat Us Heit. Of er vóór 1996 al whisky in Nederland is gemaakt, weten we niet. Zie ook <span class=\"wl\" data-n=\"Wat was de eerste Nederlandse whisky\">Wat was de eerste Nederlandse whisky</span>.</p><h2>Hoeveel makers zijn er?</h2><p>Dat hangt af van wat je telt. Een horecavakblad noemde in 2023 ongeveer 30 serieuze whiskydistilleerderijen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Een whiskyplatform telde in 2025 ruim 70 distilleerderijen die 'aan de slag zijn gegaan met whisky'.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Op die lijst staan ook brouwerijen en makers die nog geen whisky verkopen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Dat betekent in de praktijk: omdat whisky minstens drie jaar moet rijpen, zit er tussen beginnen en verkopen altijd een paar jaar.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><h2>Wie er stookt</h2><ul><li><b><span class=\"wl\" data-n=\"Zuidam\">Zuidam</span></b> is een familiebedrijf, in 1976 opgericht door Fred en Hélène van Zuidam en nu geleid door de tweede generatie.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> De producent stookt in kleine koperen ketels en laat zeven dagen vergisten.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Het whiskymerk is Millstone.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><b><span class=\"wl\" data-n=\"Us Heit\">Us Heit</span></b> in Bolsward maakt Frysk Hynder.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Meer weten we nog niet.</li><li><b>Jopen</b> is een bierbrouwerij uit Haarlem. Sinds 2015 maakt het bedrijf gedistilleerd, eerst gin en genever.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> In 2018 kwamen de distilleerketels naar de brouwerij in de Haarlemse Waarderpolder.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> In november 2023 volgden drie whisky's: een single malt, een rye en een geturfde versie.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup><sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Het distillaat dateert uit 2018.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Jopen stookt daarvoor bier zonder hop.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup></li><li><b>Boomsma</b> (Leeuwarden) en <b>Cley</b> (Rotterdam) worden ook genoemd als Nederlandse whiskymakers.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Over hen heeft de kennisbank nog geen notitie.</li></ul><p>Niet elk Nederlands whiskymerk heeft een eigen stokerij. Willem's Whisky bijvoorbeeld is een merk van Paul Selier en wordt gestookt bij De Tweekoppige Phoenix in de Zaanse Schans.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup></p><h2>Veel voorkomende misverstanden</h2><ul><li><i>\"Nederlandse whisky mag jonger zijn dan Schotse.\"</i> Nee. Ook hier is drie jaar rijping het minimum.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li><li><i>\"Er is één eerste Nederlandse whisky.\"</i> Dat hangt af van wat je met 'eerste' bedoelt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><i>\"Elke Nederlandse whiskymaker is een distilleerderij.\"</i> Nee. Sommige merken laten elders stoken.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup></li></ul><h2>Nog niet uitgezocht</h2><ul><li>Of er vóór 1996 al whisky in Nederland is gemaakt.</li><li>Een officiële telling van Nederlandse whiskydistilleerderijen. De bronnen spreken elkaar tegen (21, 30 of ruim 70).</li><li>Waar Jopen precies stookt: een whiskyplatform noemt Hoofddorp, de producent noemt de brouwerij in Haarlem. Wij houden het voorlopig op Haarlem.</li><li>Of Boomsma zelf distilleert, en gegevens over Cley.</li><li>Wie Tallwood maakt, een whisky die in de catalogus onder Nederland staat.</li><li>Of er toch een beschermde herkomstbenaming voor Nederlandse whisky bestaat (Europees register nog niet nagekeken).</li></ul>","bronnen":[{"n":"Misset Horeca 2023 - Opkomst Nederlandse whisky","t":"Opkomst van Nederlandse whisky","o":"Misset Horeca","q":"C","u":"https://www.missethoreca.nl/340752/opkomst-van-nederlandse-whisky-al-21-distilleerderijen","j":"2023-11-07"},{"n":"Whiskymonkeys 2025 - Nederlandse distilleerderijen op een rij","t":"Dit zijn de Nederlandse distilleerderijen op een rij","o":"Whiskymonkeys","q":"C","u":"https://whiskymonkeys.com/nieuws/dit-zijn-de-nederlandse-distilleerderijen-op-een-rij","j":"2025-07-02 (bijgewerkt 2025-08-24)"},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"Zuidam - Whisky","t":"Whisky — Zuidam Distillers","o":"Zuidam Distillers","q":"D","u":"https://www.zuidam.nl/nl/merken/whisky","j":""},{"n":"Jopen 2023 - Prospectus december 2023","t":"Prospectus december 2023 (pitchdeck)","o":"Jopen","q":"D","u":"https://www.jopenbier.nl/app/uploads/2023/12/Pitchdeck_december_2023_compressed-1.pdf","j":"2023-12"},{"n":"Biernet 2023 - Brouwerij Jopen lanceert drie whiskys","t":"Brouwerij Jopen lanceert drie whisky's","o":"Biernet.nl","q":"C","u":"https://www.biernet.nl/nieuws/brouwerij-jopen-lanceert-drie-whiskys","j":"2023-11-08"},{"n":"Haarlem105 2023 - Jopen voegt whisky toe aan assortiment","t":"Bierbrouwerij Jopen voegt whisky toe aan het assortiment","o":"Haarlem105","q":"C","u":"https://www.haarlem105.nl/?p=80945","j":"2023-11-10"},{"n":"Whiskymonkeys 2023 - Willems Whisky review","t":"Willem's Whisky Review","o":"Whiskymonkeys","q":"C","u":"https://whiskymonkeys.com/reviews/willems-whisky-review","j":"2023-04-12"}],"kennis":["Nederland","Whisky","Zuidam","Us Heit","Wat was de eerste Nederlandse whisky","Nederlandse whisky","Pot Still"]},"taiwan":{"id":"taiwan","soort":"land","t":"Taiwan: whisky sinds het einde van het staatsmonopolie","k":"Taiwan maakt pas sinds deze eeuw whisky. Na het einde van het staatsmonopolie op sterke drank begon Kavalan in 2005 te bouwen; ook het staatsbedrijf maakt whisky.","lt":"2","st":"INCOMPLETE","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Taiwan is een jong whiskyland. Tot het begin van deze eeuw had de staat een monopolie op sterke drank. Dat verdween nadat Taiwan in 2002 lid werd van de Wereldhandelsorganisatie (WTO) en de regels werden versoepeld.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In 2005 begon de bouw van de distilleerderij Kavalan.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In deze gids lees je wat we weten over de Taiwanese stokerijen. Over de Taiwanese wet zelf weten we nog weinig.</p>","html":"<h2>Wat mag whisky heten?</h2><p>Een Taiwanese wettelijke definitie van whisky hebben we nog niet gevonden. Wel geldt: een Taiwanese whisky die in de EU als whisky wordt verkocht, moet aan de Europese regels voldoen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Dat betekent onder meer minimaal drie jaar rijping in houten vaten, minimaal 40% alcohol en geen toegevoegde alcohol.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><h2>Wie er stookt</h2><ul><li><b><span class=\"wl\" data-n=\"Kavalan\">Kavalan</span></b> staat in Yilan.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> De bouw begon in april 2005; op 11 maart 2006 liep de eerste new make, de vers gedistilleerde spirit, een vat in.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De producent zelf spreekt van 'since 2005'.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Volgens de producent rijpt de whisky 'in intense humidity' en komt het water van smeltwater van de Snow Mountain.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Of het warme, vochtige klimaat de rijping echt versnelt, hebben we nog niet uitgezocht; zie <span class=\"wl\" data-n=\"Rijping\">Rijping</span>.</li><li><b><span class=\"wl\" data-n=\"Nantou\">Nantou</span></b> is de whiskymaker van het staatsbedrijf Taiwan Tobacco and Liquor Corporation, in Nantou.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In 2014 was de productie daar nog kleinschalig.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li></ul><h2>Taiwan als whiskymarkt</h2><p>Taiwan koopt ook veel whisky in. In de eerste helft van 2014 was het de vierde exportmarkt voor Scotch, gemeten naar waarde.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Dat is een momentopname; een actueel cijfer hebben we niet.</p><h2>Veel voorkomende misverstanden</h2><ul><li><i>\"Taiwanese whisky heeft een lange traditie.\"</i> Nee. Kavalan stookt pas sinds 2006.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><i>\"Whisky uit een warm land rijpt sneller.\"</i> Dat zegt de producent, maar het is in de kennisbank nog niet onderbouwd.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li></ul><h2>Nog niet uitgezocht</h2><ul><li>De Taiwanese wettelijke regels voor whisky.</li><li>De eigenaar van Kavalan: die wordt vaak genoemd, maar staat niet op de eigen website van de producent. Een bron hebben we nog niet vastgelegd.</li><li>Wat Nantou precies maakt, en onder welke merknaam.</li><li>Of er andere Taiwanese whiskydistilleerderijen zijn.</li><li>Hoe groot de Taiwanese whiskymarkt nu is.</li></ul>","bronnen":[{"n":"AmCham Taiwan - Blossoming of the Taiwan whisky market","t":"The Blossoming of the Taiwan Whisky Market","o":"Taiwan Business TOPICS (AmCham Taiwan)","q":"C","u":"https://topics.amcham.com.tw/2015/01/the-blossoming-of-the-taiwan-whisky-market/","j":"2015-01"},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"Kavalan - Intro","t":"Kavalan Single Malt Whisky — intro","o":"Kavalan (King Car Group — nog bevestigen)","q":"D","u":"https://www.kavalanwhisky.com/en/intro.php","j":""}],"kennis":["Taiwan","Kavalan","Nantou","Whisky","Rijping"]},"verenigde-staten":{"id":"verenigde-staten","soort":"land","t":"Verenigde Staten: veel soorten, elk met eigen regels","k":"In de VS is whisky een wettelijke klasse met een hele reeks typen, van bourbon tot American single malt. Een algemene minimale rijpingstijd kent de wet niet.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>In de Verenigde Staten is 'whisky' een wettelijke klasse. De drank wordt gedistilleerd uit vergist graanbeslag, tot minder dan 95% alcohol, en gebotteld op minimaal 40%.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Binnen die klasse onderscheidt de wet een reeks typen, elk met eigen eisen voor graan, vat en rijping.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Je mag het woord als 'whisky' of als 'whiskey' spellen; beide zijn toegestaan.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Opvallend voor wie de Europese regels kent: de wet noemt geen algemene minimale rijpingstijd.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In deze gids lees je welke soorten er zijn, wat de drooglegging betekende en welke misverstanden vaak rondgaan.</p>","html":"<h2>Wat mag whisky heten?</h2><p>Amerikaanse whisky moet in eikenhouten vaten worden opgeslagen; alleen <span class=\"wl\" data-n=\"Corn Whisky\">corn whisky</span> is daarvan uitgezonderd.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Een minimumduur voor die opslag geldt alleen voor whisky met 'straight' op het etiket: minimaal twee jaar.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Is een whisky jonger dan vier jaar, dan moet de leeftijd op het etiket staan.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Uitzondering is whisky met 'bottled in bond' op het etiket.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><p>Dat betekent in de praktijk: in de EU moet whisky minimaal drie jaar rijpen, in de VS niet.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Voor een vergelijking met andere landen, zie ons overzicht <span class=\"wl\" data-n=\"Wat mag whisky heten - regels per land\">wat mag whisky heten</span>.</p><h2>De belangrijkste soorten</h2><ul><li><b><span class=\"wl\" data-n=\"Bourbon Whisky\">Bourbon</span></b>: minimaal 51% maïs, rijping in nieuwe verkoolde eiken vaten, geen kleur- of smaakstoffen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Verkoold betekent dat de binnenkant van het vat is geschroeid. Bourbon is een beschermd Amerikaans product: hij moet in de VS zijn gedistilleerd en gerijpt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Ook Japan beschermt de naam Bourbon Whisky, via een afspraak met de VS.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b><span class=\"wl\" data-n=\"Rye Whisky (VS)\">Rye whisky</span></b>: minimaal 51% rogge, ook in nieuwe verkoolde eik.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><b><span class=\"wl\" data-n=\"Corn Whisky\">Corn whisky</span></b>: minimaal 80% maïs. Rijpt hij, dan in gebruikte of onverkoolde nieuwe eik.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><b><span class=\"wl\" data-n=\"Straight Whisky (VS)\">Straight whisky</span></b>: minimaal twee jaar in nieuwe verkoolde eik, zonder neutrale alcohol en zonder kleur- of smaakstoffen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><b><span class=\"wl\" data-n=\"Blended Whiskey (VS)\">Blended whiskey</span></b>: minimaal 20% straight whisky, aangevuld met whisky en/of neutrale alcohol, tot maximaal 80% neutrale alcohol.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><b><span class=\"wl\" data-n=\"American Single Malt Whisky\">American single malt</span></b>: 100% gemoute gerst, in één distilleerderij in de VS, gerijpt in eiken vaten van maximaal 700 liter.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Deze categorie geldt sinds 19 januari 2025 en kent geen minimale rijpingsduur.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></li></ul><p>Wil je weten of bourbon uit Kentucky moet komen? Daar hebben we een apart artikel over: <span class=\"wl\" data-n=\"Moet bourbon uit Kentucky komen en hoe lang moet bourbon rijpen\">Moet bourbon uit Kentucky komen en hoe lang moet bourbon rijpen</span>.</p><h2>Drooglegging</h2><p>Vanaf 17 januari 1920 gold in de VS een verbod op het maken, verkopen en vervoeren van alcoholhoudende dranken voor consumptie.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup><sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Ook in- en uitvoer was verboden.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Het verbod verviel op 5 december 1933, toen het 21e amendement werd aangenomen.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Wat de <span class=\"wl\" data-n=\"Amerikaanse drooglegging\">drooglegging</span> precies voor de whiskymakers betekende, hebben we nog niet uitgezocht.</p><h2>Waar komt de naam bourbon vandaan?</h2><p>Het bekende verhaal is dat bourbon zijn naam dankt aan Bourbon County in Kentucky.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Historicus Michael Veach wijst erop dat dit verhaal pas in de jaren 1870 in druk verschijnt, terwijl er al bourbonetiketten zijn uit de jaren 1850.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Hij oppert dat de naam uit New Orleans komt, van Bourbon Street.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Welke verklaring klopt, is niet vastgesteld. Zie <span class=\"wl\" data-n=\"Waar komt de naam bourbon vandaan\">Waar komt de naam bourbon vandaan</span>.</p><h2>Veel voorkomende misverstanden</h2><ul><li><i>\"Bourbon moet uit Kentucky komen.\"</i> Nee. De wet eist alleen dat hij in de VS is gedistilleerd en gerijpt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><i>\"Bourbon moet minimaal twee jaar rijpen.\"</i> Die eis geldt voor straight bourbon, niet voor bourbon zelf.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><i>\"Malt whisky is altijd 100% gerst.\"</i> In de VS is voor malt whisky minimaal 51% gemoute gerst genoeg.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li><i>\"Een Amerikaanse blend is net als een Europese blend.\"</i> Nee. De Amerikaanse blend mag neutrale alcohol bevatten; in de EU mag aan whisky geen alcohol worden toegevoegd.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></li><li><i>\"Whiskey met 'e' is verplicht.\"</i> Nee, beide spellingen mogen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li></ul><h2>Nog niet uitgezocht</h2><ul><li>Wat de drooglegging betekende voor de distilleerderijen en hoe de herstart na 1933 verliep.</li><li>Een korte geschiedenis van whisky in de VS vóór de twintigste eeuw.</li><li>Welke Amerikaanse distilleerderijen er zijn: de kennisbank heeft nog geen notities over Amerikaanse stokerijen.</li><li>Hoeveel bourbon uit Kentucky komt: daar hebben we nog geen betrouwbaar cijfer voor.</li><li>De leeftijdsregel is nagelezen in de officiële jaareditie en via Cornell; een letterlijke controle op eCFR staat nog open.</li></ul>","bronnen":[{"n":"27 CFR 5.143 - Whisky","t":"27 CFR 5.143 — Whisky (Standards of identity, VS)","o":"US Government — TTB / eCFR","q":"A","u":"https://www.ecfr.gov/current/title-27/chapter-I/subchapter-A/part-5/subpart-I/section-5.143","j":""},{"n":"27 CFR 5.74 - Statements of age","t":"27 CFR § 5.74 — Statements of age","o":"US Government (eCFR), via Cornell LII","q":"A","u":"https://www.law.cornell.edu/cfr/text/27/5.74","j":""},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"NTA - Lijst geografische aanduidingen alcoholische dranken","t":"酒類の地理的表示一覧 (lijst geografische aanduidingen voor alcoholische dranken)","o":"National Tax Agency (国税庁), Japan","q":"A","u":"https://www.nta.go.jp/taxes/sake/hyoji/chiri/ichiran.htm","j":"onbekend (laatste aanwijzing in lijst: 2025-10-01)"},{"n":"Federal Register 2024 - TD TTB-199 American Single Malt Whisky","t":"Addition of American Single Malt Whisky to the Standards of Identity for Distilled Spirits (T.D. TTB-199)","o":"Alcohol and Tobacco Tax and Trade Bureau / Federal Register","q":"A","u":"https://www.federalregister.gov/documents/2024/12/18/2024-29938/addition-of-american-single-malt-whisky-to-the-standards-of-identity-for-distilled-spirits","j":"2024-12-18"},{"n":"US Constitution - 18th Amendment","t":"Eighteenth Amendment — Constitution Annotated","o":"US Congress (constitution.congress.gov)","q":"A","u":"https://constitution.congress.gov/constitution/amendment-18/","j":""},{"n":"Constitution Annotated - Overview of Eighteenth Amendment","t":"Overview of Eighteenth Amendment, Prohibition of Liquor — Constitution Annotated","o":"Library of Congress / US Congress (constitution.congress.gov)","q":"A","u":"https://constitution.congress.gov/browse/essay/amdt18-1/ALDE_00099999/","j":""},{"n":"Constitution Annotated - Ratification of the Twenty-First Amendment","t":"Amdt21.S1.2.5 Ratification of the Twenty-First Amendment — Constitution Annotated","o":"Library of Congress / US Congress (constitution.congress.gov)","q":"A","u":"https://constitution.congress.gov/browse/essay/amdt21-S1-2-5/ALDE_00013858/","j":""},{"n":"Smithsonian 2013 - Where bourbon really got its name","t":"Where Bourbon Really Got Its Name and More Tips on America's Native Spirit","o":"Smithsonian Magazine","q":"C","u":"https://www.smithsonianmag.com/arts-culture/where-bourbon-really-got-its-name-and-more-tips-on-americas-native-spirit-145879/","j":"2013-06-13"}],"kennis":["Verenigde Staten","Whisky","Bourbon Whisky","Rye Whisky (VS)","Corn Whisky","Straight Whisky (VS)","Blended Whiskey (VS)","American Single Malt Whisky","Malt whisky","Whisky vs whiskey","Amerikaanse drooglegging","Waar komt de naam bourbon vandaan","Whiskywetgeving per land","Moet bourbon uit Kentucky komen en hoe lang moet bourbon rijpen"]},"wales":{"id":"wales","soort":"land","t":"Wales: wat 'Single Malt Welsh Whisky' op het etiket betekent","k":"Wales heeft een eigen beschermde naam voor whisky: Single Malt Welsh Whisky. Deze gids legt uit wat die naam vraagt, en wat niet.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Wales heeft een eigen beschermde naam voor whisky: Single Malt Welsh Whisky, in het Welsh Wisgi Cymreig Brag Sengl.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het was in 2023 de eerste Britse spirit die na de Brexit een geografische aanduiding (GI) kreeg onder het nieuwe Britse stelsel.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Zo'n GI legt vast wat een whisky moet zijn om die naam te mogen dragen. In deze gids lees je wat de regels vragen. Over de geschiedenis van whisky in Wales en over de makers heeft onze kennisbank nog weinig uitgezocht. Dat zeggen we er eerlijk bij.</p>","html":"<h2>Wat de beschermde naam vraagt</h2><p>De regels staan in de officiële productspecificatie.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Een <span class=\"wl\" data-n=\"Single Malt Welsh Whisky\">Single Malt Welsh Whisky</span>:</p><ul><li>is gedistilleerd in één Welshe distilleerderij, van 100% gemoute gerst, Welsh water en gist;<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li>gebruikt alleen water met een bron in Wales;<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li>is batchgewijs gestookt (per lading, niet continu) in pot stills, met of zonder kolom, of in paren pot stills;<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li>heeft minimaal drie jaar gerijpt in houten vaten, in warehouses in Wales;<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li><li>is gebotteld in Wales, op minimaal 40% vol.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></li></ul><p>De vaten mogen nieuw, gebruikt of opgeknapt ('rejuvenated') zijn. Ze mogen eerder andere alcoholische dranken hebben bevat.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Dat betekent in de praktijk: de regels schrijven geen bepaald soort vat voor.</p><h2>Welshe gerst is geen plicht</h2><p>Een veelgehoord misverstand is dat Welsh whisky van Welshe gerst moet zijn. Dat klopt niet. De gerst hoeft niet uit Wales te komen, en het mouten mag ook buiten Wales.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens de specificatie gebruiken kleinere Welshe distilleerderijen vaak wel Welshe gerst. Het is gebruikelijk, geen eis.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het water moet wél uit Wales komen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Kleurstof</h2><p>De specificatie zegt niets over kleurstof.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Dan gelden de algemene Britse regels voor whisky. In Groot-Brittannië is dat na de Brexit nog de oude Europese verordening 110/2008, in Britse wetgeving overgenomen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Wat die precies zegt over whisky, hebben we nog niet naast de huidige Europese regels gelegd. De Europese regels vind je bij <span class=\"wl\" data-n=\"Whisky\">Whisky</span>.</p><h2>En de smaak?</h2><p>In de regels hierboven staat niets over smaak.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Een smaakstijl voor 'Welsh whisky' beschrijven we daarom niet. Zoek je op smaak, gebruik dan het smaakfilter.</p><h2>Nog niet uitgezocht</h2><ul><li>De geschiedenis van whisky in Wales.</li><li>Welke distilleerderijen er in Wales stoken en wat ze maken.</li><li>Wat de algemene Britse whiskyregels (110/2008) precies zeggen, naast de Europese.</li></ul>","bronnen":[{"n":"UK GI - Single Malt Welsh Whisky specification S0006","t":"Product specification Single Malt Welsh Whisky / Wisgi Cymreig Brag Sengl (S0006)","o":"UK Government (DEFRA) — UK GI-register","q":"A","u":"https://assets.publishing.service.gov.uk/media/62de3755e90e0766afece5d5/Single_Malt_Welsh_Whisky_UK_GI_product_specification_S0006_final_version.pdf","j":"2021-08-12"},{"n":"Just Drinks 2026 - English whisky GI","t":"English whisky receives GI status","o":"Just Drinks","q":"C","u":"https://www.just-drinks.com/news/english-whisky-gi-status/","j":"2026-09-15"},{"n":"Business Companion - Spirit drinks labelling","t":"Labelling and composition of spirit drinks","o":"Business Companion (Chartered Trading Standards Institute, VK)","q":"A","u":"https://www.businesscompanion.info/en/quick-guides/food-and-drink/labelling-and-composition-of-spirit-drinks-s","j":"2025-10"}],"kennis":["Wales","Single Malt Welsh Whisky","Whisky","Whiskywetgeving per land"]},"zwitserland":{"id":"zwitserland","soort":"land","t":"Zwitserland: whisky pas sinds 1999","k":"In Zwitserland was whisky maken tot 1 juli 1999 verboden. Sindsdien stoken brouwerijen en stokerijen er single malt, met een eigen wettelijke definitie.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Zwitserland heeft een korte whiskygeschiedenis, en dat is een bewuste keuze van de wetgever geweest. Tot de zomer van 1999 mocht er geen whisky worden gemaakt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Sinds 1 juli 1999 mag het wel.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Zwitserland is geen EU-lidstaat en heeft een eigen wettelijke definitie van whisky.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> In deze gids lees je hoe het begon, wat de wet zegt en welke distilleerderijen je in de schappen kunt tegenkomen.</p>","html":"<h2>Het einde van een verbod</h2><p>Op 1 juli 1999 vervielen de wetten die whiskyproductie verboden.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens Whisky.com mag pas sinds dat jaar in Zwitserland worden gedistilleerd uit basisvoedsel zoals graan en aardappelen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Boer Ernst Bader uit Lauwil begon dezelfde dag met het stoken van single malt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens swissinfo kon de eerste fles pas vanaf de zomer van 2002 als whisky worden verkocht, omdat whisky eerst drie jaar op vat moet.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Waarom het verbod er was, en sinds wanneer precies, hebben we nog niet met een officiële bron vastgesteld.</p><h2>Wat mag whisky heten?</h2><p>In de Zwitserse verordening over alcoholische dranken (versie 2014) staat een eigen definitie.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Whisky wordt daar gemaakt van een beslag van gemout graan, dat door de eigen enzymen van de mout wordt omgezet in suiker en met gist wordt vergist.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Er wordt gedistilleerd tot minder dan 94,8% alcohol, en de drank rijpt minstens drie jaar in houten vaten van maximaal 700 liter.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Whisky mag niet worden gezoet.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Staat er een leeftijd op het etiket, dan telt het jongste bestanddeel.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><p>Dat lijkt sterk op de EU-regels (zie <span class=\"wl\" data-n=\"Whisky\">Whisky</span>).<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Let wel: de verordening uit 2014 is inmiddels vervangen. Of de definitie in de nieuwe tekst gelijk is gebleven, hebben we nog niet gecontroleerd.</p><h2>Wie er stookt</h2><ul><li><b>Säntis Malt</b> wordt gemaakt door Brauerei Locher in Appenzell, sinds 1886 een brouwerij van de familie Locher.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup><sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> De brouwerij maakt whisky sinds 1999; de eerste whisky kwam in 2002 op de markt.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Een deel van de whisky rijpt in oude eiken biervaten.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup><sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> In de praktijk past dat bij een bedrijf dat van oorsprong brouwt.</li><li><b>Langatun</b> in Aarwangen (kanton Bern) werd in 2005 opgericht door Hans Baumberger.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De familie stookt volgens Whisky.com al sinds 1857.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Langatun heeft drie stills van 500, 250 en 100 liter.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></li></ul><p>Er zijn veel meer Zwitserse whiskymakers, maar een betrouwbaar aantal hebben we nog niet.</p><h2>Nog niet uitgezocht</h2><ul><li>De actuele Zwitserse whiskydefinitie (de verordening is sinds 2017 vervangen).</li><li>De wettelijke achtergrond van het verbod vóór 1999.</li><li>Hoeveel distilleerderijen Zwitserland nu telt.</li><li>Of er een beschermde aanduiding 'Swiss whisky' bestaat.</li></ul>","bronnen":[{"n":"Swissinfo 2000 - Swiss brewers turn their talents to whisky","t":"Swiss brewers turn their talents to whisky","o":"swissinfo.ch (SRG SSR)","q":"C","u":"https://www.swissinfo.ch/eng/banking-fintech/swiss-brewers-turn-their-talents-to-whisky/1449386","j":"2000-03-27"},{"n":"Whisky.com - Langatun distilleerderij","t":"Langatun — whisky database distillery details","o":"Whisky.com (Whisky.de)","q":"C","u":"https://www.whisky.com/whisky-database/distilleries/details/langatun.html","j":""},{"n":"EDI 2013 - Verordnung über alkoholische Getränke (Stand 2014)","t":"Verordnung des EDI über alkoholische Getränke vom 29. November 2013 (SR 817.022.110), Stand am 1. Januar 2014","o":"Eidgenössisches Departement des Innern (EDI), Zwitserland (via LexFind)","q":"A","u":"https://www.lexfind.ch/tolv/148283/de","j":"2013-11-29"},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"Whiskipedia - Brauerei Locher","t":"Brauerei Locher whisky distillery","o":"Whiskipedia","q":"C","u":"https://whiskipedia.com/distilleries/brauerei-locher/","j":""},{"n":"Whisky Connosr (Roskrow) - Santis Whisky Switzerland","t":"Santis Whisky, Switzerland","o":"Whisky Connosr (World Whisky Review, issue 7)","q":"C","u":"https://www.connosr.com/worldwhiskyreview/issue-7/santis-whisky-switzerland/","j":""}],"kennis":["Zwitserland","Whisky"]}},"streek":{"campbeltown":{"id":"campbeltown","soort":"streek","t":"Campbeltown: een kleine beschermde naam op Kintyre","k":"Campbeltown is een van de twee wettelijk beschermde 'localities' voor Scotch. De SWA-kaart van 2025 noemt er drie distilleerderijen: Glen Scotia, Glengyle en Springbank.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Campbeltown is, net als Islay, een wettelijk beschermde 'locality' voor Scotch.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het gebied valt samen met de ward South Kintyre van Argyll and Bute Council.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Op de kaart van de Scotch Whisky Association (SWA) uit 2025 staan er drie distilleerderijen: Glen Scotia, Glengyle en Springbank.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Daarmee is het de kleinste streek op de kaart. Toch heeft Campbeltown een eigen naam in de wet. In deze gids lees je wat die naam betekent, wat we weten over de distilleerderijen en wat we nog niet weten.</p>","html":"<h2>Wat de wet zegt</h2><p>'Campbeltown' mag alleen op <span class=\"wl\" data-n=\"Scotch Whisky\">Scotch Whisky</span> die in dit gebied gedistilleerd is.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Bij een mengsel moet alle whisky erin daar gedistilleerd zijn.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Namen die er verwarrend veel op lijken, zijn verboden.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Een smaak of stijl schrijft de wet niet voor.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Wie er stookt</h2><p><b><span class=\"wl\" data-n=\"Springbank\">Springbank</span></b> is van het familiebedrijf J&amp;A Mitchell &amp; Co.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Volgens de producent kreeg Springbank in 1828 een vergunning, als veertiende vergunde distilleerderij van Campbeltown.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Op die plek zou eerder een illegale stokerij van Archibald Mitchell hebben gestaan. Dat is een familieverhaal, geen vastgesteld feit.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></p><p>Springbank doet volgens eigen zeggen het hele productieproces zelf, van mouten tot bottelen.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Alle gerst wordt er gemout op een traditionele moutvloer (floor malting).<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Daarbij kiemt de geweekte gerst op een vloer en wordt ze met de hand gekeerd.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Een vakblad uit 2014 beschrijft één wash still en twee spirit stills, met worm tubs.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Dat zijn koperen spiralen in een bak koud water, waarin de alcoholdamp weer vloeibaar wordt.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup></p><p>Uit die drie ketels komen drie merken, elk met een eigen manier van distilleren:<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup></p><ul><li><b>Springbank</b>: 2,5 keer gedistilleerd.</li><li><b>Longrow</b>: 2 keer, en geturfd (sinds 1973).<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b>Hazelburn</b>: 3 keer (sinds 1997).<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li></ul><p>Springbank wordt volgens de producent niet koudgefilterd en zonder kleurstof gebotteld.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup></p><p><b>Glengyle</b> is ook van J&amp;A Mitchell.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> De herbouwde distilleerderij ging in 2004 weer open.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Volgens J&amp;A Mitchell was dat de eerste nieuwe distilleerderij in Campbeltown in ruim honderd jaar, en de eerste die in Schotland in de 21e eeuw werd gebouwd.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Dat laatste is een claim die we nog niet hebben getoetst.</p><p>Over <b>Glen Scotia</b> staat nog niets in onze kennisbank, behalve dat hij op de SWA-kaart staat.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><h2>Wat je wel en niet uit 'Campbeltown' kunt afleiden</h2><p>De naam zegt waar de whisky gedistilleerd is, niet hoe hij smaakt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Met drie distilleerderijen en drie heel verschillende Springbank-merken is één 'Campbeltown-smaak' ook lastig te geven. Zoek je op smaak, gebruik dan het smaakfilter.</p><h2>Nog niet uitgezocht</h2><ul><li>Hoeveel distilleerderijen Campbeltown vroeger had en waarom de meeste verdwenen.</li><li>Gegevens over Glen Scotia: oprichting, eigenaar, productie.</li><li>Onder welke merknaam Glengyle zijn whisky verkoopt en waarom.</li><li>Of de claim 'eerste distilleerderij van de 21e eeuw' klopt.</li></ul>","bronnen":[{"n":"Scotch Whisky Regulations 2009","t":"The Scotch Whisky Regulations 2009 (SI 2009/2890)","o":"UK Government","q":"A","u":"https://www.legislation.gov.uk/uksi/2009/2890","j":"2009"},{"n":"Scotch Whisky Technical File 2019","t":"Technical File for Scotch Whisky (juni 2019)","o":"UK Government (Defra)","q":"A","u":"https://assets.publishing.service.gov.uk/media/5fd36667e90e07662ed92c85/Scotch_Whisky_Technical_File_-_June_2019.pdf","j":"2019-06"},{"n":"SWA - Big Map of Scotch Whisky 2025","t":"Big Map of Scotch Whisky (editie juli 2025)","o":"Scotch Whisky Association","q":"A","u":"https://www.scotch-whisky.org.uk/media/2492/big-map-of-scotch-whisky-scotch-whisky-association-2025.pdf","j":"2025-07"},{"n":"Springbank - Story","t":"Story — Springbank","o":"J&A Mitchell & Co","q":"D","u":"https://www.springbank.scot/about/story/","j":""},{"n":"Springbank - Distillery","t":"Distillery — Springbank","o":"Springbank (J&A Mitchell)","q":"D","u":"https://www.springbank.scot/about/distillery/","j":"ONBEKEND"},{"n":"Edinburgh Whisky Academy 2025 - Floor maltings","t":"Scotch Whisky Distilleries with On-Site Floor Maltings","o":"Edinburgh Whisky Academy","q":"C","u":"https://www.edinburghwhiskyacademy.com/blogs/feature/scotch-whisky-distilleries-with-on-site-floor-maltings","j":"2025-02-05"},{"n":"Brewer and Distiller International 2014 - Campbeltown","t":"Campbeltown (Distillery profiles)","o":"Brewer & Distiller International (IBD)","q":"C","u":"https://www.cibd.org.uk/media/5e2hin4o/5-campbeltown.pdf","j":"2014-05"},{"n":"Oxford Companion to Spirits and Cocktails - Worm","t":"worm — The Oxford Companion to Spirits & Cocktails","o":"Oxford University Press","q":"B","u":"https://www.spiritsanddistilling.com/dictionary/acref-9780199311132-e-723","j":"2021"},{"n":"Springbank - Process","t":"Process — Springbank","o":"J&A Mitchell & Co","q":"D","u":"https://www.springbank.scot/about/process/","j":""}],"kennis":["Campbeltown","Schotland","Scotch Whisky","Springbank","J&A Mitchell & Co","Floor maltings","Redactiebesluiten Jack"]},"highland":{"id":"highland","soort":"streek","t":"Highland: de grootste whiskyregio, met een lijn als grens","k":"Highland is wettelijk alles ten noorden van de Highland-Lowland-lijn. Op de SWA-kaart van 2025 is het de regio met de meeste distilleerderijen: 56, inclusief de eilanden.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Highland is een van de drie wettelijk beschermde whiskyregio's van Schotland.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De wet trekt de grens met een lijn dwars door het land: alles ten noorden ervan is Highland, alles ten zuiden Lowland.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Op de kaart van de Scotch Whisky Association (SWA) uit 2025 staan in Highland 56 distilleerderijen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Daar horen ook de eilanddistilleerderijen bij, zoals Talisker en Highland Park.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Op Whiskysite tonen we die apart onder Islands.</p>","html":"<h2>Wat de wet zegt</h2><p>De naam 'Highland' mag alleen op <span class=\"wl\" data-n=\"Scotch Whisky\">Scotch Whisky</span> die in het gebied gedistilleerd is.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Bij een mengsel moet alle whisky erin daar gedistilleerd zijn.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Verwarrend gelijkende namen zijn verboden.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><p>De scheidslijn staat in de regeling zelf beschreven. Samengevat loopt hij van de Firth of Clyde bij Greenock via de Campsie Fells en het Wallace Monument naar Milnathort, dan langs de rivier de Earn naar de Tay en via de Firth of Tay naar de Noordzee.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></p><h2>Highland, Speyside en de eilanden</h2><p><span class=\"wl\" data-n=\"Speyside\">Speyside</span> ligt ten noorden van de lijn. In de praktijk valt Speyside dus ook binnen 'Highland', al noemt de wet die overlap niet.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Daarom kan <span class=\"wl\" data-n=\"Glenfarclas\">Glenfarclas</span>, een Speyside-distilleerderij op de SWA-kaart, zijn whisky 'Highland Single Malt' noemen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Op Whiskysite is Speyside een eigen streek; Glenfarclas noemen we als uitzondering.</p><p>De SWA-kaart deelt ook de eilanddistilleerderijen bij Highland in, behalve die op Islay.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Islay heeft een eigen beschermde naam.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Op de site groeperen we de overige eilanden onder <span class=\"wl\" data-n=\"Islands\">Islands</span>, omdat dat een gangbare indeling is. Een wettelijke regio is Islands niet.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Wie er stookt op het vasteland</h2><ul><li><b><span class=\"wl\" data-n=\"Dalmore\">Dalmore</span></b> ligt aan de Cromarty Firth en werd volgens de producent in 1839 opgericht door Alexander Matheson.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Sinds 1960 is hij van Whyte &amp; Mackay.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup><sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> In 1917–1920 werd het terrein gevorderd als mijnenfabriek, en een explosie richtte schade aan.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></li><li><b><span class=\"wl\" data-n=\"Glenmorangie\">Glenmorangie</span></b> in Tain werd volgens de eigenaar in 1843 opgericht door William en Anne Matheson.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Hij hoort bij Moët Hennessy (LVMH).<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Glenmorangie zegt de hoogste ketels van Schotland te hebben, 5,14 meter.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Die hoogte is te meten, maar 'de hoogste' is niet onafhankelijk getoetst.</li><li><b><span class=\"wl\" data-n=\"Oban\">Oban</span></b> staat midden in de stad Oban en werd volgens eigenaar Diageo in 1794 opgericht door John en Hugh Stevenson.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Volgens Diageo bestond de distilleerderij al voordat Oban een vissersplaats werd.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Dat is nog niet onafhankelijk bevestigd.</li></ul><p>Van andere vastelanddistilleerderijen kennen we vooralsnog vooral de eigenaar. John Dewar &amp; Sons (Bacardi) heeft <span class=\"wl\" data-n=\"Aberfeldy\">Aberfeldy</span>, <span class=\"wl\" data-n=\"Macduff\">Macduff</span> en <span class=\"wl\" data-n=\"Royal Brackla\">Royal Brackla</span>.<sup class=\"fn\"><a href=\"#bn-10\">10</a></sup> Inver House heeft <span class=\"wl\" data-n=\"Balblair\">Balblair</span> en <span class=\"wl\" data-n=\"Pulteney\">Pulteney</span>.<sup class=\"fn\"><a href=\"#bn-11\">11</a></sup> <span class=\"wl\" data-n=\"Fettercairn\">Fettercairn</span> is van Whyte &amp; Mackay.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> <span class=\"wl\" data-n=\"Ardmore\">Ardmore</span> en <span class=\"wl\" data-n=\"Glen Garioch\">Glen Garioch</span> horen bij Suntory Global Spirits.<sup class=\"fn\"><a href=\"#bn-12\">12</a></sup> Volgens die eigenaar is Ardmore gebouwd in 1898 en bestaat Glen Garioch sinds 1797.<sup class=\"fn\"><a href=\"#bn-12\">12</a></sup> Diageo heeft onder meer <span class=\"wl\" data-n=\"Blair Athol\">Blair Athol</span>, <span class=\"wl\" data-n=\"Royal Lochnagar\">Royal Lochnagar</span>, <span class=\"wl\" data-n=\"Brora\">Brora</span> en <span class=\"wl\" data-n=\"Glen Ord\">Glen Ord</span>.<sup class=\"fn\"><a href=\"#bn-13\">13</a></sup><sup class=\"fn\"><a href=\"#bn-14\">14</a></sup> Verder staan op de SWA-lijst onder meer Ben Nevis, Clynelish, Dalwhinnie, Deanston, Edradour, Glengoyne, Glenturret, Tomatin en Tullibardine.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><h2>Wat je wel en niet uit 'Highland' kunt afleiden</h2><p>'Highland' zegt alleen dat de whisky ten noorden van de lijn gedistilleerd is.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Dat zegt iets over de plek, niet over de stijl. Een vaste smaak koppelt de wet er niet aan.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Wij hebben ook geen bron die één Highland-smaak onderbouwt. Zoek je op smaak, gebruik dan het smaakfilter.</p><h2>Nog niet uitgezocht</h2><ul><li>Hoe de Highland-Lowland-lijn historisch is ontstaan.</li><li>De letterlijke tekst van de scheidslijn in de geldende wetsversie.</li><li>Of alle 56 namen op de SWA-kaart nu actief zijn, en welke daarvan precies op een eiland liggen.</li><li>Of Dalmore en Glenmorangie, beide door een Matheson opgericht, familie van elkaar zijn.</li></ul>","bronnen":[{"n":"Scotch Whisky Regulations 2009","t":"The Scotch Whisky Regulations 2009 (SI 2009/2890)","o":"UK Government","q":"A","u":"https://www.legislation.gov.uk/uksi/2009/2890","j":"2009"},{"n":"SWR 2009 - kopie Clydesdale","t":"The Scotch Whisky Regulations 2009 — kopie van de SI-tekst (Clydesdale)","o":"Clydesdale (herpublicatie van SI 2009/2890)","q":"A","u":"https://www.clydesdale.se/press/SWR2009Guidance.pdf","j":"2009-11-23"},{"n":"SWA - Big Map of Scotch Whisky 2025","t":"Big Map of Scotch Whisky (editie juli 2025)","o":"Scotch Whisky Association","q":"A","u":"https://www.scotch-whisky.org.uk/media/2492/big-map-of-scotch-whisky-scotch-whisky-association-2025.pdf","j":"2025-07"},{"n":"Scotch Whisky Technical File 2019","t":"Technical File for Scotch Whisky (juni 2019)","o":"UK Government (Defra)","q":"A","u":"https://assets.publishing.service.gov.uk/media/5fd36667e90e07662ed92c85/Scotch_Whisky_Technical_File_-_June_2019.pdf","j":"2019-06"},{"n":"Glenfarclas - Family","t":"Family — Glenfarclas","o":"J. & G. Grant","q":"D","u":"https://glenfarclas.com/family/","j":""},{"n":"The Dalmore - History","t":"The History of The Dalmore","o":"The Dalmore (Whyte & Mackay)","q":"D","u":"https://www.thedalmore.com/en/our-world/history-of-the-dalmore/","j":""},{"n":"Whyte & Mackay - Locations","t":"Locations — Whyte & Mackay","o":"Whyte & Mackay","q":"D","u":"https://careers.whyteandmackay.com/locations","j":""},{"n":"LVMH - Glenmorangie","t":"Glenmorangie — LVMH","o":"LVMH","q":"D","u":"https://www.lvmh.com/en/our-maisons/wines-spirits/glenmorangie","j":""},{"n":"Malts.com - Oban","t":"Oban Distillery — Malts.com","o":"Diageo","q":"D","u":"https://www.malts.com/en-gb/distilleries/oban","j":""},{"n":"Bacardi 2014 - Last Great Malts","t":"John Dewar & Sons launches Last Great Malts collection","o":"Bacardi Limited","q":"D","u":"https://www.bacardilimited.com/media/news-archive/john-dewar-sons-launches-last-great-malts-collection-new-expressions-and-never-before-released-single-malts/","j":"2014-09-24"},{"n":"International Beverage - Our History","t":"Our history — International Beverage","o":"International Beverage Holdings (ThaiBev)","q":"D","u":"https://www.interbevgroup.com/our-group/our-history","j":""},{"n":"Suntory Global Spirits - Our Locations","t":"Our Locations — Suntory Global Spirits","o":"Suntory Global Spirits","q":"D","u":"https://www.suntoryglobalspirits.com/about-us/our-locations","j":""},{"n":"Malts.com - Distilleries","t":"Distilleries — Malts.com","o":"Diageo","q":"D","u":"https://www.malts.com/en-gb/distilleries","j":""},{"n":"Diageo - Our Scotch Whisky Portfolio","t":"Our Scotch Whisky Portfolio","o":"Diageo plc","q":"D","u":"https://www.diageo.com/en/our-brands/scotch-whisky","j":""}],"kennis":["Highland","Speyside","Islands","Schotland","Scotch Whisky","Dalmore","Glenmorangie","Oban","Glenfarclas","Whiskybedrijven Schotland","Redactiebesluiten Jack"]},"islands":{"id":"islands","soort":"streek","t":"Islands: een gangbare indeling, geen wettelijke regio","k":"'Islands' staat niet in de Schotse whiskywet; formeel vallen deze distilleerderijen onder Highland. Wij tonen ze apart, zodat je de eilandwhisky's buiten Islay bij elkaar vindt.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Misschien heb je gelezen dat Schotland zes whiskyregio's heeft, waaronder Islands. Dat klopt niet: in de wet staat Islands niet.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De Scotch Whisky Regulations 2009 kennen drie regio's (Highland, Lowland en Speyside) en twee kleinere 'localities' (Campbeltown en Islay).<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De Scotch Whisky Association deelt de eilanddistilleerderijen op haar kaart van 2025 in bij Highland.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Toch tonen wij ze op Whiskysite apart. In deze gids lees je waarom, en wat je wel en niet uit 'Islands' kunt afleiden.</p>","html":"<h2>Waarom wij Islands apart tonen</h2><p>'Islands' is een gangbare indeling, geen wettelijke. Wij gebruiken hem als zoekhulp: zo vind je de whisky's van de eilanden rond Schotland bij elkaar, los van het vasteland van <span class=\"wl\" data-n=\"Highland\">Highland</span>. Islay valt er niet onder. Dat eiland heeft een eigen, wettelijk beschermde naam.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Zie daarvoor de gids over <span class=\"wl\" data-n=\"Islay\">Islay</span>.</p><h3>Waarom niet samen met Islay?</h3><p>Islay en Islands worden makkelijk verward, en de vraag ligt voor de hand: is het niet gewoon één eilandstreek? Er is iets voor te zeggen. Beide gaan over eilanden, en wie 'eilandwhisky' zoekt, denkt aan allebei. Toch houden wij ze apart. Islay is een wettelijk beschermde naam: die mag alleen op whisky die op Islay gedistilleerd is.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Islands is dat niet; formeel horen deze eilanden bij Highland.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Voegen we ze samen, dan staat een whisky van een ander eiland onder een naam die hij wettelijk niet mag dragen. Twee aparte streken houdt dat verschil zichtbaar, en past bij hoe klanten zoeken.</p><h2>Wie er stookt</h2><p>De SWA-kaart noemt onder Highland onder meer Talisker, Highland Park en Isle of Jura als eilanddistilleerderijen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Ook namen als Isle of Harris, Isle of Raasay en Isle of Tiree staan op die lijst.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><ul><li><b><span class=\"wl\" data-n=\"Highland Park\">Highland Park</span></b> staat in Kirkwall op Orkney en is een merk van Edrington.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Volgens de producent kreeg Magnus Eunson in 1798 een vergunning.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Het verhaal dat Eunson, kerkdienaar én smokkelaar, whisky onder de preekstoel verstopte, is een legende van het huis.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Highland Park mout nog een deel van zijn gerst zelf op een moutvloer, met eigen turf van Hobbister Moor.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Volgens een vakbron gaat het om ongeveer 20% van de mout per mash; de rest is ongeturfd en komt van het vasteland.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> De producent noemt het heideturf en zegt de enige distilleerderij ter wereld te zijn die deze turf gebruikt.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Dat laatste is een claim.</li><li><b><span class=\"wl\" data-n=\"Talisker\">Talisker</span></b> staat in Carbost op Skye.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Volgens eigenaar Diageo opgericht in 1830 door de gebroeders MacAskill.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Diageo noemt Talisker de oudste werkende distilleerderij op Skye.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Dat is een claim van de producent.</li><li><b><span class=\"wl\" data-n=\"Isle of Jura\">Isle of Jura</span></b> is van Whyte &amp; Mackay.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Verder weten we er nog weinig over.</li></ul><h2>Wat je wel en niet uit 'Islands' kunt afleiden</h2><p>Omdat 'Islands' geen wettelijke regio is, hoort er ook geen wettelijke regel of stijl bij.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De eilanden liggen bovendien ver uit elkaar, van Orkney tot Skye.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Wel interessant: turf verschilt per vindplaats. Onderzoekers vonden in turf van Orkney meer koolhydraatderivaten en aromatische koolwaterstoffen dan in turf van Islay.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Ze schrijven dat dit de smaak <i>mogelijk</i> beïnvloedt.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Bewezen is dat niet. Zoek je op smaak, gebruik dan het smaakfilter.</p><h2>Nog niet uitgezocht</h2><ul><li>Waar de indeling 'Islands' vandaan komt en welke eilanden er in gangbaar gebruik onder vallen.</li><li>Welke distilleerderijen van de SWA-lijst precies op een eiland liggen (bijvoorbeeld <span class=\"wl\" data-n=\"Scapa\">Scapa</span>, waarvan we de ligging nog niet hebben vastgelegd).</li><li>Of de verschillen in turf echt in de whisky te proeven zijn.</li></ul>","bronnen":[{"n":"Scotch Whisky Regulations 2009","t":"The Scotch Whisky Regulations 2009 (SI 2009/2890)","o":"UK Government","q":"A","u":"https://www.legislation.gov.uk/uksi/2009/2890","j":"2009"},{"n":"SWA - Big Map of Scotch Whisky 2025","t":"Big Map of Scotch Whisky (editie juli 2025)","o":"Scotch Whisky Association","q":"A","u":"https://www.scotch-whisky.org.uk/media/2492/big-map-of-scotch-whisky-scotch-whisky-association-2025.pdf","j":"2025-07"},{"n":"Highland Park - Our story","t":"Our Story — Highland Park","o":"Highland Park (Edrington)","q":"D","u":"https://www.highlandparkwhisky.com/en/our-story","j":""},{"n":"Edrington - Our Company","t":"Our Company — Edrington","o":"Edrington","q":"D","u":"https://www.edrington.com/en/our-company","j":""},{"n":"Highland Park - Craft (producentpagina)","t":"Craft — Highland Park","o":"Highland Park (Edrington)","q":"D","u":"https://www.highlandparkwhisky.com/en/brand-story/craft","j":""},{"n":"Scotchwhisky.com - Whiskypedia Highland Park","t":"Highland Park (Whiskypedia)","o":"Scotchwhisky.com","q":"C","u":"https://scotchwhisky.com/whiskypedia/1867/highland-park/","j":"onbekend"},{"n":"Malts.com - Talisker","t":"Talisker Distillery — Malts.com","o":"Diageo","q":"D","u":"https://www.malts.com/en-gb/distilleries/talisker","j":""},{"n":"Whyte & Mackay - Locations","t":"Locations — Whyte & Mackay","o":"Whyte & Mackay","q":"D","u":"https://careers.whyteandmackay.com/locations","j":""},{"n":"Harrison en Priest 2009 - Composition of peats","t":"Composition of Peats Used in the Preparation of Malt for Scotch Whisky Production — Influence of Geographical Source and Extraction Depth","o":"Journal of Agricultural and Food Chemistry","q":"B","u":"https://pubmed.ncbi.nlm.nih.gov/19243172/","j":"2009"}],"kennis":["Islands","Highland","Islay","Schotland","Highland Park","Talisker","Isle of Jura","Turf","Floor maltings"]},"islay":{"id":"islay","soort":"streek","t":"Islay: één eiland, een beschermde naam en meer dan één stijl","k":"Islay is een van de twee wettelijk beschermde 'localities' voor Scotch. Op de whiskykaart van de Scotch Whisky Association staan er tien distilleerderijen, van zwaar geturfd tot bewust ongeturfd.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Islay is een Schots eiland in Argyll.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De naam is wettelijk beschermd. Staat 'Islay' op een fles Scotch, dan moet de whisky op het eiland gedistilleerd zijn.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De Scotch Whisky Association (SWA) zet er op haar kaart van 2025 tien distilleerderijen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Denk je bij Islay meteen aan turfrook? Dat geldt niet voor alles wat er gestookt wordt. Hieronder lees je wat de naam wettelijk betekent en wat je er níét uit kunt afleiden.</p>","html":"<h2>Wat de wet zegt</h2><p>De Scotch Whisky Regulations 2009 noemen Islay een beschermde 'locality'.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De regel is streng: de naam mag alleen op <span class=\"wl\" data-n=\"Scotch Whisky\">Scotch Whisky</span> die op Islay is gedistilleerd.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Bij een mengsel moet álle whisky erin daar gedistilleerd zijn.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Namen die er verwarrend veel op lijken, zijn verboden.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Wie er stookt</h2><p>Op de SWA-kaart staan Ardbeg, Ardnahoe, Bowmore, Bruichladdich, Bunnahabhain, Caol Ila, Kilchoman, Lagavulin, Laphroaig en Port Ellen.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><ul><li><b><span class=\"wl\" data-n=\"Laphroaig\">Laphroaig</span></b> begon volgens de producent eind 1815, met de broers Donald en Alexander Johnston.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Eigenaar is nu Suntory Global Spirits.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b><span class=\"wl\" data-n=\"Ardbeg\">Ardbeg</span></b> kreeg in 1815 een vergunning op naam van John Macdougall, aldus de eigenaar.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Sinds 1997 hoort Ardbeg bij The Glenmorangie Company (LVMH).<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup><sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Tussen 1981 en 1997 lag de distilleerderij grotendeels stil.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></li><li><b><span class=\"wl\" data-n=\"Lagavulin\">Lagavulin</span></b> ligt aan de zuidkust, zo'n 3 km buiten Port Ellen.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Volgens eigenaar Diageo opgericht in 1816 door John Johnston, en zwaar geturfd.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup></li><li><b><span class=\"wl\" data-n=\"Caol Ila\">Caol Ila</span></b>, bij Port Askaig, is volgens Diageo actief sinds 1846 en maakt zowel ongeturfde als geturfde single malt.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup></li><li><b><span class=\"wl\" data-n=\"Bowmore\">Bowmore</span></b> in het gelijknamige dorp heeft eigen floor maltings: een moutvloer waar een deel van de gerst nog zelf wordt gemout.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Over het oprichtingsjaar verschillen de bronnen (zie hieronder).</li><li><b><span class=\"wl\" data-n=\"Bruichladdich\">Bruichladdich</span></b> werd in 1881 opgericht, sloot in 1994 en distilleert sinds 2001 weer.<sup class=\"fn\"><a href=\"#bn-10\">10</a></sup> Sinds 2012 is Rémy Cointreau eigenaar.<sup class=\"fn\"><a href=\"#bn-11\">11</a></sup></li><li><b><span class=\"wl\" data-n=\"Bunnahabhain\">Bunnahabhain</span></b> werd in 1880–1881 gebouwd door The Islay Distillery Company.<sup class=\"fn\"><a href=\"#bn-12\">12</a></sup> Sinds 2023 hoort hij bij CVH Spirits.<sup class=\"fn\"><a href=\"#bn-13\">13</a></sup></li><li><b><span class=\"wl\" data-n=\"Kilchoman\">Kilchoman</span></b> is in 2005 opgericht door Anthony en Kathy Wills.<sup class=\"fn\"><a href=\"#bn-14\">14</a></sup> Volgens de producent teelt hij een deel van zijn gerst zelf, op Rockside Farm.<sup class=\"fn\"><a href=\"#bn-14\">14</a></sup></li><li><b><span class=\"wl\" data-n=\"Port Ellen\">Port Ellen</span></b> is van Diageo.<sup class=\"fn\"><a href=\"#bn-15\">15</a></sup></li></ul><h2>Bowmore: 1779 of 1816?</h2><p>Bowmore zegt dat de naam van de distilleerderij in 1779 voor het eerst is vastgelegd.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Bowmore noemt zich ook de oudste distilleerderij van Islay.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Dat is een claim van de producent. Archivaris Iain Russell schrijft dat accijnsstukken wijzen op een start in 1816.<sup class=\"fn\"><a href=\"#bn-16\">16</a></sup> Een tekst van de Schotse erfgoeddienst noemt wél 1779, maar zonder bewijsstuk.<sup class=\"fn\"><a href=\"#bn-17\">17</a></sup> Wij tonen op de site 1779, zoals Bowmore zelf doet. Het historische bewijs wijst voorlopig op 1816.</p><h2>Islay of Islands?</h2><p>De namen lijken op elkaar, maar het zijn twee verschillende indelingen. Islay is één eiland met een wettelijk beschermde naam.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> 'Islands' is een verzamelnaam uit de handel voor de andere whisky-eilanden rond Schotland. Die naam staat niet in de wet.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Op de kaart van de Scotch Whisky Association vallen de eilanddistilleerderijen buiten Islay onder Highland.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Whisky die niet op Islay gedistilleerd is, mag de naam Islay niet dragen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><p>Je zou ze kunnen samenvoegen tot één groep 'eilandwhisky'. Dat doen wij bewust niet. Dan zou een whisky van een ander eiland naast flessen met de beschermde naam Islay staan, alsof hij daar vandaan komt. Daarom tonen wij Islay en Islands als twee aparte streken, elk met een eigen gids. Zie ook de gids over <span class=\"wl\" data-n=\"Islands\">Islands</span>.</p><h2>Wat je wel en niet uit 'Islay' kunt afleiden</h2><p>'Islay' op het etiket zegt waar de whisky gedistilleerd is.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Over smaak zegt de wet niets.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> En 'Islay' betekent niet automatisch turf. Bruichladdich maakt zijn gelijknamige merk ongeturfd en zijn merken Port Charlotte en Octomore geturfd.<sup class=\"fn\"><a href=\"#bn-10\">10</a></sup> De kernstijl van Bunnahabhain is volgens de producent ongeturfd.<sup class=\"fn\"><a href=\"#bn-18\">18</a></sup> En geturfd is niet overal even sterk. De eigenaar noemt 55 ppm fenol voor Ardbeg Ten.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Kilchoman noemt ongeveer 20 ppm voor mout van zijn eigen moutvloer.<sup class=\"fn\"><a href=\"#bn-19\">19</a></sup> (ppm fenol is een maat voor hoeveel turfrook de mout heeft opgenomen.)</p><p>Turf van Islay is ook scheikundig onderzocht. Het bevat meer stikstofverbindingen dan turf van Orkney.<sup class=\"fn\"><a href=\"#bn-20\">20</a></sup> De onderzoekers schrijven dat zulke verschillen de smaak <i>mogelijk</i> beïnvloeden.<sup class=\"fn\"><a href=\"#bn-20\">20</a></sup> Bewezen is dat niet. Zoek je een rokerige whisky? Gebruik dan het smaakfilter; dat kijkt per fles in plaats van per eiland.</p><h2>Nog niet uitgezocht</h2><ul><li>Hoe de whiskygeschiedenis van het eiland verliep en hoe de indeling is ontstaan.</li><li>Of alle tien distilleerderijen op de SWA-kaart nu actief zijn (Port Ellen, Ardnahoe).</li><li>Of je kunt zeggen dat Islay-whisky 'vaak' rokerig is. Daar hebben we nog geen onafhankelijke bron voor.</li><li>Het oprichtingsjaar van Bowmore met een primaire bron (de accijnsstukken zelf).</li></ul>","bronnen":[{"n":"Scotch Whisky Regulations 2009","t":"The Scotch Whisky Regulations 2009 (SI 2009/2890)","o":"UK Government","q":"A","u":"https://www.legislation.gov.uk/uksi/2009/2890","j":"2009"},{"n":"Scotch Whisky Technical File 2019","t":"Technical File for Scotch Whisky (juni 2019)","o":"UK Government (Defra)","q":"A","u":"https://assets.publishing.service.gov.uk/media/5fd36667e90e07662ed92c85/Scotch_Whisky_Technical_File_-_June_2019.pdf","j":"2019-06"},{"n":"SWA - Big Map of Scotch Whisky 2025","t":"Big Map of Scotch Whisky (editie juli 2025)","o":"Scotch Whisky Association","q":"A","u":"https://www.scotch-whisky.org.uk/media/2492/big-map-of-scotch-whisky-scotch-whisky-association-2025.pdf","j":"2025-07"},{"n":"Laphroaig - Heritage","t":"Heritage of Laphroaig Whisky","o":"Laphroaig (Suntory Global Spirits)","q":"D","u":"https://www.laphroaig.com/heritage","j":""},{"n":"Ardbeg - History","t":"Ardbeg History — Since 1815","o":"Ardbeg (The Glenmorangie Company / LVMH)","q":"D","u":"https://www.ardbeg.com/en-int/pages/history","j":""},{"n":"LVMH - Ardbeg","t":"Ardbeg — LVMH Wines & Spirits","o":"LVMH","q":"D","u":"https://www.lvmh.com/en/our-maisons/wines-spirits/ardbeg","j":""},{"n":"Malts.com - Lagavulin","t":"Lagavulin Distillery — Malts.com","o":"Diageo","q":"D","u":"https://www.malts.com/en-gb/distilleries/lagavulin","j":""},{"n":"Malts.com - Caol Ila","t":"Caol Ila Distillery — Malts.com","o":"Diageo","q":"D","u":"https://www.malts.com/en-gb/distilleries/caol-ila","j":""},{"n":"Bowmore - Our story","t":"Our Story — Bowmore","o":"Bowmore (Suntory Global Spirits)","q":"D","u":"https://www.bowmore.com/our-story","j":""},{"n":"Remy Cointreau - Bruichladdich","t":"Bruichladdich – Port Charlotte – Octomore","o":"Rémy Cointreau","q":"D","u":"https://www.remy-cointreau.com/en/brands/bruichladdich-port-charlotte-octomore/","j":""},{"n":"Moodie Davitt 2012 - Remy Cointreau completes Bruichladdich acquisition","t":"Rémy Cointreau completes acquisition of Bruichladdich single malt","o":"The Moodie Davitt Report","q":"C","u":"https://moodiedavittreport.com/remy-cointreau-completes-acquisition-of-bruichladdich-single-malt/","j":"2012-09"},{"n":"Canmore - Bunnahabhain Distillery event 695886","t":"Bunnahabhain Distillery (Canmore event 695886)","o":"Canmore / Historic Environment Scotland","q":"B","u":"https://canmore.org.uk/event/695886","j":""},{"n":"Remgro 2025 - Integrated Annual Report Investment reviews","t":"Integrated Annual Report 2025 — Investment reviews","o":"Remgro Limited","q":"A","u":"https://www.remgro.com/ar2025/pdf/eng/Investment-Reviews.pdf","j":"2025 (boekjaar tot 30-06-2025)"},{"n":"Kilchoman - Our farm distillery","t":"Our Farm Distillery — Kilchoman","o":"Kilchoman Distillery","q":"D","u":"https://www.kilchomandistillery.com/our-farm-distillery/","j":""},{"n":"Diageo - Our Scotch Whisky Portfolio","t":"Our Scotch Whisky Portfolio","o":"Diageo plc","q":"D","u":"https://www.diageo.com/en/our-brands/scotch-whisky","j":""},{"n":"University of Glasgow 2007 - Distilling the truth","t":"Distilling the truth","o":"University of Glasgow","q":"B","u":"https://www.gla.ac.uk/news/archiveofnews/2007/december/headline_59917_en.html","j":"2007-12-19"},{"n":"Canmore - Bowmore Distillery plan SC 416703","t":"Bowmore Distillery (land- en eigendomsplan, SC 416703)","o":"Historic Environment Scotland / Canmore (tekst RCAHMS voor SCRAN)","q":"B","u":"https://canmore.org.uk/collection/416703","j":""},{"n":"Bunnahabhain - Our story","t":"Our Story — Bunnahabhain","o":"Bunnahabhain Distillery","q":"D","u":"https://bunnahabhain.com/our-story/","j":""},{"n":"Kilchoman 2022 - What is traditional floor malting","t":"What is Traditional Floor Malting? This is how we do it at Kilchoman","o":"Kilchoman Distillery","q":"D","u":"https://www.kilchomandistillery.com/distillery-news/what-is-traditional-floor-malting-this-is-how-we-do-it-at-kilchoman/","j":"2022-02-09"},{"n":"Harrison en Priest 2009 - Composition of peats","t":"Composition of Peats Used in the Preparation of Malt for Scotch Whisky Production — Influence of Geographical Source and Extraction Depth","o":"Journal of Agricultural and Food Chemistry","q":"B","u":"https://pubmed.ncbi.nlm.nih.gov/19243172/","j":"2009"}],"kennis":["Islay","Schotland","Scotch Whisky","Single Malt Scotch Whisky","Ardbeg","Bowmore","Bruichladdich","Bunnahabhain","Caol Ila","Kilchoman","Lagavulin","Laphroaig","Port Ellen","Turf","Redactiebesluiten Jack"]},"lowland":{"id":"lowland","soort":"streek","t":"Lowland: alles ten zuiden van de lijn","k":"Lowland is wettelijk het deel van Schotland ten zuiden van de Highland-Lowland-lijn. De SWA-kaart van 2025 noemt er 23 distilleerderijen, waaronder Auchentoshan, Glenkinchie en het heropende Rosebank.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Lowland is een van de drie wettelijk beschermde whiskyregio's van Schotland.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het is het deel van het land ten zuiden van de Highland-Lowland-lijn.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Die lijn loopt, samengevat, van de Firth of Clyde bij Greenock naar de Firth of Tay en de Noordzee.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup><sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Op de kaart van de Scotch Whisky Association (SWA) uit 2025 staan in Lowland 23 distilleerderijen.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Daaronder zijn oude namen als Auchentoshan en Glenkinchie, en een heropende als Rosebank.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> In deze gids lees je wat de naam wettelijk betekent, wie er stookt en welke misverstanden er rond de streek bestaan.</p>","html":"<h2>Wat de wet zegt</h2><p>De naam 'Lowland' mag alleen op <span class=\"wl\" data-n=\"Scotch Whisky\">Scotch Whisky</span> die in het gebied gedistilleerd is.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Bij een mengsel moet alle whisky erin daar gedistilleerd zijn.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Verwarrend gelijkende namen zijn verboden.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> De route van de scheidslijn hebben we uit een kopie van de wettekst; de geldende versie moeten we nog woord voor woord nalezen.</p><h2>Wie er stookt</h2><ul><li><b><span class=\"wl\" data-n=\"Auchentoshan\">Auchentoshan</span></b>, bij Glasgow, begon volgens de producent in 1817 als Duntocher Distillery van John Bulloch.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> In 1823 kwam er een legale vergunning en in 1834 de naam Auchentoshan.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Sinds 1994 is Suntory eigenaar.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> In de Tweede Wereldoorlog verwoestte een Duits bombardement een van de warehouses.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> De eigenaar noemt drievoudige distillatie als kenmerk.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Distilleren is alcohol scheiden en zuiveren door te verhitten; drievoudig betekent dat dat drie keer gebeurt.</li><li><b><span class=\"wl\" data-n=\"Glenkinchie\">Glenkinchie</span></b>, bij Pencaitland in East Lothian, is van Diageo.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Volgens Diageo werd hij in 1825 opgericht als Milton Distillery door de broers John en George Rate, en in 1837 hernoemd tot Glenkinchie.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Kom je 1837 tegen als oprichtingsjaar, dan is dat dus eigenlijk het jaar van de naamswijziging. De producent noemt twee stills (distilleerketels), waarvan de wash still alleen al zo'n 32.000 liter bevat.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup></li><li><b>Rosebank</b> distilleert sinds juni 2023 weer; de formele heropening was in juni 2024.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> De oorspronkelijke drie stills waren gesloopt en zijn nagebouwd.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Volgens het vakblad was en is Rosebank een ongeturfde, drievoudig gedistilleerde Lowland single malt.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup></li></ul><p>Verder staan op de SWA-lijst onder meer Ailsa Bay, Annandale, Bladnoch, Daftmill, Kingsbarns, Lindores Abbey en Lochlea.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Over die distilleerderijen staat nog weinig in onze kennisbank.</p><h2>Misverstanden</h2><ul><li><i>\"Auchentoshan is de enige Schotse distilleerderij die alles drievoudig distilleert.\"</i> Dat klopt niet. Er zijn meer distilleerderijen die drievoudig distilleren; Rosebank is er een.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Auchentoshan is er wel bekend om.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></li><li><i>\"Uit 'Lowland' kun je de smaak afleiden.\"</i> De wet koppelt geen smaak aan de regio.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Wij hebben ook geen onafhankelijke bron die een typische Lowland-smaak onderbouwt. Zoek je op smaak, gebruik dan het smaakfilter.</li></ul><h2>Interessant om te weten</h2><p>De oudst bekende Schotse vermelding van aqua vitae staat in een Exchequer Roll uit 1494.<sup class=\"fn\"><a href=\"#bn-10\">10</a></sup> Daarin krijgt <span class=\"wl\" data-n=\"John Cor\">John Cor</span>, monnik van Lindores Abbey, acht 'bolls' graan om aqua vitae te maken.<sup class=\"fn\"><a href=\"#bn-10\">10</a></sup> Het archief noemt dit de vroegst bekende verwijzing naar whisky.<sup class=\"fn\"><a href=\"#bn-10\">10</a></sup> Dat is een interpretatie: wat er toen gemaakt werd, weten we niet, en het is niet hetzelfde als whisky volgens de huidige regels. Of de distilleerderij Lindores Abbey op dezelfde plek staat als de abdij uit 1494, hebben we nog niet uitgezocht.</p><h2>Nog niet uitgezocht</h2><ul><li>Hoe de Lowland-traditie historisch is ontstaan.</li><li>Of Glenkinchie twee of drie keer distilleert. De bronnen wijzen op twee keer, maar zeggen het niet letterlijk; Jack noemde drievoudig.</li><li>Of alle 23 namen op de SWA-kaart nu actief zijn.</li><li>Waar de distilleerderij Lindores Abbey precies staat ten opzichte van de oude abdij.</li></ul>","bronnen":[{"n":"Scotch Whisky Regulations 2009","t":"The Scotch Whisky Regulations 2009 (SI 2009/2890)","o":"UK Government","q":"A","u":"https://www.legislation.gov.uk/uksi/2009/2890","j":"2009"},{"n":"SWR 2009 - kopie Clydesdale","t":"The Scotch Whisky Regulations 2009 — kopie van de SI-tekst (Clydesdale)","o":"Clydesdale (herpublicatie van SI 2009/2890)","q":"A","u":"https://www.clydesdale.se/press/SWR2009Guidance.pdf","j":"2009-11-23"},{"n":"Scotch Whisky Technical File 2019","t":"Technical File for Scotch Whisky (juni 2019)","o":"UK Government (Defra)","q":"A","u":"https://assets.publishing.service.gov.uk/media/5fd36667e90e07662ed92c85/Scotch_Whisky_Technical_File_-_June_2019.pdf","j":"2019-06"},{"n":"SWA - Big Map of Scotch Whisky 2025","t":"Big Map of Scotch Whisky (editie juli 2025)","o":"Scotch Whisky Association","q":"A","u":"https://www.scotch-whisky.org.uk/media/2492/big-map-of-scotch-whisky-scotch-whisky-association-2025.pdf","j":"2025-07"},{"n":"Auchentoshan - Our history","t":"Our History — Auchentoshan","o":"Auchentoshan (Suntory Global Spirits)","q":"D","u":"https://www.auchentoshan.com/our-history","j":""},{"n":"Suntory Global Spirits - Our Locations","t":"Our Locations — Suntory Global Spirits","o":"Suntory Global Spirits","q":"D","u":"https://www.suntoryglobalspirits.com/about-us/our-locations","j":""},{"n":"Malts.com - Glenkinchie","t":"Glenkinchie Distillery — Malts.com","o":"Diageo","q":"D","u":"https://www.malts.com/en-gb/distilleries/glenkinchie","j":""},{"n":"Malts.com - Glenkinchie 2022 Distillers Edition","t":"Glenkinchie 2022 Distillers Edition Single Malt Scotch Whisky, 70cl","o":"Diageo (Malts.com)","q":"D","u":"https://www.malts.com/en/products/glenkinchie-2022-distillers-edition-single-malt-scotch-whisky-70cl","j":"ONBEKEND"},{"n":"SLTN 2024 - Rosebank distillery reopens","t":"Return of the king as long-dormant Rosebank distillery reopens","o":"Scottish Licensed Trade News","q":"C","u":"https://sltn.co.uk/2024/06/07/return-of-the-king-as-long-dormant-rosebank-distillery-reopens/","j":"2024-06-07"},{"n":"ScotlandsPeople - Exchequer Roll 1494","t":"First reference to whisky, 1494","o":"ScotlandsPeople (National Records of Scotland)","q":"A","u":"https://www.scotlandspeople.gov.uk/image-library/7197","j":""}],"kennis":["Lowland","Highland","Schotland","Scotch Whisky","Auchentoshan","Glenkinchie","Exchequer Roll 1494","John Cor","Redactiebesluiten Jack"]},"speyside":{"id":"speyside","soort":"streek","t":"Speyside: een wettelijke regio binnen de Highlands","k":"Speyside is een van de drie wettelijk beschermde whiskyregio's van Schotland. De SWA-kaart van 2025 telt er 51 distilleerderijen, waaronder Glenlivet, Glenfarclas, Macallan en Glenfiddich.","lt":"5","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Speyside is een van de drie wettelijk beschermde whiskyregio's van Schotland, naast Highland en Lowland.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het gebied ligt in Moray en in Badenoch and Strathspey.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Op de kaart van de Scotch Whisky Association (SWA) uit 2025 staan er 51 distilleerderijen, van de 151 in heel Schotland.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Daaronder zijn bekende namen als Glenlivet, Glenfarclas, Macallan en Glenfiddich.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Wettelijk ligt Speyside binnen het Highland-gebied, en dat zie je soms terug op het etiket.</p>","html":"<h2>Wat de wet zegt</h2><p>De Scotch Whisky Regulations 2009 omschrijven Speyside als een aantal 'wards' (bestuurlijke wijken) van Moray Council plus de ward Badenoch and Strathspey van Highland Council.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> De naam 'Speyside' mag alleen op <span class=\"wl\" data-n=\"Scotch Whisky\">Scotch Whisky</span> die daar gedistilleerd is.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Bij een mengsel moet alle whisky erin uit Speyside komen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Speyside én Highland</h2><p>Hier zit een bekende verwarring. De wet definieert Highland als alles ten noorden van de Highland-Lowland-lijn.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Speyside ligt ten noorden van die lijn. In de praktijk valt Speyside dus ook binnen 'Highland', al zegt de wet dat niet met zoveel woorden. <span class=\"wl\" data-n=\"Glenfarclas\">Glenfarclas</span> maakt daar gebruik van: de distilleerderij staat op de SWA-kaart bij Speyside, maar noemt haar whisky 'Highland Single Malt'.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Op Whiskysite behandelen we Speyside als eigen streek. Producenten die zelf 'Highland' op het etiket zetten, noemen we als uitzondering.</p><h2>Wie er stookt</h2><ul><li><b><span class=\"wl\" data-n=\"Glenlivet\">Glenlivet</span></b>: in 1824 kreeg <span class=\"wl\" data-n=\"George Smith\">George Smith</span> een vergunning, volgens de producent als eerste legale distillateur in de parochie Glenlivet.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup><sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> Een naslagwerk bevestigt 'eerste in de regio'.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Dat volgde op de <span class=\"wl\" data-n=\"Excise Act 1823\">Excise Act 1823</span>. In 1884 kreeg zijn zoon John Gordon Smith via de rechter gedaan dat alleen deze distilleerderij 'The Glenlivet' mocht heten.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup><sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> In die tijd zetten veel distilleerderijen 'Glenlivet' in hun naam.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Eigenaar is nu Chivas Brothers (Pernod Ricard).<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup></li><li><b><span class=\"wl\" data-n=\"Glenfarclas\">Glenfarclas</span></b>: volgens de Schotse erfgoedinventaris begon het distilleren hier in 1836.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Sinds 1865 is de distilleerderij van de familie Grant.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup><sup class=\"fn\"><a href=\"#bn-4\">4</a></sup></li><li><b><span class=\"wl\" data-n=\"Macallan\">Macallan</span></b>: Edrington vierde in 2024 het 200-jarig bestaan.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> In 2018 opende er een nieuwe distilleerderij, na drieënhalf jaar bouwen.<sup class=\"fn\"><a href=\"#bn-10\">10</a></sup></li><li><b><span class=\"wl\" data-n=\"Aberlour\">Aberlour</span></b>: de eigenaar noemt 1879 als oprichtingsjaar.<sup class=\"fn\"><a href=\"#bn-11\">11</a></sup> De erfgoedinventaris noemt 1826, met herbouw in 1879–80 door James Fleming.<sup class=\"fn\"><a href=\"#bn-12\">12</a></sup> Beide jaartallen kunnen kloppen: het ene gaat over de naam, het andere over de huidige distilleerderij. Dat is nog niet zeker.</li><li><b><span class=\"wl\" data-n=\"Glenfiddich\">Glenfiddich</span></b> en <b><span class=\"wl\" data-n=\"Balvenie\">Balvenie</span></b>, allebei in Dufftown, zijn gebouwd door William Grant en nog altijd van William Grant &amp; Sons.<sup class=\"fn\"><a href=\"#bn-13\">13</a></sup><sup class=\"fn\"><a href=\"#bn-14\">14</a></sup> Glenfiddich stookte volgens de producent zijn eerste spirit op eerste kerstdag 1887.<sup class=\"fn\"><a href=\"#bn-13\">13</a></sup> Bij Balvenie noemt de eigenaar zowel 1892 (opening) als 1893 (eerste distillatie).<sup class=\"fn\"><a href=\"#bn-14\">14</a></sup><sup class=\"fn\"><a href=\"#bn-15\">15</a></sup></li></ul><p>Van een aantal andere distilleerderijen weten we vooralsnog alleen de eigenaar. Bij Chivas Brothers horen onder meer <span class=\"wl\" data-n=\"Allt A&#x27;Bhainne\">Allt A'Bhainne</span>, <span class=\"wl\" data-n=\"Braeval\">Braeval</span>, <span class=\"wl\" data-n=\"Dalmunach\">Dalmunach</span>, <span class=\"wl\" data-n=\"Glen Keith\">Glen Keith</span>, <span class=\"wl\" data-n=\"Glenburgie\">Glenburgie</span>, <span class=\"wl\" data-n=\"Glentauchers\">Glentauchers</span>, <span class=\"wl\" data-n=\"Longmorn\">Longmorn</span>, <span class=\"wl\" data-n=\"Miltonduff\">Miltonduff</span> en <span class=\"wl\" data-n=\"Strathisla\">Strathisla</span>.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Diageo heeft onder meer <span class=\"wl\" data-n=\"Dufftown\">Dufftown</span> en <span class=\"wl\" data-n=\"Glendullan\">Glendullan</span>.<sup class=\"fn\"><a href=\"#bn-16\">16</a></sup> Van John Dewar &amp; Sons (Bacardi) zijn <span class=\"wl\" data-n=\"Aultmore\">Aultmore</span> en <span class=\"wl\" data-n=\"Craigellachie\">Craigellachie</span>.<sup class=\"fn\"><a href=\"#bn-17\">17</a></sup> Inver House heeft <span class=\"wl\" data-n=\"Balmenach\">Balmenach</span>, <span class=\"wl\" data-n=\"Knockdhu\">Knockdhu</span> en <span class=\"wl\" data-n=\"Speyburn\">Speyburn</span>.<sup class=\"fn\"><a href=\"#bn-18\">18</a></sup> <span class=\"wl\" data-n=\"Glenrothes\">Glenrothes</span> hoort bij Edrington, <span class=\"wl\" data-n=\"Tamnavulin\">Tamnavulin</span> bij Whyte &amp; Mackay.<sup class=\"fn\"><a href=\"#bn-19\">19</a></sup><sup class=\"fn\"><a href=\"#bn-20\">20</a></sup></p><h2>Wat je wel en niet uit 'Speyside' kunt afleiden</h2><p>De naam zegt waar de whisky gedistilleerd is.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Een smaak koppelt de wet er niet aan.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Wij hebben nog geen onafhankelijke bron die een typische Speyside-smaak onderbouwt. Zoek je op smaak, gebruik dan het smaakfilter.</p><h2>Een verhaal, geen bewezen feit</h2><p>Over Glenlivet wordt verteld dat koning George IV in 1822 alleen Glenlivet wilde drinken. Een ooggetuige, Elizabeth Grant, schreef later op dat een kamerheer daarom overal 'pure Glenlivet' zocht.<sup class=\"fn\"><a href=\"#bn-21\">21</a></sup> Het ging toen om illegaal gestookte whisky uit de vallei, niet om de distilleerderij.<sup class=\"fn\"><a href=\"#bn-21\">21</a></sup> Die bestond legaal pas vanaf 1824.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup></p><h2>Nog niet uitgezocht</h2><ul><li>Hoe Speyside als whiskystreek is ontstaan.</li><li>Of alle 51 namen op de SWA-kaart nu actief zijn.</li><li>Het precieze oprichtingsjaar van Aberlour (1826 of 1879) en van Glenfarclas met een primaire bron.</li></ul>","bronnen":[{"n":"Scotch Whisky Regulations 2009","t":"The Scotch Whisky Regulations 2009 (SI 2009/2890)","o":"UK Government","q":"A","u":"https://www.legislation.gov.uk/uksi/2009/2890","j":"2009"},{"n":"Scotch Whisky Technical File 2019","t":"Technical File for Scotch Whisky (juni 2019)","o":"UK Government (Defra)","q":"A","u":"https://assets.publishing.service.gov.uk/media/5fd36667e90e07662ed92c85/Scotch_Whisky_Technical_File_-_June_2019.pdf","j":"2019-06"},{"n":"SWA - Big Map of Scotch Whisky 2025","t":"Big Map of Scotch Whisky (editie juli 2025)","o":"Scotch Whisky Association","q":"A","u":"https://www.scotch-whisky.org.uk/media/2492/big-map-of-scotch-whisky-scotch-whisky-association-2025.pdf","j":"2025-07"},{"n":"Glenfarclas - Family","t":"Family — Glenfarclas","o":"J. & G. Grant","q":"D","u":"https://glenfarclas.com/family/","j":""},{"n":"Oxford Companion to Spirits and Cocktails - The Glenlivet","t":"The Glenlivet — The Oxford Companion to Spirits & Cocktails","o":"Oxford University Press","q":"B","u":"https://www.spiritsanddistilling.com/dictionary/acref-9780199311132-e-129","j":"2021"},{"n":"Glenlivet - Our story","t":"Our Story — The Glenlivet","o":"The Glenlivet (Chivas Brothers)","q":"D","u":"https://www.theglenlivet.com/en/our-story/","j":""},{"n":"Chivas Brothers - About","t":"About — Chivas Brothers","o":"Chivas Brothers Ltd (Pernod Ricard)","q":"D","u":"https://www.chivasbrothers.com/about/","j":""},{"n":"Canmore - Glenfarclas Distillery","t":"Glenfarclas Distillery (Canmore site 16323)","o":"Canmore / RCAHMS (Historic Environment Scotland)","q":"B","u":"https://canmore.org.uk/site/16323","j":""},{"n":"Edrington 2024 - The Macallan 200 years young","t":"The Macallan — 200 years young","o":"Edrington","q":"D","u":"https://www.edrington.com/en/brands-news/the-macallan-200-years-young","j":"2024-01-11"},{"n":"Edrington 2018 - Annual Report Operations","t":"Annual Report 2018 - Operations","o":"Edrington","q":"A","u":"https://www.edrington.com/en/annual-report-2018/operations","j":"2018"},{"n":"Chivas Brothers - Aberlour","t":"Aberlour — Chivas Brothers","o":"Chivas Brothers","q":"D","u":"https://chivasbrothers.com/our-brands/aberlour","j":""},{"n":"Canmore - Aberlour Distillery","t":"Aberlour, Aberlour Distillery (Canmore site 16366)","o":"Historic Environment Scotland (Canmore)","q":"B","u":"https://canmore.org.uk/site/16366","j":""},{"n":"Glenfiddich - Our story","t":"Our Story — Glenfiddich","o":"William Grant & Sons","q":"D","u":"https://www.glenfiddich.com/our-story","j":""},{"n":"William Grant - We","t":"We — William Grant & Sons","o":"William Grant & Sons","q":"D","u":"https://www.williamgrant.com/gb/we/","j":""},{"n":"William Grant - The Balvenie story","t":"Unique among single malts: The Balvenie","o":"William Grant & Sons","q":"D","u":"https://www.williamgrant.com/gb/stories/the-balvenie-the-most-handcrafted-of-single-malts/","j":""},{"n":"Diageo - Our Scotch Whisky Portfolio","t":"Our Scotch Whisky Portfolio","o":"Diageo plc","q":"D","u":"https://www.diageo.com/en/our-brands/scotch-whisky","j":""},{"n":"Bacardi 2014 - Last Great Malts","t":"John Dewar & Sons launches Last Great Malts collection","o":"Bacardi Limited","q":"D","u":"https://www.bacardilimited.com/media/news-archive/john-dewar-sons-launches-last-great-malts-collection-new-expressions-and-never-before-released-single-malts/","j":"2014-09-24"},{"n":"International Beverage - Our History","t":"Our history — International Beverage","o":"International Beverage Holdings (ThaiBev)","q":"D","u":"https://www.interbevgroup.com/our-group/our-history","j":""},{"n":"Edrington - Our Company","t":"Our Company — Edrington","o":"Edrington","q":"D","u":"https://www.edrington.com/en/our-company","j":""},{"n":"Whyte & Mackay - Locations","t":"Locations — Whyte & Mackay","o":"Whyte & Mackay","q":"D","u":"https://careers.whyteandmackay.com/locations","j":""},{"n":"Bottle Imp 2016 - Whisky the spirit of Scottish national identity","t":"Whisky: The Spirit of Scottish National Identity","o":"The Bottle Imp (Association for Scottish Literature)","q":"B","u":"https://www.thebottleimp.org.uk/2016/04/whisky-the-spirit-of-scottish-national-identity/","j":"2016-04"}],"kennis":["Speyside","Highland","Schotland","Scotch Whisky","Glenlivet","Glenfarclas","Macallan","Aberlour","Glenfiddich","Balvenie","Excise Act 1823","Whiskybedrijven Schotland","Redactiebesluiten Jack"]}},"verzamel":{"distillatiejaar":{"id":"distillatiejaar","soort":"verzamel","t":"Op distillatiejaar: wat een jaartal op het etiket betekent","k":"Sommige flessen noemen het jaar waarin de whisky is gestookt. Voor Scotch mag dat alleen samen met een tweede gegeven. Zo lees je zo'n etiket.","lt":"3","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Op veel oude flessen staat een jaartal: het jaar waarin de whisky is gedistilleerd. Dat heet het distillatiejaar, of in het Engels vaak 'vintage'. Voor Scotch is wettelijk geregeld hoe dat jaartal op het etiket mag staan.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In deze voorselectie binnen Rare &amp; Old vind je flessen gesorteerd op distillatiejaar. Deze gids legt uit wat dat jaartal zegt, wat het niet zegt, en hoe je er een fles mee kunt kiezen, bijvoorbeeld uit je geboortejaar.</p>","html":"<h2>De regel voor Scotch</h2><p>Een distillatiejaar mag op Scotch alleen staan samen met het bottelingsjaar, de rijpingsduur of de leeftijd.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Dat tweede gegeven moet in hetzelfde gezichtsveld staan als het distillatiejaar.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Ook een juridisch commentaar van advocatenkantoor DLA Piper bespreekt deze regel (regulation 12).<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> In de praktijk betekent 'hetzelfde gezichtsveld': je ziet beide gegevens tegelijk, zonder de fles te draaien. Dat is onze uitleg; de precieze juridische invulling hebben we niet nagelezen.</p><p>Staat er naast het distillatiejaar ook een leeftijd, dan geldt de gewone leeftijdsregel. De leeftijd verwijst naar de jongste whisky in de fles.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Dezelfde regel van de jongste component geldt in de hele EU.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup></p><h2>Wat een distillatiejaar wel en niet zegt</h2><p>Het distillatiejaar vertelt wanneer de spirit is gestookt. Het zegt niet wanneer de whisky is gebotteld. Daarvoor heb je het tweede gegeven op het etiket nodig.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Met distillatiejaar en bottelingsjaar kun je zelf ongeveer uitrekenen hoe oud de whisky is. Dat is een benadering: de jaartallen zeggen niets over de precieze maanden.</p><p>Een distillatiejaar zegt ook niets over de smaak. Twee flessen uit hetzelfde jaar kunnen heel verschillend zijn, bijvoorbeeld door een ander vat of een andere rijpingsduur.</p><h2>Een fles uit je geboortejaar kiezen</h2><p>Zoek je een fles 'uit je geboortejaar', dan kijk je naar het distillatiejaar. Dat is het jaar waarin de whisky is gestookt. Het bottelingsjaar ligt vaak tientallen jaren later; in Rare &amp; Old gaat het om flessen van dertig jaar en ouder. Dat is een manier van kiezen, geen belofte: het jaartal zegt iets over het moment van stoken, niet over hoe de whisky smaakt of wat hij waard is.</p><h2>Nog niet uitgezocht</h2><ul><li>Of een distillatiejaar betekent dat álle whisky in de fles in dat jaar is gestookt. Onze samenvatting van de Scotch-regels zegt daar niets over.</li><li>Welke regels gelden voor een distillatiejaar op whisky buiten Schotland, zoals in de EU of de VS.</li><li>Wat 'hetzelfde gezichtsveld' juridisch precies inhoudt.</li></ul>","bronnen":[{"n":"Scotch Whisky Regulations 2009","t":"The Scotch Whisky Regulations 2009 (SI 2009/2890)","o":"UK Government","q":"A","u":"https://www.legislation.gov.uk/uksi/2009/2890","j":"2009"},{"n":"DLA Piper 2024 - Scotch whisky labelling and bottling","t":"Scotch whisky – labelling and bottling","o":"DLA Piper","q":"C","u":"https://www.dlapiper.com/en/insights/topics/whisky-law-insights/2024/scotch-whisky-labelling-and-bottling","j":"2024-09-19"},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"}],"kennis":["Rijping","Scotch Whisky","NAS"]},"oude-grain":{"id":"oude-grain","soort":"verzamel","t":"Oude grain whisky: wat single grain is, en wie het stookt","k":"Single grain Scotch is wettelijk een restcategorie: alles van één distilleerderij wat geen single malt of blend is. Wat dat betekent, en welke graandistilleerderijen we kennen.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>In Schotland is single grain een wettelijke categorie, maar wel een bijzondere: hij wordt omschreven door wat hij níet is.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Grain whisky is bovendien een vast bestanddeel van blended Scotch. In deze voorselectie binnen Rare &amp; Old vind je grain whisky's van dertig jaar en ouder. Deze gids legt uit wat grain whisky is, welke graandistilleerderijen onze kennisbank kent, en welke vragen nog openstaan.</p>","html":"<h2>Wat is grain whisky?</h2><p>Een algemene Europese definitie van 'grain whisky' bestaat niet. De Europese verordening kent het niet als aparte categorie.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Wel moet elke whisky in de EU gemoute granen bevatten.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Ook voor alle Scotch is gemoute gerst verplicht.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het idee dat grain whisky geen gerst bevat, klopt dus niet.</p><p>In de praktijk gebruiken we 'grain whisky' voor whisky waarvan het beslag naast gemoute gerst ook andere, meestal ongemoute granen bevat. Dat is een omschrijving uit onze kennisbank, geen wettekst. Welke granen in Schotse grain whisky gangbaar zijn, hebben we nog niet met een goede bron vastgelegd.</p><h2>Single grain en blended grain</h2><p><span class=\"wl\" data-n=\"Single Grain Scotch Whisky\">Single Grain Scotch Whisky</span> is Scotch die in één distilleerderij is gedistilleerd en géén single malt en géén blended Scotch is.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Het is dus een restcategorie. De definitie schrijft geen type distilleerketel voor.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> <span class=\"wl\" data-n=\"Blended Grain Scotch Whisky\">Blended Grain Scotch Whisky</span> is een blend van twee of meer single grains van meer dan één distilleerderij.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>De kolomketel</h2><p>Grain whisky wordt vaak in verband gebracht met de kolomketel. De <span class=\"wl\" data-n=\"Coffey Still\">Coffey Still</span> is een continue distilleerketel met twee kolommen, de analyser en de rectifier. Aeneas Coffey patenteerde hem in 1830.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Volgens de Oxford Companion was het de eerste commercieel bruikbare continue ketel die geschikt was gemaakt voor graan.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Maar nogmaals: voor single grain Scotch schrijft de wet het type ketel niet voor.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><h2>Grain en blends</h2><p>Blended Scotch bestaat per definitie uit één of meer single malts en één of meer single grains.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens de Scotch Whisky Association is bijna negen op de tien flessen Scotch wereldwijd een blended Scotch.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Dat betekent, als interpretatie: grain whisky zit in het grootste deel van de Scotch die wordt verkocht.</p><h2>Welke graandistilleerderijen we kennen</h2><p>De kaart van de Scotch Whisky Association uit 2025 noemt een aparte groep graandistilleerderijen: Cameronbridge, Girvan, Invergordon, Loch Lomond Grain, North British, Reivers, Starlaw en Strathclyde.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Van drie daarvan heeft onze kennisbank de eigenaar:</p><ul><li><span class=\"wl\" data-n=\"Strathclyde\">Strathclyde</span> is volgens eigen opgave van <span class=\"wl\" data-n=\"Chivas Brothers\">Chivas Brothers</span>.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup></li><li><span class=\"wl\" data-n=\"Girvan\">Girvan</span> is volgens eigen opgave van <span class=\"wl\" data-n=\"William Grant &amp;amp; Sons\">William Grant &amp; Sons</span>.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup></li><li><span class=\"wl\" data-n=\"Invergordon\">Invergordon</span> is volgens eigen opgave van <span class=\"wl\" data-n=\"Whyte &amp;amp; Mackay\">Whyte &amp; Mackay</span>.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup></li></ul><p>Over hun geschiedenis en werkwijze weten we nog niets met bron.</p><h2>Waarom zie je oude grain vaak bij onafhankelijke bottelaars?</h2><p>Dat hebben we nog niet uitgezocht. We laten het hier daarom als open vraag staan.</p><h2>Nog niet uitgezocht</h2><ul><li>Waarom oude grain whisky vaak via onafhankelijke bottelaars op de markt zou komen.</li><li>Welke granen in Schotse grain whisky gangbaar zijn.</li><li>Geschiedenis, oprichting en werkwijze van de graandistilleerderijen; Cameronbridge, North British en de andere hebben nog geen eigen notitie.</li><li>Hoe groot het aandeel grain whisky in blends is.</li></ul>","bronnen":[{"n":"Scotch Whisky Regulations 2009","t":"The Scotch Whisky Regulations 2009 (SI 2009/2890)","o":"UK Government","q":"A","u":"https://www.legislation.gov.uk/uksi/2009/2890","j":"2009"},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"Oxford Companion to Spirits and Cocktails - Aeneas Coffey","t":"Coffey, Aeneas — The Oxford Companion to Spirits & Cocktails","o":"Oxford University Press","q":"B","u":"https://www.spiritsanddistilling.com/dictionary/acref-9780199311132-e-1328","j":"2021"},{"n":"SWA - Scotch Whisky FAQs","t":"Scotch Whisky FAQs","o":"Scotch Whisky Association","q":"A","u":"https://www.scotch-whisky.org.uk/discover-scotch/faqs/","j":""},{"n":"SWA - Big Map of Scotch Whisky 2025","t":"Big Map of Scotch Whisky (editie juli 2025)","o":"Scotch Whisky Association","q":"A","u":"https://www.scotch-whisky.org.uk/media/2492/big-map-of-scotch-whisky-scotch-whisky-association-2025.pdf","j":"2025-07"},{"n":"Chivas Brothers - About","t":"About — Chivas Brothers","o":"Chivas Brothers Ltd (Pernod Ricard)","q":"D","u":"https://www.chivasbrothers.com/about/","j":""},{"n":"William Grant - We","t":"We — William Grant & Sons","o":"William Grant & Sons","q":"D","u":"https://www.williamgrant.com/gb/we/","j":""},{"n":"Whyte & Mackay - Locations","t":"Locations — Whyte & Mackay","o":"Whyte & Mackay","q":"D","u":"https://careers.whyteandmackay.com/locations","j":""}],"kennis":["Grain whisky","Single Grain Scotch Whisky","Blended Grain Scotch Whisky","Coffey Still","Blending","Strathclyde","Girvan","Invergordon"]},"single-cask":{"id":"single-cask","soort":"verzamel","t":"Single casks van onafhankelijke bottelaars: wat het etiket wel en niet belooft","k":"Single cask, cask strength, koudfiltratie, kleurstof: welke van deze termen wettelijk vastliggen en welke niet. En wat een onafhankelijke bottelaar is.","lt":"5","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Op flessen van onafhankelijke bottelaars staan vaak termen als single cask en cask strength. Klinkt officieel, maar niet al die termen liggen wettelijk vast. In deze voorselectie binnen Rare &amp; Old vind je single casks van dertig jaar en ouder. Deze gids legt uit wat een onafhankelijke bottelaar is, wat single cask en cask strength betekenen, en hoe het zit met koudfiltratie en kleurstof. Zo weet je wat je op het etiket wel en niet kunt aflezen.</p>","html":"<h2>Wat is een onafhankelijke bottelaar?</h2><p>Een onafhankelijke bottelaar (independent bottler) bottelt whisky onder een eigen naam, terwijl die whisky bij een distilleerderij is gestookt. Dat is onze werkomschrijving; een wettelijke definitie hebben we niet gevonden. Een voorbeeld is <span class=\"wl\" data-n=\"That Boutique-y Whisky Company\">That Boutique-y Whisky Company</span>. Master of Malt lanceerde dat label in 2012 met bottelingen van onder meer Ardbeg, The Macallan, Caperdonich en Port Ellen.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> Volgens Master of Malt zelf was de reden dat het geen manier had om single malts van genoemde distilleerderijen uit te brengen.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup></p><h2>Single cask</h2><p>Single cask betekent in het gangbare gebruik dat alle flessen uit één vat komen, zonder menging met andere vaten.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> De term staat niet in de Europese verordening en niet in de Scotch-regels.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Er is dus geen wettelijke definitie. Er zijn ook verhalen over flessen die als single cask werden verkocht, maar uit meerdere vaten waren samengevoegd en daarna in één vat nagerijpt.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Dat rust op een zwakke bron. In de praktijk betekent dit: wat single cask precies inhoudt, hangt af van de bottelaar.</p><p>Niet verwarren met single malt. 'Single' betekent daar: uit één distilleerderij.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Zie <span class=\"wl\" data-n=\"Single Malt Scotch Whisky\">Single Malt Scotch Whisky</span>.</p><h2>Cask strength</h2><p>Cask strength (vatsterkte) is whisky die na het rijpen niet of nauwelijks met water is verdund. Alleen de Verenigde Staten leggen de term wettelijk vast: de bottelsterkte mag daar hooguit 1% vol. lager zijn dan bij het legen van het vat.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> In de EU en in de Scotch-regels komt cask strength niet voor.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Bij heel lange rijping, drie decennia of meer, kan de sterkte in het vat flink dalen.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Een oude cask-strengthfles heeft dus niet per se een hoog percentage. Met welke sterkte een vat ooit is gevuld, verschilt per distilleerderij.</p><h2>Koudfiltratie</h2><p>Bij koudfiltratie (chill filtration) wordt whisky vóór het bottelen gekoeld en gefilterd. Zo verdwijnen stoffen die bij kou of verdunning troebeling geven, vooral langketenige vetzuren en hun esters.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup><sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Zonder koudfiltratie kan whisky onder ongeveer 46% vol. troebel worden.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup><sup class=\"fn\"><a href=\"#bn-9\">9</a></sup> Het is een optionele techniek, niet wettelijk geregeld.<sup class=\"fn\"><a href=\"#bn-10\">10</a></sup> Wat koudfiltratie met de smaak doet, is niet onafhankelijk onderzocht in onze bronnen.</p><p>Op deze site tonen we koudfiltratie per fles alleen als de producent het vermeldt. Vermeldt de producent niets, dan tonen we niets. We gokken het ook niet op basis van het alcoholpercentage.</p><h2>Kleurstof</h2><p>In de EU en voor Scotch mogen aan whisky alleen water en gewone karamel (<span class=\"wl\" data-n=\"E150a\">E150a</span>) worden toegevoegd. Karamel dient alleen om de kleur aan te passen.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup><sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> In Duitsland moet 'mit Farbstoff' op het etiket staan als een kleurstof is toegevoegd.<sup class=\"fn\"><a href=\"#bn-11\">11</a></sup> Dat dit ook voor karamel geldt, is onze interpretatie. Ook kleurstof tonen we per fles als de producent het vermeldt.</p><h2>Nog niet uitgezocht</h2><ul><li>Een gebronde definitie van 'onafhankelijke bottelaar'.</li><li>Of single cask in de praktijk altijd één vat betekent; daar is alleen een zwakke bron voor.</li><li>Wat koudfiltratie en karamel met de smaak doen.</li></ul>","bronnen":[{"n":"The Spirits Business 2012 - Scotch distilleries feature in Master of Malt range","t":"Scotch distilleries feature in Master of Malt range","o":"The Spirits Business","q":"C","u":"https://www.thespiritsbusiness.com/?p=6216","j":"2012-09-14"},{"n":"Master of Malt 2022 - A short history of That Boutique-y Whisky Company","t":"A short history of That Boutique-y Whisky Company","o":"Master of Malt","q":"D","u":"https://www.masterofmalt.com/blog/post/a-short-history-of-that-boutique-y-whisky-company.aspx","j":"2022-09-27"},{"n":"Wikipedia - Single barrel whiskey","t":"Single barrel whiskey","o":"Wikipedia","q":"E","u":"https://en.wikipedia.org/wiki/Single_barrel_whiskey","j":""},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"Scotch Whisky Regulations 2009","t":"The Scotch Whisky Regulations 2009 (SI 2009/2890)","o":"UK Government","q":"A","u":"https://www.legislation.gov.uk/uksi/2009/2890","j":"2009"},{"n":"27 CFR 5.87 - Barrel proof","t":"27 CFR 5.87 – Barrel Proof and similar terms","o":"U.S. Government (eCFR / TTB)","q":"A","u":"https://www.ecfr.gov/current/title-27/chapter-I/subchapter-A/part-5/subpart-F/section-5.87","j":""},{"n":"WSET 2026 - From 40 to cask strength","t":"From 40% to cask strength: understanding whisky ABV","o":"Wine & Spirit Education Trust (WSET)","q":"C","u":"https://www.wsetglobal.com/knowledge-centre/blog/2026/from-40-to-cask-strength-understanding-whisky-abv","j":"2026-08-07"},{"n":"Whisky Magazine 2003 - The chill factor","t":"The chill factor","o":"Whisky Magazine","q":"C","u":"https://whiskymag.com/articles/the-chill-factor","j":"2003-09-25"},{"n":"Annandale - Chill filtration","t":"Chill Filtration (technical note)","o":"Annandale Distillery","q":"D","u":"https://www.annandaledistillery.com/technical-notes/chill-filtration/","j":""},{"n":"DLA Piper 2024 - Scotch whisky labelling and bottling","t":"Scotch whisky – labelling and bottling","o":"DLA Piper","q":"C","u":"https://www.dlapiper.com/en/insights/topics/whisky-law-insights/2024/scotch-whisky-labelling-and-bottling","j":"2024-09-19"},{"n":"CVUA Baden-Wuerttemberg 2025 - Merkblatt Spirituosenetiketten","t":"Merkblatt Spirituosenetiketten","o":"Chemische und Veterinäruntersuchungsämter Baden-Württemberg","q":"B","u":"https://www.untersuchungsaemter-bw.de/cloud/portal/Merkblatt_Spirituosenetiketten.pdf","j":"2025-02"}],"kennis":["Single cask","Cask strength","Chill filtration","E150a","That Boutique-y Whisky Company","Single Malt Scotch Whisky"]},"veertig-plus":{"id":"veertig-plus","soort":"verzamel","t":"40 jaar en ouder: wat de leeftijd op het etiket echt zegt","k":"Een leeftijd op het etiket verwijst naar de jongste whisky in de fles. Wat dat betekent bij flessen van veertig jaar en ouder, en wat er in al die jaren in het vat gebeurt.","lt":"4","st":"NEEDS REVIEW","status":"incomplete","bijgewerkt":"2026-10-08","intro":"<p>Een leeftijd op een whiskyfles is geen vrije keuze van de maker. Voor Scotch en in de Europese Unie ligt vast wat een getal als '40 years old' betekent.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> In deze voorselectie binnen Rare &amp; Old vind je flessen met een leeftijd van veertig jaar of meer. Deze gids legt uit wat die leeftijd wettelijk zegt, wat er in veertig jaar in een vat gebeurt, en wat er onderweg verdampt. Waarom zulke flessen zeldzaam zijn, hebben we nog maar gedeeltelijk uitgezocht. Dat staat onderaan.</p>","html":"<h2>Wat '40 jaar' wettelijk betekent</h2><p>Een leeftijd op het etiket verwijst naar de jongste alcoholische component in de fles.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup><sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Voor Scotch wordt die leeftijd in jaren uitgedrukt.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup> In de EU geldt daarbij dat alle rijping onder fiscaal toezicht moet hebben plaatsgevonden.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Dat betekent: in een whisky van veertig jaar zit geen whisky die jonger is dan veertig jaar. Oudere whisky mag er wel in zitten. Dat geldt ook voor een blend.</p><p>Voor <span class=\"wl\" data-n=\"Scotch Whisky\">Scotch Whisky</span> moet de rijping bovendien in Schotland gebeuren, in eiken vaten van maximaal 700 liter.<sup class=\"fn\"><a href=\"#bn-1\">1</a></sup></p><p>Staat er geen leeftijd op het etiket, dan heet dat <span class=\"wl\" data-n=\"NAS\">NAS</span>: no age statement.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Volgens de Edinburgh Whisky Academy zegt het ontbreken van een leeftijd niets over de kwaliteit.<sup class=\"fn\"><a href=\"#bn-3\">3</a></sup> Je weet dan alleen niet hoe oud de jongste whisky is.</p><h2>Wat lange rijping doet</h2><p>Rijping is wettelijk de opslag van een drank in geschikte recipiënten, zoals vaten, zodat natuurlijke reacties hem eigen kenmerken geven.<sup class=\"fn\"><a href=\"#bn-2\">2</a></sup> Een wetenschappelijk overzicht onderscheidt zes mechanismen. Het vat geeft stoffen af, houtmoleculen worden afgebroken, en stoffen uit hout en spirit reageren met elkaar. Ook verdampen vluchtige stoffen door het hout heen.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Hoe groot het effect is en hoeveel tijd het kost, verschilt sterk en hangt vooral af van het type vat.<sup class=\"fn\"><a href=\"#bn-5\">5</a></sup> Ook de voorgeschiedenis van een vat beïnvloedt de samenstelling van de whisky.<sup class=\"fn\"><a href=\"#bn-6\">6</a></sup> In de praktijk betekent dit: veertig jaar zegt iets over de tijd, maar niet precies hoe de whisky smaakt. Het vat bepaalt mee.</p><h2>Wat er verdampt</h2><p>Tijdens de rijping verdampt een deel van de whisky door het vat heen. Dat deel heet de <span class=\"wl\" data-n=\"Angel&#x27;s share\">Angel's share</span>.<sup class=\"fn\"><a href=\"#bn-4\">4</a></sup> Voor Schotland noemt een vakartikel ongeveer 1 à 2% per jaar.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> The Glenlivet noemt zelf ongeveer 2% per jaar.<sup class=\"fn\"><a href=\"#bn-8\">8</a></sup> Of het alcoholpercentage daardoor daalt of stijgt, hangt af van de luchtvochtigheid. Bij vochtige lucht verdampt vooral alcohol, bij droge lucht vooral water.<sup class=\"fn\"><a href=\"#bn-7\">7</a></sup> Bij heel lange rijping, drie decennia of meer, kan de sterkte in het vat flink dalen.<sup class=\"fn\"><a href=\"#bn-9\">9</a></sup></p><h2>Waarom zijn zulke flessen zeldzaam?</h2><p>Uit het bovenstaande volgt één reden, als interpretatie: na tientallen jaren verdamping is er minder whisky over in het vat. Andere redenen, zoals hoeveel whisky er decennia geleden is weggelegd of welke distilleerderijen inmiddels gesloten zijn, heeft onze kennisbank nog niet onderbouwd.</p><h2>Nog niet uitgezocht</h2><ul><li>Waarom flessen van veertig jaar en ouder zeldzaam zijn, behalve door verdamping.</li><li>Hoeveel whisky er na veertig jaar gemiddeld in een vat over is; een betrouwbaar wetenschappelijk cijfer ontbreekt.</li><li>Hoe klimaat en type warehouse de rijping beïnvloeden.</li></ul>","bronnen":[{"n":"Scotch Whisky Regulations 2009","t":"The Scotch Whisky Regulations 2009 (SI 2009/2890)","o":"UK Government","q":"A","u":"https://www.legislation.gov.uk/uksi/2009/2890","j":"2009"},{"n":"Verordening (EU) 2019-787","t":"Verordening (EU) 2019/787 inzake gedistilleerde dranken","o":"Europees Parlement en Raad van de EU","q":"A","u":"https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:02019R0787-20240513","j":"2019-05-17"},{"n":"Edinburgh Whisky Academy 2023 - No Age Statement","t":"Whisky words: No Age Statement (NAS)","o":"Edinburgh Whisky Academy","q":"C","u":"https://www.edinburghwhiskyacademy.com/blogs/definition/whisky-words-no-age-statement-nas","j":"2023-08-16"},{"n":"Mosedale 1995 - Effects of oak wood on maturation","t":"Effects of oak wood on the maturation of alcoholic beverages with particular reference to whisky","o":"Forestry (Oxford University Press)","q":"B","u":"https://academic.oup.com/forestry/article-abstract/68/3/203/598104","j":"1995"},{"n":"Mosedale en Puech 1998 - Wood maturation of distilled beverages","t":"Wood maturation of distilled beverages","o":"Trends in Food Science & Technology (Elsevier)","q":"B","u":"https://www.sciencedirect.com/science/article/pii/S0924224498000247","j":"1998"},{"n":"Piggott e.a. 1993 - Scotch whisky maturation casks with varying histories","t":"Effects on Scotch whisky composition and flavour of maturation in oak casks with varying histories","o":"International Journal of Food Science and Technology","q":"B","u":"https://academic.oup.com/ijfst/article/28/3/303/7867650","j":"1993"},{"n":"Whiskey Wash - Angels share (Hughes)","t":"Whiskey Science: Looking at the Angels' Share","o":"The Whiskey Wash","q":"C","u":"https://thewhiskeywash.com/bourbon/whiskey-science-angels-share/","j":""},{"n":"Glenlivet - Angels share","t":"Whisky Evaporation — What is the Angel's Share?","o":"The Glenlivet (Chivas Brothers)","q":"D","u":"https://www.theglenlivet.com/en/our-community/articles/angels-share-meaning/","j":""},{"n":"WSET 2026 - From 40 to cask strength","t":"From 40% to cask strength: understanding whisky ABV","o":"Wine & Spirit Education Trust (WSET)","q":"C","u":"https://www.wsetglobal.com/knowledge-centre/blog/2026/from-40-to-cask-strength-understanding-whisky-abv","j":"2026-08-07"}],"kennis":["Rijping","Angel's share","NAS","Scotch Whisky","Cask strength"]}}};
